# Language: jac
# from: osp_A_05__mm3_v13
# Help me build a vet-clinic round in Jac. Pets are nodes with a name, species, and whether they need a vaccine today. A vet walker should keep its own list of patient names and count of shots given as it moves from pet to pet; afterwards I want to read those numbers straight off the spawned walker instance and print a summary.
"""Vet-clinic round: walker visits pets, gives vaccines, reports counts."""

node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = True;
}

walker Vet {
    has patients: list[str] = [];
    has shots_given: int = 0;

    can start with Root entry {
        print(f"Vet beginning the round");
        visit [-->];
    }

    can examine with Pet entry {
        self.patients.append(here.name);
        if here.needs_vaccine {
            self.shots_given += 1;
            print(f"Gave vaccine to {here.name} the {here.species}");
            here.needs_vaccine = False;
        } else {
            print(f"{here.name} the {here.species} is already up to date");
        }
        visit [-->];
    }
}

with entry {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True)
        ++> Pet(name="Rex", species="dog", needs_vaccine=True)
        ++> Pet(name="Hopper", species="rabbit", needs_vaccine=False)
        ++> Pet(name="Luna", species="cat", needs_vaccine=True);

    vet = Vet();
    root spawn vet;

    print(f"Round complete: {len(vet.patients)} patients seen, {vet.shots_given} shots given");
    print(f"Patient list: {vet.patients}");
}

# written in jac
# from: osp_A_10__mm3_v27
# I'm writing an order auditor in Jac and need both flavors of early return working side by side. Orders are nodes with an amount, a validity flag, and a fraud flag. Invalid orders should be skipped while the audit continues to later orders, but a flagged-fraud order must halt the whole walk on the spot. Print a line per order showing which action fired.
"""Order auditor: invalid orders are skipped, fraud orders halt the walk."""

node Order {
    has order_id: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has audited: int = 0;

    can start with Root entry {
        print("Order audit begins");
        visit [-->];
    }

    can audit with Order entry {
        action = "";
        if here.fraud {
            action = "HALT";
        } elif not here.valid {
            action = "SKIP";
        } else {
            action = "OK";
        }
        print(f"[{action}] order {here.order_id} amount=${here.amount:.2f}");
        if here.fraud {
            disengage;
        }
        self.audited += 1;
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    root ++> Order(order_id="A-001", amount=120.50)
        ++> Order(order_id="A-002", amount=80.00, valid=False)
        ++> Order(order_id="A-003", amount=200.00, fraud=True)
        ++> Order(order_id="A-004", amount=55.25);
    root spawn OrderAuditor();
    print("Audit complete");
}

# Language: Jac
# from: osp__Concorda-Sailing__knowledge-graph__56__dossiers
"""Concorda-Sailing/knowledge-graph#56 — dossier outbound dependency reach."""

node Dossier {
    has name: str;
}

edge Outbound {}

obj DossierGraph {
    has nodes: dict[str, Dossier] = {};
}

walker OutboundWalk {
    has claimed: dict[str, bool] = {};
    has reached: list[str] = [];

    can step with Dossier entry {
        if here.name in self.claimed { skip; }
        self.claimed[here.name] = True;
        self.reached.append(here.name);
        visit [->:Outbound:->][?:Dossier];
    }
}

def load_dossiers(nodes: list[str], edges: list[tuple[str, str]]) -> DossierGraph {
    g = DossierGraph();
    for n in nodes {
        nd = Dossier(name=n);
        root ++> nd;
        g.nodes[n] = nd;
    }
    for (src, dst) in edges {
        s = g.nodes.get(src, None);
        d = g.nodes.get(dst, None);
        if s is not None and d is not None { s +>:Outbound:+> d; }
    }
    return g;
}

def outbound_reach(store: DossierGraph, `node: str) -> list[str] {
    nd = store.nodes.get(`node, None);
    if nd is None { return []; }
    w = nd spawn OutboundWalk(claimed={}, reached=[]);
    out: list[str] = [];
    for n in w.reached {
        if n != `node { out.append(n); }
    }
    return sorted(out);
}

# Language: jac
# from: osp_C_59__mm3_v39
# Our build system's dependency graph contains diamonds: shared libraries are needed by several modules. Count total build minutes across all tasks, making sure a task reachable by multiple paths is audited exactly once even though traversal reaches it more than once.
"""Diamond dependency audit: each task is counted once even when multiple paths reach it."""

node Task {
    has title: str = "";
    has minutes: int = 0;
    has audited: bool = False;
}

walker Auditor {
    has total_minutes: int = 0;
    has visited_titles: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        if not here.audited {
            here.audited = True;
            self.total_minutes = self.total_minutes + here.minutes;
            self.visited_titles = self.visited_titles + [here.title];
            print(f"Audited '{here.title}' (+{here.minutes} min)");
        } else {
            print(f"Skipped '{here.title}' (already counted)");
        }
        visit [-->];
    }
}

with entry {
    # Diamond topology:
    #   root -> compile  ->+-> link_tests  (diamond apex)
    #                         +-> link_app
    #   root -> bundle_lib (shared library, reached via both link_* paths)
    compile = Task(title="compile", minutes=10);
    link_tests = Task(title="link_tests", minutes=5);
    link_app = Task(title="link_app", minutes=5);
    bundle_lib = Task(title="bundle_lib", minutes=3);

    root ++> compile ++> link_tests;
    root ++> link_tests ++> bundle_lib;
    root ++> link_app;
    root ++> link_app ++> bundle_lib;

    auditor = Auditor();
    root spawn auditor;

    print(f"\nTotal build minutes (deduplicated): {auditor.total_minutes}");
    print(f"Tasks audited in order: {auditor.visited_titles}");
}

# Jac lang
# from: osp_A_12__composer_v50
# I'm doing a warehouse stock take in Jac. Stock items are nodes with a SKU and a quantity. A counter walker should report each shelf quantity during its sweep, and the main block should read result.reports afterwards to print the per-item counts, the total units in the warehouse, and the smallest shelf count.
"""Warehouse stock take: model stock items as shelf nodes and sweep with a counter walker."""

node StockItem {
    has sku: str = "";
    has quantity: int = 0;
}

walker Counter {
    can start with Root entry {
        visit [-->];
    }

    can count with StockItem entry {
        print(f"Shelf report — {here.sku}: {here.quantity} units");
        report here;
        visit [-->];
    }
}

with entry {
    root ++> StockItem(sku="SKU-001", quantity=42)
        ++> StockItem(sku="SKU-002", quantity=17)
        ++> StockItem(sku="SKU-003", quantity=8)
        ++> StockItem(sku="SKU-004", quantity=25);

    result = root spawn Counter();

    total_units = 0;
    smallest_count = None;
    for item in result.reports {
        print(f"{item.sku}: {item.quantity}");
        total_units += item.quantity;
        if smallest_count is None or item.quantity < smallest_count {
            smallest_count = item.quantity;
        }
    }
    print(f"Total units: {total_units}");
    print(f"Smallest shelf count: {smallest_count}");
}

# Language: jac
# from: osp_A_01__composer_v33
# I'm prototyping a tiny library catalog in Jac. Model each book as a node with a title, publication year, and an availability flag — the year should default to 0 when unknown and books should be available by default. Then write a librarian walker that starts at root, walks the shelf, and prints every book with its IN/OUT status.
"""Library catalog: model books as nodes and walk the shelf with a librarian walker."""

node Book {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

walker Librarian {
    has shelf_label: str = "Main";

    can start with Root entry {
        visit [-->];
    }

    can shelve with Book entry {
        status = "IN" if here.available else "OUT";
        print(f"[{status}] {here.title} ({here.year})");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Book(title="Dune", year=1965)
        ++> Book(title="Neuromancer", year=1984)
        ++> Book(title="Circe", year=2018, available=False);
    print(f"Shelving books for Sci-Fi & Fantasy shelf");
    root spawn Librarian(shelf_label="Sci-Fi & Fantasy");
}

