# ----------------------------------------------------------------------
# Edge archetypes (typed — the relationship carries meaning / payload).
# ----------------------------------------------------------------------

edge IdentityMapping {
    # LDAP/Keycloak group -> Ranger role binding; has correlation id.
    has correlation_id: str = "";
}

edge LineageEdge {
    # Source -> downstream dataset lineage with provenance payload.
    has source: str = "";
    has query_job: str = "";
    has confidence: float = 1.0;
    has freshness_ts: int = 0;
    has evidence: str = "";
}

edge PolicyBinding {
    # Policy -> applied resource binding.
    has correlation_id: str = "";
}

# ----------------------------------------------------------------------
# Base node for resources that carry identity-style fields shared by
# Dataset and PIIColumn, so a union ability can read them safely.
# ----------------------------------------------------------------------

node GovernedResource {
    has resource_label: str = "";
}

# ----------------------------------------------------------------------
# Node archetypes.
# ----------------------------------------------------------------------

node Identity {
    has display_name: str = "";
    has group: str = "";
    has auth_id: str = "";
}

node RangerPolicy {
    has policy_name: str = "";
    has decision: str = "deny";
    has classification: str = "";
    has version: int = 1;
    has is_stale: bool = False;
}

node Dataset(GovernedResource) {
    has ns: str = "";
    has table_name: str = "";
    has snapshot_id: int = 0;
}

node PIIColumn(GovernedResource) {
    has column_name: str = "";
    has classification: str = "PII";
    has mask_required: bool = True;
}

# ----------------------------------------------------------------------
# Walker: walks identity -> policies -> datasets -> lineage chain.
# Performs the recursion the issue flags as hand-rolled Python.
# Carries an explicit visited-set (jac 0.36.1 walkers don't dedupe).
# ----------------------------------------------------------------------

walker GovernanceAuditor {
    has auditor_name: str = "audit-1";
    has decisions: list = [];
    has visited_ids: list = [];

    can start with Root entry {
        print(f"=== Governance audit by {self.auditor_name} ===");
        visit [-->];
    }

    can audit_identity with Identity entry {
        marker = id(here);
        if marker in self.visited_ids {
            visit [-->];
            disengage;
        }
        self.visited_ids.append(marker);
        print(f"identity {here.display_name} (group={here.group}, "
              f"auth_id={here.auth_id})");
        self.decisions.append(f"IDENTITY:{here.auth_id}");
        visit [->:IdentityMapping:->] else { disengage; }
    }

    can audit_policy with RangerPolicy entry {
        marker = id(here);
        if marker in self.visited_ids {
            visit [-->];
            disengage;
        }
        self.visited_ids.append(marker);
        stale_tag = "STALE" if here.is_stale else "FRESH";
        verdict = f"POLICY:{here.policy_name}={here.decision} "
                  f"(class={here.classification}, v{here.version}, {stale_tag})";
        print(f"  policy {verdict}");
        self.decisions.append(verdict);
        if here.is_stale and here.decision == "allow" {
            print("    !! stale policy -> refusing auto-allow");
            self.decisions.append(f"REFUSED:{here.policy_name}");
            disengage;
        }
        visit [-->];
    }

    can audit_resource with Dataset | PIIColumn entry {
        marker = id(here);
        if marker in self.visited_ids {
            visit [-->];
            disengage;
        }
        self.visited_ids.append(marker);
        print(f"    resource {here.resource_label}");
        self.decisions.append(f"RESOURCE:{here.resource_label}");
        visit [->:LineageEdge:->] else { disengage; }
    }
}

# ----------------------------------------------------------------------
# Walker: dependency-ordered cascade invalidation. Walks a Dataset and
# recursively invalidates downstream lineage when the snapshot is stale.
# ----------------------------------------------------------------------

walker LineageInvalidator {
    has invalidated_count: int = 0;
    has visited_ids: list = [];

    can start with Root entry {
        visit [-->];
    }

    can invalidate with Dataset entry {
        marker = id(here);
        if marker in self.visited_ids {
            visit [-->];
            disengage;
        }
        self.visited_ids.append(marker);
        here.snapshot_id = 0;
        self.invalidated_count += 1;
        print(f"invalidated dataset {here.ns}.{here.table_name}");
        visit [->:LineageEdge:->] else { disengage; }
    }
}

