"""Gated descendant loads: a layout's load acts as a prerequisite for its children.

Models the SvelteKit 'gate' proposal natively:
- LayoutGroup nodes have a `gated` flag and a `load` step that may redirect.
- Page nodes represent descendant loads that should only start once their
  gated layout ancestors have completed.
- A walker traverses the layout tree top-down, respecting the gate contract:
  nested gated layouts chain sequentially, descendants only run after the
  gate resolves, and a redirect from any gated ancestor aborts descendants.
"""

node LayoutGroup {
    has name: str = "";
    has gated: bool = False;
    has redirects_to: str = "";
    has resolves_user: bool = False;
}

node Page {
    has title: str = "";
    has has_run: bool = False;
}

edge LayoutEdge { has order: int = 0; }

walker LoadRunner {
    has pending: list = [];
    has aborted: bool = False;

    def gate_layout(layout: LayoutGroup) -> bool {
        if layout.redirects_to != "" {
            print(f"redirect -> {layout.redirects_to} (no descendants will load)");
            return False;
        }
        if layout.resolves_user {
            print(f"resolved user in {layout.name}");
        }
        print(f"gate cleared: {layout.name}");
        return True;
    }

    can start with Root entry {
        visit [-->];
    }

    can run_layout with LayoutGroup entry {
        if self.aborted {
            return;
        }
        if here.gated {
            gate_ok = self.gate_layout(here);
            if not gate_ok {
                self.aborted = True;
                return;
            }
        }
        self.pending = self.pending + [here.name];
        visit [-->];
    }

    can run_page with Page entry {
        if self.aborted {
            return;
        }
        here.has_run = True;
        self.pending = self.pending + [here.title];
    }
}

with entry {
    authed = LayoutGroup(name="(authenticated)", gated=True, resolves_user=True);
    inner = LayoutGroup(name="(dashboard)", gated=True);
    root ++> authed ++> inner;

    dashboard_page = Page(title="dashboard");
    settings_page = Page(title="settings");
    inner ++> dashboard_page;
    inner ++> settings_page;

    public_layout = LayoutGroup(name="(public)");
    landing_page = Page(title="landing");
    public_layout ++> landing_page;
    root ++> public_layout;

    runner = LoadRunner();
    authed spawn runner;

    print(f"run order: {runner.pending}");
    print(f"dashboard ran: {dashboard_page.has_run}, settings ran: {settings_page.has_run}, landing ran: {landing_page.has_run}");

    print("--- now with a redirecting gate ---");

    redirect_layout = LayoutGroup(name="(locked)", gated=True, redirects_to="/login");
    child = Page(title="secret");
    redirect_layout ++> child;
    root ++> redirect_layout;

    r2 = LoadRunner();
    redirect_layout spawn r2;
    print(f"run order: {r2.pending}");
    print(f"secret ran: {child.has_run}");
}

