    can start with Root entry {
        print("GapReviewer: walking every discovered gap");
        visit [-->];
    }

    can review with Gap entry {
        candidates = [here ->:WantsFrom:->];
        proposed = [];
        for w in candidates {
            proposed.append(w.title);
