node Override {
    has number: int = 0;
    has title: str = "";
    has layer: str = "";
    has commit: str = "";
    has issue: str = "";
    has direction: str = "";
}

node SchemaLayer {
    has name: str = "";
    has baseline_version: str = "7.0.0";
}

