    can start with Root entry {
        print("Reachable overrides + inherited baseline fields:");
        visit [->:OverrideOf:->];
    }

    can list_override with Override entry {
        print(f"  override #{here.number}: {here.title} -> {here.direction}");
        visit [->:OverrideOf:->];
    }

    can list_inherited with SchemaLayer entry {
        print(f"  inherited from {here.name} baseline {here.baseline_version}");
        visit [-->] else { disengage; }
    }
}

with entry {
    upstream = SchemaLayer(name="cellxgene_schema_7.0.0", baseline_version="7.0.0");
