    has variant: str = "";
}

edge DependsOn {
    # Artifact-to-artifact dependency (POM-level).
}

edge UsesPlugin {
    # Project uses a Compose Compiler plugin.
}

edge CachedAs {
    # A resolved Compose artifact set was cached as a DexCache entry.
}

# ----------------------------------------------------------------------
# Walker: walk the resolved-artifact tree from a Project and rebuild the
# DEX cache. Carries an explicit cycle guard because jac 0.36.1 walkers
# have no built-in once-per-node visitation.
# ----------------------------------------------------------------------

walker RebuildPreviewDex {
    has visited_fingerprints: list[str] = [];
    has compose_fingerprints: list[str] = [];
    has invalidated: bool = False;

    can start with Root entry {
        # Root has no project metadata; just kick off traversal to the Project.
        visit [-->];
