    can enter_project with Project entry {
        print(f"Project: {here.name} (variant={here.variant}, kotlin={here.kotlin_version})");
        print("Triggering Gradle sync to obtain resolved Compose artifacts...");
        visit [->:Resolved:->];
    }

    can traverse_artifacts with Artifact entry {
        # Cycle guard: don't revisit artifacts with the same fingerprint.
        fp = here.fingerprint();
        already_seen = False;
        for seen in self.visited_fingerprints {
            if seen == fp {
                already_seen = True;
