# from: osp_C_41__mm3_v71
# Build a small social graph where some profiles belong to pets rather than people. Write a walker that starts at each person and recommends new friends, but only adult human ones -- pet profiles and minors must never show up in the suggestions. Print how many raw neighbours each person sees versus how many survive the filters.
"""Friend recommendation walker that filters out pets and minors.

Walks a social graph starting from each human adult and reports how many
raw neighbours it sees versus how many survive the adult-human filter.
Pet profiles and minors are excluded from suggestions.
"""

node Profile {
    has name: str = "";
    has age: int = 0;
    has species: str = "human";
}

edge FriendLink {}

walker Recommend {
    can start with Root entry {
        visit [-->];
    }

    can recommend with Profile entry {
        raw = 0;
        good = 0;
        for n in [->:FriendLink:->] {
            raw += 1;
            if n.species == "human" and n.age >= 18 {
                good += 1;
            }
        }
        print(
            f"{here.name}: raw neighbours={raw}, "
            f"adult human suggestions={good}"
        );
        visit [-->] else { disengage; };
    }
}

with entry {
    alice = Profile(name="Alice", age=30);
    bob = Profile(name="Bob", age=25);
    carol = Profile(name="Carol", age=17);
    rex = Profile(name="Rex", age=4, species="dog");
    whiskers = Profile(name="Whiskers", age=3, species="cat");
    dave = Profile(name="Dave", age=40);

    alice +>:FriendLink:+> bob;
    alice +>:FriendLink:+> carol;
    alice +>:FriendLink:+> rex;
    alice +>:FriendLink:+> dave;
    bob +>:FriendLink:+> carol;
    bob +>:FriendLink:+> whiskers;
    bob +>:FriendLink:+> dave;
    dave +>:FriendLink:+> bob;
    dave +>:FriendLink:+> alice;

    root ++> alice;
    root ++> bob;
    root ++> dave;

    root spawn Recommend();
}

