# I'm doing a warehouse stock take in Jac. Stock items are nodes with a SKU and a quantity. A counter walker should report each shelf quantity during its sweep, and the main block should read result.reports afterwards to print the per-item counts, the total units in the warehouse, and the smallest shelf count.
"""Warehouse stock take: model shelves as nodes and walk the warehouse with a counter walker."""

node StockItem {
    has sku: str = "";
    has quantity: int = 0;
}

walker Counter {
    has total: int = 0;
    has smallest: int = 0;
    has seen_first: bool = False;
    has count: int = 0;

    can start with Root entry {
        self.smallest = 0;
        visit [-->] else { disengage; }
    }

    can tally with StockItem entry {
        qty = here.quantity;
        self.total = self.total + qty;
        if self.seen_first {
            if qty < self.smallest {
                self.smallest = qty;
            }
        } else {
            self.smallest = qty;
            self.seen_first = True;
        }
        self.count = self.count + 1;
        print(f"[item {self.count}] sku={here.sku} quantity={qty}");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> StockItem(sku="A-001", quantity=42)
        ++> StockItem(sku="A-002", quantity=15)
        ++> StockItem(sku="A-003", quantity=87)
        ++> StockItem(sku="A-004", quantity=3);

    counter = Counter();
    root spawn counter;

    print("--- stock take summary ---");
    print(f"items counted: {counter.count}");
    print(f"total units:   {counter.total}");
    print(f"smallest qty:  {counter.smallest}");
}

