# I'm marking out a hiking trail in Jac as a chain of plain waypoints between the trailhead and the summit — the waypoints themselves don't need to hold any data at all. Give me a hiker walker that travels the trail and counts how many waypoints it passes, printing each stop number along the way and a completion line once it has passed enough of them.
"""Hiking trail: a chain of plain waypoints between trailhead and summit.

The waypoints carry no payload — they're pure graph topology. A hiker
walker travels the trail, counts each waypoint it passes, prints the
stop number, and emits a completion line once it has enough.
"""

node Waypoint {
    # Pure topology node: no fields, just a stop along the trail.
}

walker Hiker {
    has target: int = 3;
    has count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can hike with Waypoint entry {
        self.count += 1;
        print(f"Stop {self.count}");
        if self.count >= self.target {
            print(f"Summit reached after {self.count} stops!");
            disengage;
        }
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();
    root spawn Hiker(target=4);
}

