# Health-inspect a restaurant kitchen line (grill, fryer, cold prep): check each station's temperature, flagging anything above 40 C as a violation, and separately log every station visit. Both checks must run at every station.
"""Restaurant kitchen line health inspection.

One walker (KitchenInspector) sweeps the line so every station
(Grill, Fryer, ColdPrep) gets both a temperature check (flagging
anything above 40 C as a violation) and a visit log entry.
"""

node Station {
    has name: str = "";
    has temperature: float = 0.0;

    def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

node Grill(Station) {
    has name: str = "";
    has temperature: float = 0.0;

    override def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

node Fryer(Station) {
    has name: str = "";
    has temperature: float = 0.0;

    override def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

node ColdPrep(Station) {
    has name: str = "";
    has temperature: float = 0.0;

    override def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

walker KitchenInspector {
    has violation_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect with Station entry {
        if here.is_violation() {
            self.violation_count += 1;
            print(f"[VIOLATION] {here.name} is {here.temperature} C (>40 C)");
        } else {
            print(f"[OK] {here.name} is {here.temperature} C");
        }
        print(f"[VISIT] Logged visit to {here.name} station");
        visit [-->];
    }
}

with entry {
    root ++> Grill(name="Grill", temperature=180.0)
        ++> Fryer(name="Fryer", temperature=165.0)
        ++> ColdPrep(name="ColdPrep", temperature=4.0);

    inspector = KitchenInspector();
    root spawn inspector;
    print(f"Total violations: {inspector.violation_count}");
}

