# I'm making a tiny dungeon crawler in Jac. Rooms are chained nodes and one special room holds the treasure. A hunter walker should check rooms one by one while counting how many it has seen, and terminate the entire search immediately when it finds the treasure room — rooms past the vault must never be visited.
"""Dungeon crawler: a chain of room nodes, one holds the treasure.

A hunter walker traverses the chain, counts the rooms it inspects,
and disengages the moment it locates the vault so rooms past it are
never visited.
"""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;
    has found_treasure: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can explore with Room entry {
        self.rooms_checked += 1;
        if here.has_treasure {
            self.found_treasure = True;
            print(f"Vault found in '{here.name}' after "
                  f"{self.rooms_checked} room(s) inspected.");
            disengage;
        }
        print(f"Inspected '{here.name}' — empty.");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Foyer")
        ++> Room(name="Antechamber")
        ++> Room(name="Vault", has_treasure=True)
        ++> Room(name="Secret Passage")
        ++> Room(name="Dragons Lair");

    hunter = Hunter();
    root spawn hunter;

    print(f"Hunter report: checked={hunter.rooms_checked}, "
          f"found={hunter.found_treasure}");
}

