    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];

    can start with Root entry {
        print("Weather sweep beginning...");
        visit [-->] else { disengage; }
    }

    can record with Station entry {
        msg = f"Station {here.location}: {here.celsius}°C";
