# A residency-epoch tracker node carries the worldspace's current epoch
# counter. The ReconcileFrame walker reads it; ResidencyChange mutates it.
node ResidencyEpoch {
    has epoch: int = 0;
}

node TerrainBlock {
    has key: str = "";
    has lod_level: int = 0;
    has available: bool = True;
}

node ObjectBlock {
    has key: str = "";
    has lod_level: int = 0;
    has available: bool = True;
}

node FullCell {
    has key: str = "";
    has lod_level: int = 0;
}

node Landscape {
    has immutable: bool = True;
    has name: str = "";
}

edge ResidentIn {
    has since: str = "";
}

edge AdjacentTo {
    has seam_label: str = "";
}

edge HasFull {
    has at_level: int = 0;
}

walker ResidencyChange {
    has site: str = "";

    can start with Root entry {
        visit [->:ResidentIn:->];
    }

    can bump with ResidencyEpoch entry {
        here.epoch += 1;
        print(f"[residency] bump epoch -> {here.epoch} via {self.site}");
        visit [->:ResidentIn:->];
    }
}

