# I'm making a tiny dungeon crawler in Jac. Rooms are chained nodes and one special room holds the treasure. A hunter walker should check rooms one by one while counting how many it has seen, and terminate the entire search immediately when it finds the treasure room — rooms past the vault must never be visited.
"""Tiny dungeon crawler: chained rooms with a hidden treasure vault.

A Hunter walks the chain room by room, counting every room it enters.
The instant it steps into the treasure vault it disengages so that no
room past the vault is ever visited.
"""

node Room {
    has name: str = "";
    has is_vault: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can search with Room entry {
        self.rooms_checked += 1;
        if here.is_vault {
            print(
                f"Treasure found in '{here.name}' after checking "
                f"{self.rooms_checked} room(s). Hunter stops here."
            );
            disengage;
        }
        print(f"Checked '{here.name}' (no treasure).");
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Guardroom")
        ++> Room(name="Trap Hall")
        ++> Room(name="Vault", is_vault=True)
        ++> Room(name="Hidden Alcove")
        ++> Room(name="Escape Passage");

    hunter = Hunter();
    root spawn hunter;
    print(f"Total rooms checked: {hunter.rooms_checked}");
}

