"""Weather sweep: walk weather stations, report temperatures, then summarize."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];
    has min_c: float = 0.0;
    has max_c: float = 0.0;
    has seen: int = 0;

    can start with Root entry {
        visit [-->];
