node OntologyDef {
    has name: str = "";
    has entity_types: str = "user,device,session";
    has depth: int = 2;
}

node LatentState {
    has world_id: str = "";
    has description: str = "";
}

edge RenderedAs {
    has renderer: str = "";
}

node RenderRecord {
    has text: str = "";
    has renderer_kind: str = "";
    has is_critical: bool = False;
}

node QueryProgram {
    has operations: str = "join,time,aggregate";
    has depth: int = 1;
    has parent_op: str = "";
}

edge Decomposes {
    has label: str = "";
}

edge HasOntology {
    has version: str = "v9";
