    has title: str = "";
    has bytes: str = "";
}

node ReferenceDef {
    has label: str = "";
    has url: str = "";
    has title: str = "";
}

node Heading {
    has text: str = "";
    has level: int = 0;
    has slug: str = "";
}

node InlineSpan {
    has kind: str = "";
    has run: str = "";
    has repeats: int = 0;
}

node ParsedBlock {
    has kind: str = "";
    has ordinal: int = 0;
}

edge Contains { has order: int = 0; }

walker MarkdownAuditor {
    has seen_labels: list[str] = [];
    has seen_slugs: list[str] = [];
    has failures: int = 0;

    can start with Root entry {
        print("Auditing Markdown graph from root");
        visit [-->];
    }

    can audit_doc with MarkdownDocument entry {
        print(f"document: '{here.title}' ({len(here.bytes)} bytes)");
        visit [->:Contains:->];
    }

    can audit_block with ParsedBlock entry {
        print(f"  block[{here.ordinal}] kind={here.kind}");
        visit [->:Contains:->];
    }

    can audit_refs with ReferenceDef entry {
        already = False;
        for lbl in self.seen_labels {
            if lbl == here.label {
                already = True;
            }
        }
        if already {
            print(f"  DUPLICATE reference: {here.label}");
            self.failures = self.failures + 1;
        } else {
            self.seen_labels.append(here.label);
            print(f"  ref[{here.label}] -> {here.url}");
        }
    }

    can audit_heading with Heading entry {
        slug = here.text.lower().replace(" ", "-");
        collide = False;
        for s in self.seen_slugs {
            if s == slug {
                collide = True;
            }
        }
        if collide {
            print(f"  COLLIDING slug: {slug}");
            self.failures = self.failures + 1;
        } else {
            self.seen_slugs.append(slug);
            print(f"  heading h{here.level}: {here.text} -> #{slug}");
        }
    }

    can audit_inline with InlineSpan entry {
        if here.repeats > 32 {
            print(f"  QUADRATIC inline: {here.kind} x{here.repeats}");
            self.failures = self.failures + 1;
        } else {
            print(f"  inline[{here.kind}]: len={len(here.run)}");
        }
    }
}

walker ParserTakeover {
    has depth: int = 0;
    has max_depth: int = 8;
    has inherited_adv: int = 6;
    has retired: int = 0;

    can start with Root entry {
        print("CommonMark dependency severed; Blocks Engine owns Markdown.");
        print(f"rescanned advisories dropped from downstream lockfile: {self.inherited_adv}");
        visit [-->];
