        self.report_lines.append(line);
        line2 = f"  owner_decision: {here.owner_decision}";
        self.report_lines.append(line2);
        visit [->:ProducedDelta:->];
    }

    can review with ArchitectureDelta entry {
        if here.title in self.visited {
            self.report_lines.append(
                f"[CYCLE] refusing to revisit {here.title}"
            );
            disengage;
        }
        self.visited.append(here.title);
        label = "INVALIDATED" if here.invalidated else "LIVE";
        self.report_lines.append(
            f"[DELTA/{label}] {here.title}"
            f" | rationale={here.rationale}"
        );
        visit [->:Supersedes:->];
    }
}

walker CascadeInvalidator {
    has origin: str = "";
    has invalidations: list[str] = [];

    can start with Root entry {
        visit [-->];
