node Room {
    has name: str = "";
    has official_log: list[str] = [];

    can admit with Visitor entry {
        print(f"[LOG] {visitor.kind} entered {self.name}");
    }

    can inspect with Curator entry {
        self.official_log.append(visitor.curator_name);
        visitor.rooms_inspected += 1;
        print(f"[INSPECTION] Curator {visitor.curator_name} inspected {self.name}");
    }
}

