    can start with Root entry {
        visit [-->];
    }

    can tour_room with Room entry {
        visit [-->];
    }
}

walker Curator {
    has curator_name: str = "Anonymous";
    has rooms_inspected: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect_room with Room entry {
        visit [-->];
    }
}

