"""Offline issue tracking graph with dependency-cycle detection."""

node TrackingIssue {
    has issue_number: int = 123;
    has title: str = "";
    has state: str = "open";
}

node ComponentIssue {
    has issue_number: int = 0;
    has title: str = "";
    has state: str = "open";
    has offline_only: bool = True;
}

node EvidenceRecord {
    has title: str = "";
    has result: str = "MANUAL_REVIEW";
    has offline_only: bool = True;
    has limitation: str = "";
}

edge Contains {
    has relation: str = "component";
}

edge DependsOn {
    has relation: str = "runtime dependency";
}

edge HasEvidence {
    has relation: str = "offline evidence";
}

walker DependencyAuditor {
    has visited_numbers: list[int] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can open_tracking with TrackingIssue entry {
        print(f"Tracking issue #{here.issue_number}: {here.title}");
        visit [->:Contains:->] else { disengage; }
    }

    can inspect_component with ComponentIssue entry {
        if here.issue_number in self.visited_numbers {
            print(f"Cycle detected at #{here.issue_number}; dependency walk stopped");
            disengage;
        } else {
            self.visited_numbers.append(here.issue_number);
            print(f"Reviewing #{here.issue_number}: {here.title}");
            visit [->:DependsOn:->] else { disengage; }
        }
    }
}

walker EvidenceAuditor {
    has visited_numbers: list[int] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can open_tracking with TrackingIssue entry {
        visit [->:Contains:->] else { disengage; }
    }

    can inspect_component with ComponentIssue entry {
        if here.issue_number in self.visited_numbers {
            disengage;
        } else {
            self.visited_numbers.append(here.issue_number);
            visit [->:HasEvidence:->] else { disengage; }
        }
    }

    can record with EvidenceRecord entry {
        print(f"Evidence: {here.title} => {here.result} (offline={here.offline_only})");
    }
}

with entry {
    tracking = TrackingIssue(
        issue_number=123,
        title="Harden Orion runtime and quality evidence"
    );

    issue128 = ComponentIssue(
        issue_number=128,
        title="Enforce an end-to-end monotonic request deadline"
    );

    issue129 = ComponentIssue(
        issue_number=129,
        title="Detect recurring recoverable failure cycles across turns"
    );

    issue130 = ComponentIssue(
        issue_number=130,
        title="Track evidence progress for repeated successful reads"
    );

    evidence128 = EvidenceRecord(
        title="Issue 128 targeted offline regression",
        result="PASS",
        limitation="Does not prove live model stability"
    );

    evidence129 = EvidenceRecord(
        title="Issue 129 scripted cycle fixture",
        result="PASS",
        limitation="Does not prove production mutation policy"
    );

    evidence130 = EvidenceRecord(
        title="Issue 130 offline read-progress fixture"
    );

    root ++> tracking;
    tracking +>:Contains:+> issue128;
    tracking +>:Contains:+> issue129;
    tracking +>:Contains:+> issue130;

    issue128 +>:DependsOn:+> issue129;
    issue129 +>:DependsOn:+> issue130;
    issue130 +>:DependsOn:+> issue128;

    issue128 +>:HasEvidence:+> evidence128;
    issue129 +>:HasEvidence:+> evidence129;
    issue130 +>:HasEvidence:+> evidence130;

    root spawn DependencyAuditor();
    root spawn EvidenceAuditor();
}

