"""Flight network: priced legs normalize against the peak fare a scout reports."""

node Airport {
    has code: str = "";
    has city: str = "";
}

edge FlightLeg {
    has price: float = 0.0;

    def fare_fraction(max_fare: float) -> float {
        if max_fare <= 0.0 {
            return 0.0;
        }
        return self.price / max_fare;
    }
}

walker Scout {
    has legs: list[FlightLeg] = [];
    has prices: list[float] = [];
    has max_fare: float = 0.0;
    has seen: dict[str, bool] = {};

    can start with Root entry {
        visit [-->];
