    jfk = Airport(code="JFK", city="New York");
    ord_ap = Airport(code="ORD", city="Chicago");
    lax = Airport(code="LAX", city="Los Angeles");

    root ++> jfk;
    jfk +>:FlightLeg(price=450.0):+> ord_ap;
    ord_ap +>:FlightLeg(price=320.0):+> lax;
    jfk +>:FlightLeg(price=890.0):+> lax;

