node EpicNode {
    has title: str = "";
    has ticket: str = "";
    has status: str = "PENDING";   # PENDING | GO | BLOCKED
    has category: str = "PILOT";   # PILOT | CALIBRATION | HARDENING | STRATEGY | RELEASE
}

edge DependsOn {
    has rationale: str = "";
}

walker EpicAuditor {
    has visited: list[str] = [];
    has blocked: list[str] = [];
    has go_count: int = 0;
    has blocked_count: int = 0;
    has release_unlocked: bool = False;

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can audit with EpicNode entry {
        key = here.ticket;
        # Cycle safety: re-entry is a defect, mark BLOCKED and stop.
        if key in self.visited {
            here.status = "BLOCKED";
            self.blocked.append(key);
            self.blocked_count += 1;
            print(f"[CYCLE] {key} re-entered -> BLOCKED");
            disengage;
        }
        self.visited.append(key);

        # Domain rule: every upstream must already be GO before this node is GO.
        upstreams = [->:DependsOn:->];
        ready = True;
        for up in upstreams {
            if up.status != "GO" {
                ready = False;
            }
        }

        if ready {
            here.status = "GO";
            self.go_count += 1;
            print(f"[GO]   {here.ticket:>4} {here.title}  ({here.category})");
        } else {
            here.status = "BLOCKED";
            self.blocked.append(here.ticket);
            self.blocked_count += 1;
            print(f"[WAIT] {here.ticket:>4} {here.title}  ({here.category})  waiting on upstreams");
        }

        # Release gate special handling.
        if here.ticket == "#453" and here.status == "GO" {
            self.release_unlocked = True;
