"""Resolved workflow specs for canonicalized recipe input paths.

Models the WP-Codebox issue #1697: declared recipe mount paths
(``/wp-codebox-vendor``, ``/home/wpcom/public_html``) must be
canonicalized to runtime paths under ``/tmp/wp-codebox-inputs/...`` by a
single authoritative resolver before any runtime command executes.
The walker performs the resolver traversal and flags any executable arg
that still references a canonicalized declared mount target.
"""

# --- Entities ---------------------------------------------------------

node Recipe {
    has name: str = "";
    has declared_mounts: list[str] = [];
}

node ResolvedSpec {
    has original_args: dict[str, str] = {};
    has resolved_args: dict[str, str] = {};
    has has_unresolved: bool = False;
}

node RuntimeStep {
    has cmd: str = "";
    has args: dict[str, str] = {};
}

# --- Relationships (typed edges) --------------------------------------

edge OwnsMount {
    has declared_path: str = "";
}

edge ProducesSpec {
    has resolution_status: str = "ok";
}

edge ExecutesSpec { }

# --- Walker: the resolver ---------------------------------------------

walker ResolveWorkflow {
    has canonical_root: str = "/tmp/wp-codebox-inputs";

    # The walker accumulates one exit report.
    has report_lines: list[str] = [];

    can start with Root entry {
        visit [->:OwnsMount:->];
    }

    # Walk every recipe the project owns.
    can catalog with Recipe entry {
        print(f"[recipe] {here.name} declared mounts: {here.declared_mounts}");
        visit [->:OwnsMount:->];
    }

    # Each declared mount produces a resolved spec node (one-shot).
    can resolve with Mount entry {
        canonical = f"{self.canonical_root}/{here.declared_path.strip('/')}";
        # Pretend the runtime cmd line still references the declared path
        # (the bug from #1696). The resolver catches it.
        original = {
            "cwd": here.declared_path,
            "autoload-file": f"{here.declared_path}/vendor/autoload.php",
        };
        resolved = {
            "cwd": canonical,
            "autoload-file": f"{canonical}/vendor/autoload.php",
        };
        # Two-phase mutation: build the spec node first, then attach it.
        spec = ResolvedSpec(
            original_args=original,
            resolved_args=resolved,
            has_unresolved=False,
        );
        # Guard: if any executable arg still references a canonicalized
        # declared target, the spec is flagged.
        for (key, value) in original.items() {
            if here.declared_path in value and "wp-codebox-inputs" not in value {
                spec.has_unresolved = True;
            }
        }
        status = "FAIL" if spec.has_unresolved else "OK";
        here +>:ProducesSpec(resolution_status=status):+> spec;
        # Run the runtime step once the spec is in place.
        here +>:ExecutesSpec:+> RuntimeStep(
            cmd="wordpress.phpunit",
            args=resolved,
        );
        self.report_lines.append(
            f"[resolve] {here.declared_path} -> {canonical} [{status}]"
        );
    }

    can audit with ResolvedSpec entry {
        if here.has_unresolved {
            print(f"[guard] UNRESOLVED canonical mount target in executable args: {here.original_args}");
        } else {
            print(f"[audit] resolved cleanly: {here.resolved_args}");
        }
        visit [-->];
    }

    can run with RuntimeStep entry {
        print(f"[runtime] exec {here.cmd} {here.args}");
        visit [-->];
    }

    can finish with Root entry {
        # Single exit report.
        print("--- resolver report ---");
        for line in self.report_lines {
            print(line);
        }
        print("--- end report ---");
    }
}

# --- Demonstration wiring -------------------------------------

# Mount archetype declared so typed edges resolve; carries declared path.
node Mount {
    has declared_path: str = "";
}

with entry {
    # Two recipes, each owning their declared mounts.
    vendor_recipe = Recipe(
        name="wp-codebox-vendor",
        declared_mounts=["/wp-codebox-vendor"],
    );
    public_recipe = Recipe(
        name="wpcom-public-html",
        declared_mounts=["/home/wpcom/public_html"],
    );
    root ++> vendor_recipe;
    root ++> public_recipe;

    # Wire declared mounts as typed OwnsMount edges off each recipe.
    vendor_recipe +>:OwnsMount(declared_path="/wp-codebox-vendor"):+> Mount(declared_path="/wp-codebox-vendor");
    public_recipe +>:OwnsMount(declared_path="/home/wpcom/public_html"):+> Mount(declared_path="/home/wpcom/public_html");

    # Spawn the resolver walker from the root.
    root spawn ResolveWorkflow();
}

