# For my quiz app I want a grader walker in Jac whose reports are strictly typed to integers, so nobody can accidentally report a string score. Quiz nodes carry a student name and score. Spawn the grader over a handful of quizzes and print the collected scores plus the class average.
"""Quiz app grader: collect integer scores from Quiz nodes and report the class average."""

node Quiz {
    has student_name: str = "";
    has score: int = 0;
}

walker Grader {
    has reports: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        report here.score;
        visit [-->];
    }
}

with entry {
    root ++> Quiz(student_name="Alice", score=92)
        ++> Quiz(student_name="Bob", score=85)
        ++> Quiz(student_name="Carol", score=78)
        ++> Quiz(student_name="Diego", score=88);

    grader = Grader();
    root spawn grader;

    scores = grader.reports;
    print(f"Collected scores: {scores}");
    total = 0;
    for s in scores {
        total += s;
    }
    class_avg = 0;
    if scores {
        class_avg = total // len(scores);
    }
    print(f"Class average: {class_avg}");
}

