        self.visited.append(here.name);
        self.reachable.append(here);
        if here.backend not in ["organization", "github-hosted"] and not here.dual_backend {
            print(f"[REJECT] {here.name} has undeclared backend '{here.backend}'");
        } else {
            label = "DUAL" if here.dual_backend else here.backend.upper();
            print(f"[OK] {here.name} backend={label}");
        }
        visit [->:Invokes:->];
    }

    can audit_job with Job entry {
        marker = "HEAVY" if here.expensive else "light";
        print(f"  job[{marker}] {here.title}");
        visit [->:Invokes:->];
    }
