parent link. Listeners attach to Activities to react to lifecycle events.
Propagation moves a trace context across a boundary via a Propagator.
Exception recording copies redacted text into a snapshot.

The walker `Auditor` traverses the parent chain from a span back to the root,
detects cycles in parent links (no built-in visited set in jac 0.36.1), and
reports whether the chain is well-formed, malformed (unknown format), or
contains redaction leaks.
"""

node Activity {
    has name: str = "";
    has trace_id: str = "";
    has parent_id: str = "";
    has has_listeners: bool = False;
    has tags_allocated: bool = False;
    has service_name: str = "";
    has exception_text: str = "";
    has redacted: bool = True;
}

node Listener {
    has kind: str = "noop";
}

node Propagator {
    has format: str = "w3c";
    has allow_w3c: bool = True;
    has bounded: bool = True;
}

edge Parent {
    has depth: int = 0;
}

edge Attached {
    has since: str = "";
}

walker Auditor {
    has start_id: str = "";
    has findings: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can audit with Activity entry {
        # Fast path: no listeners means we must NOT have allocated tags yet.
        if not here.has_listeners and here.tags_allocated {
            self.findings.append(f"LEAK: tags allocated on '{here.name}' without listener");
        }

        # Per-span service identity is supposed to be dropped — flag it.
        if here.service_name != "" {
            self.findings.append(f"PER-SPAN SERVICE: '{here.name}' carries '{here.service_name}'");
        }

        # Redaction check: exception text must be empty unless explicitly kept.
        if here.exception_text != "" and here.redacted {
            self.findings.append(f"REDACTED: '{here.name}' exception text was copied");
        }

        # Walk the parent chain via typed edge. Cycle-safe by guard set.
        visit [->:Parent:->];
