# I'm writing an order auditor in Jac and need both flavors of early return working side by side. Orders are nodes with an amount, a validity flag, and a fraud flag. Invalid orders should be skipped while the audit continues to later orders, but a flagged-fraud order must halt the whole walk on the spot. Print a line per order showing which action fired.
"""Order auditor demonstrating both early-return flavors side by side.

Invalid orders are *skipped* and the audit continues to later orders.
Fraud-flagged orders *halt* the whole walk on the spot. A line is printed
for every order showing which action fired.
"""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has audited: int = 0;
    has skipped: int = 0;
    has halted_on_fraud: bool = False;

    can start with Root entry {
        print("OrderAuditor beginning audit run");
        visit [-->] else { disengage; }
    }

    can audit with Order entry {
        # Fraud halt: stop the entire walk on the spot.
        if here.fraud {
            self.halted_on_fraud = True;
            print(f"[HALT-FRAUD] order amount={here.amount} -- stopping walk");
            disengage;
        }

        # Invalid skip: report and continue to the next order.
        if not here.valid {
            self.skipped += 1;
            print(f"[SKIP]      order amount={here.amount} -- invalid, continuing");
            visit [-->] else { disengage; }
            return;
        }

        # Clean order: record and keep walking.
        self.audited += 1;
        print(f"[AUDIT]     order amount={here.amount}");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Order(amount=120.0, valid=True)
        ++> Order(amount=80.0,  valid=False)
        ++> Order(amount=250.0, valid=True, fraud=True)
        ++> Order(amount=60.0,  valid=True);

    auditor = OrderAuditor();
    root spawn auditor;

    print(
        f"summary: audited={auditor.audited} "
        f"skipped={auditor.skipped} "
        f"halted_on_fraud={auditor.halted_on_fraud}"
    );
}

