"""Local JSON session storage modeled with typed graph relationships and a bounded audit walker."""

node SessionStore {
    has title: str = "Local session store";
    has year: int = 0;
    has available: bool = True;
    has expanded_path: str = "~/.mcp-studio/sessions/";
}

node McpServer {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
    has version: str = "";
}

node McpSession {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has session_id: str = "";
    has server_name: str = "";
    has file_name: str = "";
    has tags: str = "";
    has started_at: int = 0;
}

node SessionEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has sequence: int = 0;
    has kind: str = "";
    has payload: str = "";
}

edge RegistersServer { }
edge HostsSession { }
edge ContainsEntry { }

walker SessionAuditor {
    has max_hops: int = 8;
    has hops: int = 0;
    has session_count: int = 0;
    has entry_count: int = 0;

    can start with Root entry {
        print("Starting local session storage audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspectStore with SessionStore entry {
        print(f"Storage path: {here.expanded_path}");
        if self.hops >= self.max_hops {
            print("Traversal limit reached at storage root");
            disengage;
        }
        self.hops += 1;
        visit [->:RegistersServer:->] else {
            disengage;
        }
        self.hops -= 1;
    }

    can inspectServer with McpServer entry {
        print(f"Server: {here.name} ({here.version})");
        if self.hops >= self.max_hops {
            print("Traversal limit reached at server");
            disengage;
        }
        self.hops += 1;
        visit [->:HostsSession:->] else {
            disengage;
        }
        self.hops -= 1;
    }

    can inspectSession with McpSession entry {
        self.session_count += 1;
        status = "valid" if here.available else "invalidated";
        print(f"Session {here.session_id}: {status}, tags={here.tags}");

        if self.hops >= self.max_hops {
            print(f"Traversal limit reached at session {here.session_id}");
            disengage;
        }
        self.hops += 1;
        visit [->:ContainsEntry:->] else {
            disengage;
        }
        self.hops -= 1;
    }

    can inspectEntry with SessionEntry entry {
        self.entry_count += 1;
        print(f"  entry {here.sequence}: {here.kind} -> {here.payload}");
    }
}

with entry {
    store = SessionStore(expanded_path="~/.mcp-studio/sessions/");

    server = McpServer(
        name="demo-server",
        version="1.0.0"
    );

    first = McpSession(
        session_id="sess-001",
        server_name="demo-server",
        file_name="sess-001.json",
        tags="regression,inspector",
        started_at=20250101
