    first_request = SessionEntry(
        sequence=1,
        kind="request",
        payload="tools/list"
    );

    first_response = SessionEntry(
        sequence=2,
        kind="response",
        payload="200 OK"
    );

    second_request = SessionEntry(
        sequence=1,
        kind="request",
        payload="resources/read"
    );

    root ++> store;
    store +>:RegistersServer:+> server;
    server +>:HostsSession:+> first;
    server +>:HostsSession:+> second;
    first +>:ContainsEntry:+> first_request;
    first +>:ContainsEntry:+> first_response;
    second +>:ContainsEntry:+> second_request;

    auditor = SessionAuditor(max_hops=8);
    root spawn auditor;

    print(f"Audited {auditor.session_count} sessions and "
          f"{auditor.entry_count} stored entries");
}

