# Signet's macOS production runtime deliberately selects a workspace or Homebrew SQLite library so extension loading works. The selected Homebrew SQLite on this host is 3.53.4 and does **not** include `ENABLE_UPDATE_DELETE_LIMIT`, so the scheduled retention sweep fails with `near "LIMIT": syntax error`.
# 
# The test suite uses Bun's embedded SQLite 3.51.0, which **does** include that optional compile flag. The retention tests therefore pass against a different SQL capability set than the installed daemon.
# 
# ## Live installed-daemon evidence
# 
# Installed Signet `0.214.32` logged during its scheduled sweep:
# 
# ```text
# WARN [yielding-writes] retention sweep: write batch failed after 0 committed items
#   {"processed":0,"batches":0,"error":"near \"LIMIT\": syntax error"}
# WARN [retention] Sweep error {"error":"near \"LIMIT\": syntax error"}
# ```
# 
# Current `main` revision `52e891f8b` still contains the same SQL in `platform/daemon/src/pipeline/retention-worker.ts`:
# 
# - `purgeHistory()`;
# - `purgeCompletedJobs()`;
# - `purgeDeadJobs()`; and
# - both statuses in `purgeTranscriptCaptureJobs()`.
# 
# The tombstone/graph/vector transaction runs before these post-retention batches. The first incompatible history delete fails, and the remaining completed/dead/transcript cleanup steps are not processed.
# 
# ## Direct runtime reproduction
# 
# Using Bun's embedded SQLite:
# 
# ```text
# sqlite_version(): 3.51.0
# compile option: ENABLE_UPDATE_DELETE_LIMIT
# DELETE FROM t WHERE created_at < ? LIMIT ? -> changes: 1
# ```
# 
# Using the production-selected `/usr/local/opt/sqlite/lib/libsqlite3.dylib` through `Database.setCustomSQLite()`:
# 
# ```text
# sqlite_version(): 3.53.4
# compile option: absent
# DELETE FROM t WHERE created_at < ? LIMIT ? -> SQLiteError: near "limit": syntax error
# ```
# 
# This is not an old-SQLite-version problem. It is an optional compile-time grammar difference.
# 
# ## Root cause
# 
# Production SQLite selection and SQL verification are separate systems:
# 
# - `resolveSqliteRuntimeConfig()` prefers the Homebrew library on macOS.
# - DB-owner workers receive that selected path and call `Database.setCustomSQLite()`.
# - retention tests construct ordinary `bun:sqlite` in-memory databases without exercising the selected production runtime.
# - no startup capability contract or SQL portability test prevents queries from depending on Bun-only compile options.
# 
# ## Recommended fix
# 
# Do not require `SQLITE_ENABLE_UPDATE_DELETE_LIMIT` for supported runtime behavior. Express bounded deletes with portable SQL, for example by selecting a bounded ID set and deleting by those IDs in the same transaction, or with a portable `WHERE id IN (SELECT id ... LIMIT ?)` form where its query plan is verified.
# 
# Keep the existing work bound and transaction semantics. Do not replace the batch with an unbounded delete.
# 
# Add one isolated production-SQLite compatibility suite. Because `Database.setCustomSQLite()` is process-global, run it in a subprocess against each supported available runtime rather than switching libraries inside the ordinary test process.
# 
# ## Acceptance criteria
# 
# - History, completed/dead memory jobs, and completed/dead transcript-capture jobs purge in bounded batches without `DELETE ... LIMIT` grammar.
# - A regression test runs `runRetentionSweepOnce()` against a custom SQLite library lacking `ENABLE_UPDATE_DELETE_LIMIT` and verifies every post-retention result/count.
# - The same fixture passes under Bun's embedded SQLite.
# - The regression uses the production runtime-selection path or the exact selected library path in an isolated process.
# - CI records `sqlite_version()` and relevant `PRAGMA compile_options` for each tested runtime.
# - A repository audit identifies any other mutation SQL that relies on optional SQLite compile flags.
# - Startup/health exposes the selected SQLite source/path class and capability status without leaking sensitive paths.
# - A failed maintenance batch reports the failed step (`history`, `completed`, etc.), not only the generic `retention sweep` label.
# 
# ## Architecture implication
# 
# Database abstraction is not only a TypeScript interface. The SQL grammar and compile options are part of the runtime contract. A test fake or alternate SQLite build is not production parity if it accepts syntax the selected installed library rejects.
# 
# Related: #1792 (single runtime capability graph), #1793 (architecture ratchet), and #1779/#1780 (truthful runtime health/composition).
# 
# 
# Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.
"""Portable retention sweep over a selected SQLite runtime and bounded batches."""

node SqliteRuntime {
    has source_class: str = "";
    has selected_version: str = "";
    has supports_limit_delete: bool = False;
    has capability_status: str = "";
}

node RetentionBatch {
    has name: str = "";
    has batch_limit: int = 0;
    has delete_strategy: str = "";
    has transactional: bool = True;
}

node RetentionRow {
    has batch_name: str = "";
    has table_name: str = "";
    has row_id: int = 0;
    has status: str = "";
    has batch_limit: int = 0;
    has slot: int = 0;
    has stale: bool = False;
    has purged: bool = False;
}

edge BatchQueue {
    has order: int = 0;
}

edge Purges {
    has reason: str = "";
}

edge Continues {
    has order: int = 0;
}

walker RetentionSweep {
    has seen_batches: list[str] = [];
    has purged_rows: int = 0;
    has failed_step: str = "";

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_runtime with SqliteRuntime entry {
        print(f"runtime {here.source_class} SQLite {here.selected_version}: {here.capability_status}");
        if here.supports_limit_delete {
            print("optional DELETE LIMIT grammar is available");
        } else {
            print("DELETE LIMIT is unavailable; using bounded ID-subquery deletes");
        }
        visit [->:BatchQueue:->] else { disengage; }
    }

    can inspect_batch with RetentionBatch entry {
        if here.name in self.seen_batches {
            self.failed_step = here.name + " (dependency cycle)";
            print(f"failed step: {self.failed_step}");
            disengage;
        } else {
            self.seen_batches.append(here.name);
            if not here.transactional {
                self.failed_step = here.name + " (not transactional)";
                print(f"failed step: {self.failed_step}");
                disengage;
            } else {
                print(f"step {here.name}: bound {here.batch_limit} rows with {here.delete_strategy}");
                visit [->:Purges:->] else {
                    print(f"step {here.name}: no stale rows");
                }
            }
        }
    }

    can purge_row with RetentionRow entry {
        if here.stale and here.slot <= here.batch_limit {
            here.purged = True;
            self.purged_rows += 1;
            print(f"{here.batch_name}: purged {here.table_name} row {here.row_id} ({here.status})");
        }
        visit [->:Continues:->] else {
            print(f"{here.batch_name}: row frontier complete");
        }
    }
}

with entry {
    runtime = SqliteRuntime(
        source_class="Homebrew production library",
        selected_version="3.53.4",
        supports_limit_delete=False,
        capability_status="portable mutation path required"
    );

    history = RetentionBatch(
        name="history",
        batch_limit=2,
        delete_strategy="DELETE ... WHERE id IN (SELECT id ... LIMIT ?)"
    );
    completed = RetentionBatch(
        name="completed memory jobs",
        batch_limit=2,
        delete_strategy="DELETE ... WHERE id IN (SELECT id ... LIMIT ?)"
    );
    transcripts = RetentionBatch(
        name="completed transcript captures",
        batch_limit=2,
        delete_strategy="DELETE ... WHERE id IN (SELECT id ... LIMIT ?)"
    );

    root ++> runtime;
    runtime +>:BatchQueue(order=1):+> history;

    history_row_1 = RetentionRow(batch_name="history", table_name="history", row_id=101, status="expired", batch_limit=2, slot=1, stale=True);
    history_row_2 = RetentionRow(batch_name="history", table_name="history", row_id=102, status="expired", batch_limit=2, slot=2, stale=True);
    history_row_3 = RetentionRow(batch_name="history", table_name="history", row_id=103, status="expired", batch_limit=2, slot=3, stale=True);

    completed_row_1 = RetentionRow(batch_name="completed memory jobs", table_name="memory_jobs", row_id=201, status="completed", batch_limit=2, slot=1, stale=True);
    completed_row_2 = RetentionRow(batch_name="completed memory jobs", table_name="memory_jobs", row_id=202, status="dead", batch_limit=2, slot=2, stale=True);

    transcript_row_1 = RetentionRow(batch_name="completed transcript captures", table_name="transcript_capture_jobs", row_id=301, status="completed", batch_limit=2, slot=1, stale=True);
    transcript_row_2 = RetentionRow(batch_name="completed transcript captures", table_name="transcript_capture_jobs", row_id=302, status="dead", batch_limit=2, slot=2, stale=True);

    history +>:Purges(reason="retention age"):+> history_row_1;
    history +>:Purges(reason="retention age"):+> history_row_2;
    history +>:Purges(reason="retention age"):+> history_row_3;

    completed +>:Purges(reason="retention age"):+> completed_row_1;
    completed +>:Purges(reason="retention age"):+> completed_row_2;

    transcripts +>:Purges(reason="retention age"):+> transcript_row_1;
    transcripts +>:Purges(reason="retention age"):+> transcript_row_2;

    history_row_2 +>:Continues(order=1):+> completed;
    completed_row_2 +>:Continues(order=2):+> transcripts;

    root spawn RetentionSweep();
}

