# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

# A Dancer2 application fixture. `appname` is literal (not dynamic) for the
# supported cells; `dsl_default` records whether the bare `get`/`post`/...
# keywords are admitted at the global scope, and `dsl_handler_only` records
# which keywords may only appear inside a route handler.
node DancerApp {
    has appname: str = "";
    has dsl_default: bool = True;
    has dsl_handler_only: bool = True;
    has supported_version: bool = True;
    has core_only: bool = False;
    has missing_module: bool = False;
}

# A route declaration. Method + pattern are literal; `is_named` flags
# routes with a name so named-route references can be followed; `arity`
# captures the 2/3/4-arg form; `route_kind` discriminates plain / regex /
# any / splat.
node Route {
    has method: str = "";
    has pattern: str = "";
    has route_kind: str = "plain";
    has arity: int = 2;
    has is_named: bool = False;
    has route_name: str = "";
}

# A hook declaration. `hook_kind` selects canonical vs alias vs inline vs
# dynamic/plugin boundary.
node Hook {
    has hook_name: str = "";
    has hook_kind: str = "canonical";
}

# A reference to a named route. `ref_kind` discriminates literal reference
# vs dynamic/incomplete. `safe_for_rename` records whether the LSP may
# safely rename this occurrence.
node RouteRef {
    has target_name: str = "";
    has ref_kind: str = "literal";
    has safe_for_rename: bool = True;
}

# ---------------------------------------------------------------------------
# Typed edges (relationship carries meaning, so each gets an archetype)
# ---------------------------------------------------------------------------

edge DeclaresRoute {}
edge DeclaresHook {}
edge ReferencesRoute {}
edge RunsUnder {}

# ---------------------------------------------------------------------------
# Walker: walks one DancerApp, enumerates its declared routes, follows
# references, and reports lifecycle / support-claim receipts.
# ---------------------------------------------------------------------------

walker ConformanceAuditor {
    # Cycle policy: explicit visited set — walks are over typed DeclaresRoute
    # / ReferencesRoute edges, and a misbehaving fixture that loops a route
    # back onto its own app must not hang the traversal.
    has visited: list[str] = [];
    has route_count: int = 0;
    has ref_count: int = 0;
    has hook_count: int = 0;
    has rejections: list[str] = [];

    can start with Root entry {
        visit [-->];
