    can audit with DancerApp entry {
        # Negative control: unsupported version, missing module, or
        # Dancer2::Core-only usage are out of scope for support claims.
        if not here.supported_version {
            self.rejections.append(f"app {here.appname}: unsupported version");
            disengage;
        }
        if here.missing_module {
            self.rejections.append(f"app {here.appname}: missing Dancer2");
            disengage;
        }
        if here.core_only {
            self.rejections.append(f"app {here.appname}: Dancer2::Core only");
            disengage;
        }
        print(f"auditing Dancer2 app '{here.appname}'");
        visit [->:DeclaresRoute:->];
        visit [->:DeclaresHook:->];
        visit [->:ReferencesRoute:->];
    }

    can tally_route with Route entry {
        self.route_count += 1;
        label = "named" if here.is_named else "anon";
        print(f"  route[{label}] {here.method} {here.pattern} (arity={here.arity}, kind={here.route_kind})");
    }

    can tally_hook with Hook entry {
        self.hook_count += 1;
        print(f"  hook[{here.hook_kind}] {here.hook_name}");
    }

    can follow_ref with RouteRef entry {
        # Cycle guard: track visited ref target names so a ref graph that
        # loops back to itself does not hang the auditor.
        tag = here.target_name + ":" + here.ref_kind;
        if tag in self.visited {
            return;
        }
        self.visited.append(tag);
        self.ref_count += 1;
        verdict = "rename-safe" if here.safe_for_rename else "refused";
        print(f"  ref -> {here.target_name} [{here.ref_kind}, {verdict}]");
    }
}

# ---------------------------------------------------------------------------
# Walker: refuses to audit when the fixture is dynamic-only (a negative
# control: dynamic appname, dynamic route pattern, etc.) — mirrors the
# issue's requirement that the harness assert the intended fallback,
# not merely print "skipped".
# ---------------------------------------------------------------------------

walker RefusalProbe {
    has reason: str = "";

    can probe with DancerApp entry {
        if here.appname == "" {
            self.reason = "dynamic appname";
            print(f"REFUSAL: {self.reason}");
            disengage;
        }
        if here.core_only {
            self.reason = "Dancer2::Core only";
            print(f"REFUSAL: {self.reason}");
            disengage;
        }
        if here.missing_module {
            self.reason = "missing Dancer2 module";
            print(f"REFUSAL: {self.reason}");
            disengage;
        }
        if not here.supported_version {
            self.reason = "unsupported Dancer2 version";
            print(f"REFUSAL: {self.reason}");
            disengage;
        }
        print(f"ACCEPTED: app '{here.appname}' cleared all negative controls");
    }
}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------

with entry {
    # Positive fixture: a representative Dancer2 app with literal appname,
    # the full method set, named + regex + any routes, a canonical hook,
    # and a literal named-route reference.
    pos_app = DancerApp(appname="HelloWorld");
    pos_app +>:DeclaresRoute:+> Route(method="get", pattern="/hello", arity=2);
    pos_app +>:DeclaresRoute:+> Route(method="post", pattern="/submit", arity=3);
    pos_app +>:DeclaresRoute:+> Route(method="any", pattern="/any", arity=2, route_kind="any");
    pos_app +>:DeclaresRoute:+> Route(method="get", pattern=r"^/items/(\d+)$", route_kind="regex");
    pos_app +>:DeclaresRoute:+> Route(method="get", pattern="/named", is_named=True, route_name="show_named");
    pos_app +>:DeclaresHook:+> Hook(hook_name="before_request", hook_kind="canonical");
    pos_app +>:DeclaresHook:+> Hook(hook_name="init", hook_kind="alias");
    pos_app +>:ReferencesRoute:+> RouteRef(target_name="show_named", ref_kind="literal", safe_for_rename=True);
    pos_app +>:ReferencesRoute:+> RouteRef(target_name="dyn_target", ref_kind="dynamic", safe_for_rename=False);

    # Negative fixture: dynamic appname — the RefusalProbe must reject it.
    neg_dynamic = DancerApp(appname="", dsl_default=True);
    neg_dynamic +>:DeclaresRoute:+> Route(method="get", pattern="/x");

    # Negative fixture: missing Dancer2 module — both walkers must reject.
    neg_missing = DancerApp(appname="Broken", missing_module=True);

    # Negative fixture: unsupported version.
    neg_version = DancerApp(appname="OldApp", supported_version=False);

    root +>:RunsUnder:+> pos_app;
    root +>:RunsUnder:+> neg_dynamic;
    root +>:RunsUnder:+> neg_missing;
    root +>:RunsUnder:+> neg_version;

    auditor = ConformanceAuditor();
    root spawn auditor;

    print("--- refusal probes ---");
    pos_app spawn RefusalProbe();
    neg_dynamic spawn RefusalProbe();
    neg_missing spawn RefusalProbe();
    neg_version spawn RefusalProbe();

    print(f"summary: routes={auditor.route_count}, hooks={auditor.hook_count}, refs={auditor.ref_count}, rejections={auditor.rejections}");
}

