# I need a weather sweep in Jac: weather stations are nodes with a location and a temperature reading in Celsius. A walker should visit each station and report the temperature as it goes without stopping. After the sweep, print the full list of readings plus the min and max across all stations.
"""Weather station sweep.

Each station is a node carrying a location and a Celsius reading.
A walker traverses every station, prints the reading as it goes, and
accumulates the readings so we can report min/max at the end.
"""

node Station {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];

    can start with Root entry {
        visit [-->];
    }

    can read with Station entry {
        print(f"{here.location}: {here.celsius}C");
        self.readings.append(here.celsius);
        visit [-->];
    }
}

with entry {
    root ++> Station(location="North", celsius=12.5)
        ++> Station(location="East", celsius=18.0)
        ++> Station(location="South", celsius=21.3)
        ++> Station(location="West", celsius=9.8)
        ++> Station(location="Central", celsius=15.6);

    sweep = WeatherSweep();
    root spawn sweep;

    readings = sweep.readings;
    lo = min(readings);
    hi = max(readings);
    print(f"All readings: {readings}");
    print(f"Min: {lo}C  Max: {hi}C");
}

