"""Road-trip playlist: chain tracks inline and have a player walker play them in order."""

node Track {
    has title: str = "";
    has artist: str = "";
    has runtime_sec: int = 0;
}

walker Player {
    has total_sec: int = 0;
    has track_count: int = 0;

    can start with Root entry {
        print("== Road-trip playlist ==");
        visit [-->];
    }

    can play with Track entry {
        self.total_sec += here.runtime_sec;
        self.track_count += 1;
        mins = here.runtime_sec // 60;
        secs = here.runtime_sec % 60;
        total_mins = self.total_sec // 60;
        total_secs = self.total_sec % 60;
