            f"Now playing: {here.title} by {here.artist} "
            f"({mins}:{secs:02d}) "
            f"| running total {total_mins}:{total_secs:02d}"
        );
        visit [-->];
    }
}

with entry {
    root ++> Track(title="Highway Star", artist="Deep Purple", runtime_sec=372)
        ++> Track(title="Life in the Fast Lane", artist="Eagles", runtime_sec=276)
        ++> Track(title="Born to Run", artist="Bruce Springsteen", runtime_sec=270);
    root spawn Player();
}

