A walker arms a READ grant on a note, another revokes it, and a flag on the
note itself makes the transition visible in the output.
"""

node Note {
    has title: str = "";
    has year: int = 0;
    has share_enabled: bool = False;
}

edge Owns { }

walker ArmShare {
    can start with Root entry {
        visit [-->];
    }

    can arm with Note entry {
        here.share_enabled = True;
        print(f"[ARM]  {here.title} ({here.year}) -> share_enabled={here.share_enabled}");
        visit [-->];
    }
}

walker RevokeShare {
    can start with Root entry {
        visit [-->];
    }

    can revoke with Note entry {
        here.share_enabled = False;
        print(f"[REV]  {here.title} ({here.year}) -> share_enabled={here.share_enabled}");
        visit [-->];
    }
}

with entry {
    morning = Note(title="Morning Pages", year=2024);
    review = Note(title="Weekly Review", year=2024);
    root +>:Owns:+> morning;
    root +>:Owns:+> review;

    print("Before:");
    print(f"  {morning.title}: share_enabled={morning.share_enabled}");
    print(f"  {review.title}: share_enabled={review.share_enabled}");

    root spawn ArmShare();

    print("After arm:");
    print(f"  {morning.title}: share_enabled={morning.share_enabled}");
    print(f"  {review.title}: share_enabled={review.share_enabled}");

    root spawn RevokeShare();

    print("After revoke:");
    print(f"  {morning.title}: share_enabled={morning.share_enabled}");
    print(f"  {review.title}: share_enabled={review.share_enabled}");
}

