# For my quiz app I want a grader walker in Jac whose reports are strictly typed to integers, so nobody can accidentally report a string score. Quiz nodes carry a student name and score. Spawn the grader over a handful of quizzes and print the collected scores plus the class average.
"""Quiz grader walker that reports only integer scores over Quiz nodes."""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has scores: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        print(f"{here.student}: {here.score}");
        self.scores.append(here.score);
        report here.score;
        visit [-->];
    }
}

walker ClassAverage {
    has total: int = 0;
    has count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can tally with Quiz entry {
        self.total += here.score;
        self.count += 1;
        visit [-->];
    }

    can summarize with Root exit {
        if self.count > 0 {
            avg = self.total / self.count;
            print(f"Class average: {avg}");
        } else {
            print("No quizzes graded.");
        }
        report self.total;
    }
}

with entry {
    root ++> Quiz(student="Alice", score=88)
        ++> Quiz(student="Bob", score=72)
        ++> Quiz(student="Carla", score=95)
        ++> Quiz(student="Dmitri", score=60);

    grader = root spawn Grader();
    print(f"Collected scores: {grader.scores}");

    root spawn ClassAverage();
}

