# A maintenance crew tours our orchard groves servicing irrigation pumps and sprinklers: one shared routine should log each device kind, how many hours it sat idle, reset its counter, and report the total devices serviced.
"""Orchard irrigation tour: a crew walker visits pumps and sprinklers, logging each, resetting idle hours, and tallying total devices serviced."""

node Pump {
    has label: str = "";
    has idle_hours: int = 0;

    def kind() -> str {
        return "pump";
    }

    def reset_idle() -> None {
        self.idle_hours = 0;
    }
}

node Sprinkler {
    has label: str = "";
    has idle_hours: int = 0;

    def kind() -> str {
        return "sprinkler";
    }

    def reset_idle() -> None {
        self.idle_hours = 0;
    }
}

walker Crew {
    has serviced: int = 0;

    can start with Root entry {
        print("Crew starting orchard irrigation tour");
        visit [-->];
    }

    can service with Pump | Sprinkler entry {
        pre_idle = here.idle_hours;
        here.reset_idle();
        self.serviced += 1;
        print(f"Serviced {here.kind()} '{here.label}': idle was {pre_idle}h, reset to {here.idle_hours}h");
        visit [-->];
    }
}

with entry {
    grove_a = Pump(label="North-Pump-1", idle_hours=12);
    grove_b = Sprinkler(label="South-Sprinkler-3", idle_hours=7);
    grove_c = Pump(label="East-Pump-2", idle_hours=3);
    grove_d = Sprinkler(label="West-Sprinkler-1", idle_hours=19);

    root ++> grove_a ++> grove_b ++> grove_c ++> grove_d;

    crew = Crew();
    root spawn crew;

    print(f"Total devices serviced: {crew.serviced}");
}

