"""TLAS BUILD-vs-UPDATE gate: ordered BLAS layout compare fails when draw-sort permutes."""

node DrawInstance {
    has entity_id: int = 0;
    has blas_address: int = 0;
    has sort_depth: float = 0.0;
    has in_raster: bool = True;
}

node DrawSequence {
    has frame_label: str = "";
}

node TlasCache {
    has cached_addresses: list[int] = [];
    has blas_map_generation: int = 0;
}

edge DrawOrder { }

walker OrderedLayoutGate {
    has cache_ref: TlasCache;
    has collected: list[int] = [];
    has decision: str = "BUILD";

    def addresses_match_ordered(cached: list[int], current: list[int]) -> bool {
        if len(cached) != len(current) {
            return False;
        }
        for i in range(len(cached)) {
            if cached[i] != current[i] {
                return False;
            }
        }
        return True;
    }

    def decide() {
        cached = self.cache_ref.cached_addresses;
        if len(cached) == 0 {
            self.decision = "BUILD";
        } elif self.addresses_match_ordered(cached, self.collected) {
            self.decision = "UPDATE";
        } else {
            self.decision = "BUILD";
        }
    }

    can head with DrawSequence entry {
        visit [->:DrawOrder:->] else { disengage; };
    }

    can collect with DrawInstance entry {
        self.collected.append(here.blas_address);
        visit [->:DrawOrder:->] else {
            self.decide();
            disengage;
        };
    }
