# Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.
"""Employee management foundation: self-referencing org hierarchy with
recursive traversal, lifecycle history, and deletion-policy checks.

Models the essential scenario from the issue using native Jac archetypes
(typed edges + walker traversal) instead of hand-rolled recursion."""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node Employee {
    has employee_number: str = "";
    has first_name: str = "";
    has last_name: str = "";
    has status: str = "ACTIVE";        # ACTIVE | TERMINATED | SUSPENDED
    has employment_type: str = "FULL_TIME";  # FULL_TIME | PART_TIME | CONTRACT | INTERN
    has hire_date: str = "";
    has department: str = "";
    has position: str = "";
    has full_name: str = "";
    has tenure_years: int = 0;
    has has_payroll_history: bool = False;
    has has_leave_history: bool = False;
    has has_active_leave_request: bool = False;
}

node EmploymentEvent {
    has event_type: str = "HIRE";     # HIRE | TRANSFER | PROMOTION | DEMOTION | SALARY_ADJUSTMENT | TERMINATION
    has event_date: str = "";
    has notes: str = "";
}

# ---------------------------------------------------------------------------
# Typed edges: relationships carry meaning, so they are typed.
# ---------------------------------------------------------------------------

edge ReportsTo { }      # employee -> manager (self-referencing hierarchy)
edge HasEvent { }       # employee -> EmploymentEvent (lifecycle history)

# ---------------------------------------------------------------------------
# Walker: recursive org-tree walk + deletion-policy audit + history dump.
# Carries an explicit visited set because jac 0.36.1 walkers have no
# built-in once-per-node visitation (a manager reachable via two report
# lines would otherwise be counted twice / looped over).
# ---------------------------------------------------------------------------

walker HierarchyAuditor {
    has visited_ids: list = [];
    has chain: list = [];
    has events_seen: int = 0;
    has blocked_deletions: list = [];
    has terminated_with_leave: list = [];

    can start with Root entry {
        visit [-->];
    }

    # Recursive descent: walk every direct report (typed edge) and audit.
    can audit with Employee entry {
        # Cycle / re-entry guard (domain logic: source recurses over a
        # self-referencing FK, which can cycle in corrupt data).
        already = False;
        for vid in self.visited_ids {
            if vid == here {
                already = True;
            }
        }
        if already {
            print(f"[cycle/seen] skipping {here.full_name}");
            disengage;
        }
        self.visited_ids.append(here);

        # Build the reporting chain as we descend.
        self.chain.append(here.full_name);
        print(
            f"  {'  ' * (len(self.chain) - 1)}{here.full_name} "
            f"({here.employee_number}) — {here.position}, "
            f"{here.department}, status={here.status}, "
            f"tenure={here.tenure_years}y"
        );

        # BR-HCM-001: cannot delete if payroll or leave history exists.
        if here.has_payroll_history or here.has_leave_history {
            reason = "payroll_history" if here.has_payroll_history else "leave_history";
            self.blocked_deletions.append((here.full_name, reason));
        }

        # BR-HCM-003: cannot terminate employee with active leave requests.
        if here.status == "TERMINATED" and here.has_active_leave_request {
            self.terminated_with_leave.append(here.full_name);
        }

        # Recurse through the self-referencing manager edge.
        visit [->:ReportsTo:->];
    }

    # Lifecycle history side: collect events on a separate traversal.
    can collect_events with EmploymentEvent entry {
        self.events_seen = self.events_seen + 1;
        print(f"  history: {here.event_type} on {here.event_date} — {here.notes}");
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Demo: build a small tenant with a 3-level hierarchy, a terminated-but-
# blocked employee, and a cyclic edge to exercise the cycle guard.
# ---------------------------------------------------------------------------

with entry {
    # CEO at the top.
    ceo = Employee(
        employee_number="E-0001",
        first_name="Ada",
        last_name="Lovelace",
        status="ACTIVE",
        employment_type="FULL_TIME",
        hire_date="2010-01-04",
        department="Executive",
        position="CEO",
        full_name="Ada Lovelace",
        tenure_years=14,
    );

    # Two VPs reporting to CEO.
    vp_eng = Employee(
        employee_number="E-0002",
        first_name="Grace",
        last_name="Hopper",
        status="ACTIVE",
        department="Engineering",
        position="VP Engineering",
        full_name="Grace Hopper",
        tenure_years=12,
    );
    vp_ops = Employee(
        employee_number="E-0003",
        first_name="Linus",
        last_name="Vance",
        status="ACTIVE",
        department="Operations",
        position="VP Operations",
        full_name="Linus Vance",
        tenure_years=9,
    );

    # ICs reporting to VP Engineering.
    ic_a = Employee(
        employee_number="E-0004",
        first_name="Margaret",
        last_name="Hamilton",
        status="ACTIVE",
        department="Engineering",
        position="Principal Engineer",
        full_name="Margaret Hamilton",
        tenure_years=8,
    );
    ic_b = Employee(
        employee_number="E-0005",
        first_name="Donald",
        last_name="Knuth",
        status="ACTIVE",
        department="Engineering",
        position="Senior Engineer",
        full_name="Donald Knuth",
        tenure_years=6,
    );

    # An intern on a contract — short tenure.
    intern = Employee(
        employee_number="E-0006",
        first_name="Tim",
        last_name="Berners",
        status="ACTIVE",
        employment_type="INTERN",
        hire_date="2024-06-01",
        department="Engineering",
        position="Engineering Intern",
        full_name="Tim Berners",
        tenure_years=0,
    );

    # A terminated employee with an active leave request — BR-HCM-003.
    blocked_term = Employee(
        employee_number="E-0007",
        first_name="Edsger",
        last_name="Dijkstra",
        status="TERMINATED",
        department="Engineering",
        position="Staff Engineer",
        full_name="Edsger Dijkstra",
        tenure_years=4,
        has_active_leave_request=True,
    );

    # An employee with payroll history — BR-HCM-001 blocks deletion.
    payroll_locked = Employee(
        employee_number="E-0008",
        first_name="Barbara",
        last_name="Liskov",
        status="ACTIVE",
        department="Engineering",
        position="Senior Engineer",
        full_name="Barbara Liskov",
        tenure_years=7,
        has_payroll_history=True,
    );

    # Lifecycle events for one employee.
    hire_ev = EmploymentEvent(event_type="HIRE", event_date="2018-03-15", notes="Joined as IC");
    promo_ev = EmploymentEvent(event_type="PROMOTION", event_date="2021-09-01", notes="Promoted to Senior");
    salary_ev = EmploymentEvent(event_type="SALARY_ADJUSTMENT", event_date="2023-04-01", notes="Annual review");

    # Wire the org tree via typed ReportsTo edges.
    # root -> CEO -> VPs -> ICs
    root ++> ceo;
    ceo +>:ReportsTo:+> vp_eng;
    ceo +>:ReportsTo:+> vp_ops;
    vp_eng +>:ReportsTo:+> ic_a;
    vp_eng +>:ReportsTo:+> ic_b;
    vp_eng +>:ReportsTo:+> intern;
    vp_eng +>:ReportsTo:+> blocked_term;
    vp_eng +>:ReportsTo:+> payroll_locked;

    # Intentionally corrupt data: a cycle (blocked_term -> ic_a) to prove
    # the cycle guard fires instead of looping forever.
    blocked_term +>:ReportsTo:+> ic_a;

    # Attach the lifecycle history chain to one employee.
    ic_a +>:HasEvent:+> hire_ev;
    ic_a +>:HasEvent:+> promo_ev;
    ic_a +>:HasEvent:+> salary_ev;

    print("=== Org hierarchy audit (recursive ReportsTo walk) ===");
    auditor = HierarchyAuditor();
    root spawn auditor;

    # Summary of business-rule violations collected during the walk.
    print("\n=== Business rule summary ===");
    print(f"  blocked deletions (BR-HCM-001): {len(auditor.blocked_deletions)}");
    for (name, reason) in auditor.blocked_deletions {
        print(f"    - {name}: {reason}");
    }
    print(f"  terminated with active leave (BR-HCM-003): {len(auditor.terminated_with_leave)}");
    for name in auditor.terminated_with_leave {
        print(f"    - {name}");
    }
    print(f"  reporting chain length: {len(auditor.chain)}");
    print(f"  nodes visited: {len(auditor.visited_ids)}");
}

