# data; the row values themselves are intact in either order.
node KvBlock {
    has block_id: int = 0;
    has block_size: int = 0;
    has gm_offset: int = 0;
    has rows: list[int] = [];
}

# A compressed sparse index referencing two physical blocks in the order
# the operator *logically* consumes them.
node SparseIndex {
    has index_id: int = 0;
    has slot: int = 0;
}

# The query row that owns a list of ``SparseIndex`` entries.
node QueryRow {
    has row_id: int = 0;
    has total_pairs: int = 0;
}

edge PhysicalAlloc {
    has allocated_at: int = 0;
}

edge LogicalPair {
    has pair_slot: int = 0;
}

walker Auditor {
    has total_slots: int = 0;
    has current_slot: int = -1;

    can start with Root entry {
        self.total_slots = 0;
        self.current_slot = -1;
        visit [-->];
    }

    can gather with QueryRow entry {
        print(f"QueryRow {here.row_id} references {here.total_pairs} compressed-KV pairs");
        visit [->:LogicalPair:->];
    }

    can pair with SparseIndex entry {
        self.current_slot = here.slot;
        self.total_slots = self.total_slots + 1;
        blocks = [here->:PhysicalAlloc:->];
        if len(blocks) >= 2 {
            b1 = blocks[0];
            b2 = blocks[1];
            # Logical order (FIX): concatenate in cmp_sparse_indices order.
            merged_logical = list(b1.rows) + list(b2.rows);
            # Physical order (BUG): pick the block with the lower gm_offset first.
            if b1.gm_offset <= b2.gm_offset {
                first_block = b1;
                second_block = b2;
            } else {
