    # Physical block allocation. Notice blk_a has a *lower* gm_offset than blk_b,
    # and blk_c has a *lower* gm_offset than blk_d -- exactly the kind of
    # allocation state that permutes the buggy merged row order.
    idx_0 +>:PhysicalAlloc(allocated_at=100):+> blk_a;
    idx_0 +>:PhysicalAlloc(allocated_at=500):+> blk_b;

    idx_1 +>:PhysicalAlloc(allocated_at=900):+> blk_c;
    idx_1 +>:PhysicalAlloc(allocated_at=1300):+> blk_d;

    # A second allocation layout for the same logical indices, demonstrating
    # that flipping the physical addresses is what changes the buggy output.
    alt_blk_x = KvBlock(block_id=10, block_size=3, gm_offset=2500, rows=[1, 2, 3]);
    alt_blk_y = KvBlock(block_id=11, block_size=3, gm_offset=2200, rows=[4, 5, 6]);
    idx_0 +>:PhysicalAlloc(allocated_at=2200):+> alt_blk_y;
    idx_0 +>:PhysicalAlloc(allocated_at=2500):+> alt_blk_x;

    print("=== First allocator layout (blk_a < blk_b by gm_offset) ===");
    root spawn Auditor();

    # Now flip the physical block layout for idx_0 to show the BUG
    # changes while the FIX stays the same.
    idx_0 del --> blk_a;
    idx_0 del --> blk_b;
    idx_0 +>:PhysicalAlloc(allocated_at=800):+> blk_b;
    idx_0 +>:PhysicalAlloc(allocated_at=300):+> blk_a;

    print("=== Second allocator layout (blk_b < blk_a by gm_offset) ===");
    root spawn Auditor();
}

