node Package {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
}

node Barrel {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has role: str = "barrel";
}

node SourceFile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has role: str = "defining file";
}

edge Imports {
    has reason: str = "";
}

walker BarrelAuditor {
    has seen: list[str] = [];

    can start with Root entry {
        print("Auditing application import graph");
        visit [-->] else {
            disengage;
        }
