node Account {
    has account_id: str = "";
    has label: str = "";
    has archived: bool = False;
}

edge HasChild {
    has created_on: str = "";
}

walker SubtreeCollector {
    has actor_id: str = "";
    has descendants: list[str] = [];
    has _seen: list[str] = [];

    can start with Root entry {
        visit [->:HasChild:->];
    }

    can descend with Account entry {
        if here.archived {
            # Archived node: subtree authority breaks here.
            disengage;
