}

walker Authority {
    has actor: Account | None = None;
    has target_id: str = "";
    has allowed: bool = False;
    has reason: str = "";

    can start with Account entry {
        if here.archived {
            self.allowed = False;
            self.reason = "actor archived";
            disengage;
