# I'm marking out a hiking trail in Jac as a chain of plain waypoints between the trailhead and the summit — the waypoints themselves don't need to hold any data at all. Give me a hiker walker that travels the trail and counts how many waypoints it passes, printing each stop number along the way and a completion line once it has passed enough of them.
"""Hiking trail: a chain of plain waypoints from trailhead to summit, counted by a hiker walker."""

node Waypoint {
    has stop_num: int = 0;
}

walker Hiker {
    has target: int = 3;
    has count: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can hike with Waypoint entry {
        self.count += 1;
        here.stop_num = self.count;
        print(f"Stop #{here.stop_num}");
        if self.count >= self.target {
            print("Reached the summit — trail complete!");
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    trailhead = Waypoint();
    w1 = Waypoint();
    w2 = Waypoint();
    w3 = Waypoint();
    summit = Waypoint();

    root ++> trailhead ++> w1 ++> w2 ++> w3 ++> summit;

    root spawn Hiker(target=3);
}

