# ## Design sketch
# 
# The pipeline is already per-page in stages 1-4 (georef, adjacency-gate, snap, street-solve); only the volume-level passes are global (reference scale + family rungs, reconcile, iiif/compare) and those are cheap. So:
# 
# - Per page, per stage, hash the stage's actual inputs: `streets.json`, the page's keymap location (not the whole keymap.json — most pages' locations are unchanged by a read-repair elsewhere on the sheet), adjacency claims/edges touching the page, relevant flags, and a stage-code version stamp.
# - `fit --incremental` reuses the prior run's channel sidecar when the hash matches, recomputes when it doesn't, and ALWAYS re-runs the global passes (they're volume-level and fast; reconcile must see the full pose set).
# - Cross-page couplings to get right (the reasons a naive per-page cache is wrong):
#   - the volume reference scale / family rungs are derived from *published* fits, so a changed page can perturb snap refinement on untouched pages (documented in fit-pipeline.md: nashville p4 moved 26->402 ft under a scale-band experiment). Treat the rung set as an input to snap's hash: if the rung set changes, snap re-runs volume-wide; if not, per-page reuse is sound.
#   - adjacency-gate arbitration is volume-global (multi-contradiction counting) — cheap, always re-run; only its *demotion writes* are per-page.
#   - snap's ransac-neighbor rotation prior reads neighbours' published fits — include the neighbour poses in the page's snap hash (this is the same staleness class #240's clear_derived_sidecars fixed; hashing makes it explicit instead of nuking everything).
# - `candidates.jsonl` already works as an incremental cache keyed on contradiction mtime; this generalizes that pattern and pushes the archive system's volume-level input hashing down to page granularity.
# 
# ## Prerequisite: per-stage timing
# 
# The fit log doesn't timestamp stages, so stage costs are currently inferred from file mtimes. First change (small, immediate): wrap `run_cmd` in fit.py with elapsed-time reporting and record per-stage durations in the run manifest. Per-page snap timing already exists (`elapsed_s` in candidates.jsonl, #192); georef and reconcile have no per-page timing yet.
# 
# ## Expected payoff
# 
# A keymap-reads-only change re-fits ~10-15% of pages: minutes per volume instead of ~30-45. A gate-logic change re-runs stage 2 + affected downstream pages only. Full recompute stays available (and remains the pre-merge standard); incremental mode is for the iterate loop.
# 
# 🤖 Generated with [Claude Code](https://claude.com/claude-code)
# 
# Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.
"""Mapsnap incremental fit: model pages, stages, and rung sets as a graph.

Demonstrates the cross-page coupling the issue cares about: snap's hash
for a page depends on its neighbour poses and on the volume-wide rung
set, so a single page's invalidation ripples through the neighbours
that snap consulted. A walker walks the snap dependency edges and
emits one incremental-fit plan per affected page."""

# ---- Nodes -----------------------------------------------------------------

node NodeBase {
    has kind: str = "";
    has label: str = "";
    has fingerprint: str = "";
}

node Page(NodeBase) {
    has keymap_loc: str = "";
    has stage_version: int = 0;
}

node Stage(NodeBase) {
    has stage_name: str = "";
    has stage_version: int = 0;
}

node RungSet(NodeBase) {
    has volume: str = "";
}

# Snap's neighbour-pose prior: a typed dependency from one page to another.
edge SnapPrior {
    has weight: float = 0.0;
}

# Stage -> Page: which page the stage ran on.
edge RanOn { }

# Page -> Page: snap consumed the neighbour's published fit.
edge ConsultedPose { }

# Page -> RungSet: snap for this page read the volume's rung set.
edge UsedRungs { }

# ---- Walker ----------------------------------------------------------------

# `FitPlanner` traverses the per-page snap dependencies. For each page it
# reaches it records why the page must be recomputed (own hash change,
# neighbour pose change, or rung-set change). One exit `report` collects
# the plan.
walker FitPlanner {
    has changed_pages: list[str] = [];
    has changed_rungs: str = "";

    can start with Root entry {
        visit [-->];
    }

    # Union ability: same logic whether we land on a Page or on a RungSet.
    # Both node kinds share `label`, `fingerprint`, and `kind` via NodeBase.
    can plan with Page | RungSet entry {
        reason = "";
        if here.kind == "rungset" {
            self.changed_rungs = here.fingerprint;
            reason = "rungs=" + here.fingerprint;
        } else {
            self.changed_pages.append(here.label);
            label_reason = "neighbour-of-rungs" if self.changed_rungs != "" else "own-hash";
            reason = label_reason;
        }
        print(f"[plan] {here.label}: {reason}");
        visit [-->];
    }
}

# `SnapWalker` simulates a single A/B that mutates a few pages and the
# rung set, then spawns the planner to compute which pages must re-snap.
walker SnapWalker {
    has volume: str = "";

    can start with Root entry {
        print(f"== incremental fit for volume {self.volume} ==");
        visit [-->];
    }

    can plan_volume with RungSet entry {
        print(f"rung-set fingerprint = {here.fingerprint}");
        visit [-->];
    }

    can plan_page with Page entry {
        print(f"page {here.label} keymap_loc={here.keymap_loc}");
        visit [-->];
    }
}

# ---- Demo ------------------------------------------------------------------

with entry {
    georef = Stage(stage_name="georef", stage_version=1);
    snap = Stage(stage_name="snap", stage_version=2);
    reconcile = Stage(stage_name="reconcile", stage_version=1);

    rungset = RungSet(volume="nashville", fingerprint="rungs-v3");

    # Pages in a single volume; only p2 and p4 had their keymap locations
    # edited, mirroring the issue's "~10-15% of pages" example.
    p1 = Page(label="p1", keymap_loc="A1");
    p2 = Page(label="p2", keymap_loc="B7");
    p3 = Page(label="p3", keymap_loc="C3");
    p4 = Page(label="p4", keymap_loc="D9");
    p5 = Page(label="p5", keymap_loc="E2");

    # Volume-level chain: stages -> rungset -> pages.
    root ++> georef ++> snap ++> reconcile ++> rungset;
    rungset ++> p1 ++> p2 ++> p3 ++> p4 ++> p5;

    # Snap's cross-page dependencies: each page consulted its neighbours'
    # published fits (the staleness class the issue flags).
    p1 +>:SnapPrior(weight=0.9):+> p2;
    p2 +>:SnapPrior(weight=0.7):+> p3;
    p3 +>:SnapPrior(weight=0.8):+> p4;
    p4 +>:SnapPrior(weight=0.6):+> p5;

    # Pages -> stages that ran on them (typed RanOn edge).
    p1 +>:RanOn:+> georef;
    p2 +>:RanOn:+> georef;
    p3 +>:RanOn:+> georef;
    p4 +>:RanOn:+> georef;
    p5 +>:RanOn:+> georef;

    # Pages -> rung set they read during snap.
    p1 +>:UsedRungs:+> rungset;
    p2 +>:UsedRungs:+> rungset;
    p3 +>:UsedRungs:+> rungset;
    p4 +>:UsedRungs:+> rungset;
    p5 +>:UsedRungs:+> rungset;

    # Walk the volume to show what incremental fit sees.
    root spawn SnapWalker(volume="nashville");

    # Now ask the planner which pages must recompute when rungs change.
    planner = FitPlanner(changed_rungs="rungs-v3");
    root spawn planner;
}

