# I'm making a tiny dungeon crawler in Jac. Rooms are chained nodes and one special room holds the treasure. A hunter walker should check rooms one by one while counting how many it has seen, and terminate the entire search immediately when it finds the treasure room — rooms past the vault must never be visited.
"""Tiny dungeon crawler: a chain of rooms with a hidden treasure vault.

The Hunter walker advances room-by-room along the chain, counting how many
rooms it has inspected. The instant it steps into the treasure room, it
disengages — rooms downstream of the vault are never visited.
"""

node Room {
    has name: str = "";
    has treasure: bool = False;
}

walker Hunter {
    has rooms_inspected: int = 0;
    has found_treasure: bool = False;
    has treasure_room: str = "";

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can explore with Room entry {
        self.rooms_inspected += 1;
        if here.treasure {
            self.found_treasure = True;
            self.treasure_room = here.name;
            print(f"Found the treasure in '{here.name}' after inspecting {self.rooms_inspected} room(s). Halting the hunt.");
            disengage;
        }
        print(f"Inspected '{here.name}' — no treasure here.");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes")
        ++> Room(name="Treasure Vault", treasure=True)
        ++> Room(name="Forbidden Crypt")
        ++> Room(name="Dragon's Den");

    hunter = Hunter();
    root spawn hunter;

    if hunter.found_treasure {
        print(f"Hunt summary: treasure secured in '{hunter.treasure_room}' after {hunter.rooms_inspected} room(s) searched.");
    } else {
        print(f"Hunt summary: no treasure found after {hunter.rooms_inspected} room(s) searched.");
    }
}

