            here.emitted = True;
            visit [-->];
            return;
        }
        self.cycle_stack.append(here.name);
        unresolved = False;
        for callee in [->:Call:->] {
            if not callee.emitted {
                unresolved = True;
                break;
            }
        }
        if unresolved {
            self.cycle_stack.pop();
            visit [->:Call:->];
            return;
        }
        print(here.body);
        self.order.append(here.name);
        here.emitted = True;
        self.cycle_stack.pop();
        visit [-->];
    }
}

