    has name: str = "";
}

node Person {
    has user_id: str = "";
    has name: str = "";
    has company_id: str = "";
    has hop: int = -1;
    has processed_token: str = "";
}

node Project {
    has project_id: str = "";
    has name: str = "";
    has company_id: str = "";
    has active: bool = True;
    has hop: int = -1;
    has processed_token: str = "";
}

node Card {
    has card_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has company_id: str = "";
    has creator_id: str = "";
}

