node GraphItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has owner: str = "";
    has details: str = "";
    has visible_to_all: bool = False;

    def readable_to(viewer: str) -> bool {
        if self.visible_to_all {
            return True;
        }
        if self.owner == viewer {
            return True;
        }
        return False;
    }
