    secret = Secret(
        title="alice-secret",
        value="only-alice-should-read-this",
        details="value=only-alice-should-read-this",
        owner="alice"
    );

    root +>:Contains:+> shared;
    shared +>:Contains:+> alice;
    alice +>:Contains:+> secret;

    root spawn RawGraphDump();
    root spawn AuthorizedGraphDump(viewer="bob");
