# A maintainer on the project babyfish-ct/jimmer (unknown) filed this issue about hand-rolled graph machinery causing pain:
# 
# Issue #1237: [Feature Request] - Make subquery support Base-Query
# 
# ### Reason
# 
# Hi! Sometimes, I wish the result of a CTE recursive query could be used as a subquery within another query. For example:
# 
# ```SQL
# WITH RECURSIVE cte AS ( 
#   SELECT foo_id from tree_table where parent_id IS NULL 
#   UNION ALL
#   SELECT children.foo_id from tree_table children INNER JOIN cte cte_parent ON children.parent_id = cte_parent.id
# )
# SELECT * from foo where id IN (SELECT foo_id in cte)
# ```
# 
# However, Base-Query now appears to only support usage within root queries (please correct me if I'm mistaken).
# 
# 
# 
# ### Description
# 
# Therefore, I hope subquery can support Base-Query.
# 
# ### Existing solutions
# 
# Consequently, I now have to split a single query into two steps:
# 1. Use a recursive CTE query to generate the full list of IDs I need.
# 2. Process this ID list within the code and then use it as a parameter for the query.
# 
# Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.
"""Recursive CTE-style subquery: model a tree where the recursive CTE
result feeds into a downstream query, exactly the scenario from issue
#1237. A walker descends the tree collecting IDs (the CTE), then another
walker uses that collected set as a subquery filter against a separate
collection of Foo nodes (the consumer query).
"""

node TreeNode {
    has id: int = 0;
    has name: str = "";
}

node Foo {
    has id: int = 0;
    has label: str = "";
}

edge ParentOf { }

walker CollectSubtree {
    has collected_ids: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with TreeNode entry {
        self.collected_ids.append(here.id);
        visit [->:ParentOf:->];
    }
}

walker QueryWithSubquery {
    has allowed_ids: list[int] = [];
    has matches: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can filter with Foo entry {
        if here.id in self.allowed_ids {
            self.matches.append(here.label);
        }
        visit [-->];
    }
}

with entry {
    # Build the tree (the source the recursive CTE walks).
    r = TreeNode(id=0, name="root");
    a = TreeNode(id=1, name="a");
    b = TreeNode(id=2, name="b");
    c = TreeNode(id=3, name="c");
    d = TreeNode(id=4, name="d");
    r +>:ParentOf:+> a;
    a +>:ParentOf:+> b;
    a +>:ParentOf:+> c;
    c +>:ParentOf:+> d;
    root ++> r;

    # Step 1: recursive CTE walk to gather ids.
    cte = CollectSubtree();
    r spawn cte;
    print(f"CTE collected ids: {cte.collected_ids}");

    # Step 2: consumer query filtered by the subquery result.
    f1 = Foo(id=1, label="foo-A");
    f2 = Foo(id=2, label="foo-B");
    f3 = Foo(id=3, label="foo-C");
    f4 = Foo(id=5, label="foo-E");
    f5 = Foo(id=99, label="foo-OTHER");
    root ++> f1 ++> f2 ++> f3 ++> f4 ++> f5;

    consumer = QueryWithSubquery(allowed_ids=cte.collected_ids);
    root spawn consumer;
    print(f"Subquery-filtered foos: {consumer.matches}");
}

