node ExposureStore {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has monotonic_now: float = 0.0;
    has half_life: float = 60.0;
    has semantic_fatigue: float = 0.0;
    has pattern_fatigue: float = 0.0;
    has visit_key: str = "";
}

node Exposure {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has semantic_identity: str = "";
    has story_family: str = "";
    has pattern: str = "";
    has final_text: str = "";
    has tape_channel: str = "";
    has lexical_tail: str = "";
    has lifecycle: str = "PLANNED";
    has playback_accepted: bool = False;
    has actually_spoken: bool = False;
    has observed_monotonic: float = 0.0;
    has base_penalty: float = 1.0;
    has event_penalty_coefficient: float = 1.0;
    has embedding_hint: float = 0.0;
    has visit_key: str = "";
}

node Channel {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has tape_channel: str = "";
    has pressure: float = 0.0;
    has visit_key: str = "";
}

