    has now: float = 0.0;
    has half_life: float = 60.0;
    has visited_keys: list[str] = [];
    has tail_history: list[str] = [];
    has pressure_channels: list[str] = [];
    has pressure_values: list[float] = [];
    has semantic_total: float = 0.0;
    has pattern_total: float = 0.0;

    def already_seen(candidate: str) -> bool {
        return candidate in self.visited_keys;
    }

    def lexical_tail_jaccard(left: str, right: str) -> float {
        left_terms = left.split(" ");
        right_terms = right.split(" ");
        intersection = 0;
        union = len(left_terms);
        for token in right_terms {
            if token in left_terms {
                intersection += 1;
            } else {
                union += 1;
            }
        }
        if union == 0 {
            return 0.0;
        }
        return intersection / union;
    }

