# In our warehouse simulation, packing stations announce which robot they are serving while robots announce each station they stop at. Count stops per robot and boxes packed per station across a three-station line.
"""Warehouse packing line: stations announce the robot they serve and robots announce every station they stop at, with totals across a three-station line."""

node Station {
    has name: str = "";
    has robot_served: str = "";
    has boxes_packed: int = 0;
}

node Robot {
    has name: str = "";
    has stops: int = 0;
}

edge Serves {
    has robot_served: str = "";
    has boxes_packed: int = 0;
}

edge StopsAt {
    has station_name: str = "";
}

walker StationAnnouncer {
    can start with Root entry {
        visit [-->];
    }

    can announce with Station entry {
        print(f"Station {here.name} is serving robot {here.robot_served} ({here.boxes_packed} boxes packed)");
        visit [-->];
    }
}

walker RobotAnnouncer {
    can start with Root entry {
        visit [-->];
    }

    can announce with Robot entry {
        print(f"Robot {here.name} stops: {here.stops}");
        visit [-->];
    }

    can visit_station with Station entry {
        print(f"  -> stopped at station {here.name}");
        visit [-->];
    }
}

walker StopsCounter {
    has target: str = "";

    can start with Root entry {
        visit [-->];
    }

    can walk_stations with Station entry {
        if here.robot_served == self.target {
            here.boxes_packed += 1;
            print(f"Station {here.name} packed a box for {self.target}");
        }
        visit [-->];
    }
}

walker BoxesCounter {
    has target: str = "";

    can start with Root entry {
        visit [-->];
    }

    can walk_stations with Station entry {
        if here.name == self.target {
            here.boxes_packed += 1;
            print(f"Station {here.name} total boxes packed: {here.boxes_packed}");
        }
        visit [-->];
    }
}

with entry {
    s1 = Station(name="S1", robot_served="R1", boxes_packed=0);
    s2 = Station(name="S2", robot_served="R2", boxes_packed=0);
    s3 = Station(name="S3", robot_served="R3", boxes_packed=0);

    r1 = Robot(name="R1", stops=0);
    r2 = Robot(name="R2", stops=0);
    r3 = Robot(name="R3", stops=0);

    root ++> s1 ++> s2 ++> s3;
    root ++> r1 ++> r2 ++> r3;

    print("=== Station announcements ===");
    root spawn StationAnnouncer();

    print("=== Robot announcements ===");
    root spawn RobotAnnouncer();

    print("=== Counting stops per robot ===");
    r1 spawn StopsCounter(target="R1");
    r2 spawn StopsCounter(target="R2");
    r3 spawn StopsCounter(target="R3");

    print("=== Counting boxes per station ===");
    root spawn BoxesCounter(target="S1");
    root spawn BoxesCounter(target="S2");
    root spawn BoxesCounter(target="S3");

    print("=== Final tallies ===");
    print(f"Robot R1: {r1.stops} stops");
    print(f"Robot R2: {r2.stops} stops");
    print(f"Robot R3: {r3.stops} stops");
    print(f"Station S1: {s1.boxes_packed} boxes packed");
    print(f"Station S2: {s2.boxes_packed} boxes packed");
    print(f"Station S3: {s3.boxes_packed} boxes packed");
}

