# Guests at our hotel walk past service desks (spa session, room-service dinner, express laundry); each desk adds its price to whichever guest is currently passing by. Print each charge as it happens and what each guest owes at checkout.
"""Hotel service desk: each desk charges whichever guest is currently passing by."""

node Desk {
    has name: str = "";
    has price: int = 0;
}

node Guest {
    has name: str = "";
    has bill: int = 0;
}

walker GuestVisitor {
    has name: str = "";
    has bill: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can pass_desk with Desk entry {
        charge_msg = f"{self.name} charged {here.price} for {here.name}";
        self.bill = self.bill + here.price;
        print(charge_msg);
        visit [-->];
    }

    can walk_more with Guest entry {
        visit [-->];
    }
}

with entry {
    spa = Desk(name="spa session", price=40);
    dinner = Desk(name="room-service dinner", price=55);
    laundry = Desk(name="express laundry", price=20);

    root ++> spa ++> dinner ++> laundry;

    alice = GuestVisitor(name="Alice");
    bob = GuestVisitor(name="Bob");

    root spawn alice;
    root spawn bob;

    print(f"{alice.name} owes {alice.bill}");
    print(f"{bob.name} owes {bob.bill}");
}

