        price=450.0, origin_code="JFK", dest_code="LAX"
    );
    jfk +>:leg_jfk_lax:+> lax;

    leg_lax_ord = FlightLeg(
        price=320.0, origin_code="LAX", dest_code="ORD"
    );
    lax +>:leg_lax_ord:+> ord;

    leg_ord_bos = FlightLeg(
        price=580.0, origin_code="ORD", dest_code="BOS"
    );
    ord +>:leg_ord_bos:+> bos;

    leg_bos_jfk = FlightLeg(
        price=275.0, origin_code="BOS", dest_code="JFK"
    );
    bos +>:leg_bos_jfk:+> jfk;

    leg_jfk_ord = FlightLeg(
        price=510.0, origin_code="JFK", dest_code="ORD"
    );
    jfk +>:leg_jfk_ord:+> ord;

    scout = FareScout();
    root spawn scout;

    peak = scout.peak_fare;
    print(
        f"Scout peak fare: ${peak} "
        f"(reported {len(scout.fare_report)} prices)"
    );

    legs = [
        leg_jfk_lax,
        leg_lax_ord,
        leg_ord_bos,
        leg_bos_jfk,
