def _sort_nodes_by_cid(nodes: list[GNode]) -> list[GNode] {
    cids: list[str] = [];
    out: list[GNode] = [];
    for nd in nodes {
        cids.append(nd.cid);
    }
    cids = sorted(cids);
    for cid in cids {
        for nd in nodes {
            if nd.cid == cid {
                out.append(nd);
            }
        }
    }
    return out;
}

