"""NORA-style architecture publishing: principles, building blocks, and standards
linked by typed relationships, traversed by walkers that handle parent/child
nesting, dependency ordering, mapping lookups, and cycle-safe walks.
"""

node Principle {
    has title: str = "";
    has code: str = "";
    has description: str = "";
    has depth: int = 0;
}

node BuildingBlock {
    has title: str = "";
    has code: str = "";
    has description: str = "";
    has kind: str = "service";
}

node Standard {
    has title: str = "";
    has code: str = "";
    has compliance_status: str = "toegepast";
    has compliance_reasoning: str = "";
}

edge AdoptsFrom { }
edge ComposedOf { }
edge ProfilesOf { }
edge HasChild { }

walker TreePrinter {
    can start with Root entry {
        visit [-->];
    }

    can walk_principle with Principle entry {
        indent = "  " * here.depth;
        print(f"{indent}{here.title} ({here.code})");
        visit [->:HasChild:->];
    }
}

walker DependencyOrderer {
    has visited: list[str] = [];
    has order: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can gather with BuildingBlock entry {
        key = here.code;
        if key not in self.visited {
            self.visited.append(key);
            self.order.append(key);
            print(f"ordered: {here.title}");
            visit [->:ComposedOf:->];
        } else {
            visit [->:ComposedOf:->];
        }
    }
}

walker ComplianceAuditor {
    has issues: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_standard with Standard entry {
        if here.compliance_status == "niet-toegepast" and here.compliance_reasoning == "" {
            note = f"missing reasoning for {here.code}";
            self.issues.append(note);
            print(f"[WARN] {note}");
        } else {
            print(f"[OK] {here.code}: {here.compliance_status}");
        }
        visit [-->];
    }

    can audit_principle with Principle entry {
        visit [->:ProfilesOf:->];
    }
}

with entry {
    p_api = root ++> Principle(title="API Design", code="AP-01", description="REST guidelines");
    p_ver = root ++> Principle(title="Versioning", code="AP-04", description="semver policy");
    root ++> BuildingBlock(title="Auth Service", code="BB-AUTH", description="OAuth2 gateway");
    root ++> BuildingBlock(title="Search Service", code="BB-SRCH", description="full-text index");
    root ++> Standard(title="OAuth 2.1", code="STD-OAUTH", compliance_status="toegepast");
    root ++> Standard(title="NORA AP-04", code="STD-AP04", compliance_status="niet-toegepast", compliance_reasoning="");

    p_api +>:HasChild:+> p_ver;

    root +>:AdoptsFrom:+> Standard(code="STD-OAUTH");

    bb_auth = root +>:ComposedOf:+> BuildingBlock(title="Token Cache", code="BB-TKC", description="Redis-backed");
    bb_auth +>:ComposedOf:+> BuildingBlock(title="Crypto Module", code="BB-CRY", description="HS256/RS256");

    root +>:ProfilesOf:+> Standard(code="STD-AP04");

    root spawn TreePrinter();
    print("---");
    root spawn DependencyOrderer();
    print("---");
    root spawn ComplianceAuditor();
}

