node OntologyClass {
    has name: str = "";
    has depth: int = 0;
    has width_index: int = 0;
    has order_index: int = 0;
    has invalidated: bool = False;
}

node IndexEntry {
    has lo: int = 0;
    has hi: int = 0;
    has two_hop_ancestors: list[str] = [];
}

edge Parent {
    has weight: float = 1.0;
}

edge TwoHopLink {
    has hop: int = 1;
}

walker HierarchyInspector {
    has visited: list[str] = [];
    has order: list[str] = [];
    has cycle_detected: bool = False;
    has two_hop_fanout: int = 0;

    can start with Root entry {
        print(f"=== HIER walk starting over root children ===");
        self.visited = [];
        self.order = [];
        self.cycle_detected = False;
        visit [-->] else { disengage; }
