        self.visited.append(here.name);
        here.depth = len(self.visited) - 1;
        print(f"  visit {here.name} (depth {here.depth}, width_idx {here.width_index})");
        self.order.append(here.name);
        visit [->:Parent:->] else { disengage; }
    }

    can probe with IndexEntry entry {
        # Walk over typed TwoHopLink edges to count 2-hop fanout.
        self.two_hop_fanout = 0;
        for _ in [->:TwoHopLink:->] {
            self.two_hop_fanout += 1;
        }
        print(f"  2-hop fanout at index entry: {self.two_hop_fanout}");
        visit [->:TwoHopLink:->] else { disengage; }
    }
}

walker CascadeInvalidator {
    has invalid_name: str = "";
    has purged: list[str] = [];

    can start with Root entry {
        print(f"=== Cascade invalidation targeting '{self.invalid_name}' ===");
        visit [-->] else { disengage; }
    }

    can invalidate with OntologyClass entry {
        if here.name == self.invalid_name {
            here.invalidated = True;
            self.purged.append(here.name);
            print(f"  invalidated {here.name}, cascading through children");
            visit [->:Parent:->] else { disengage; }
        } else {
            visit [->:Parent:->] else { disengage; }
        }
    }
}

