A kiosk walker greets every visitor (regardless of type), a zookeeper
dispenses a species-appropriate meal using a union trigger across
Lion and Parrot (and a fall-through for any other animal), and a
school group simply watches the animals quietly.
"""

node Lion {
    has name: str = "";
}

node Parrot {
    has name: str = "";
    has phrase: str = "";
}

node Animal {
    has name: str = "";
}

walker Kiosk {
    can start with Root entry {
        print("[kiosk] Welcome to the park!");
        visit [-->];
    }

    can greet with Lion | Parrot | Animal entry {
        print(f"[kiosk] Hello, visitor near {here.name}");
        visit [-->];
    }
}

walker Zookeeper {
    can start with Root entry {
        visit [-->];
    }

    can feed_lion with Lion entry {
        print(f"[zookeeper] {here.name} the lion gets meat.");
        visit [-->];
    }

    can feed_parrot with Parrot entry {
        print(f"[zookeeper] {here.name} the parrot gets seed ({here.phrase}).");
        visit [-->];
    }

    can feed_other with Animal entry {
        print(f"[zookeeper] {here.name} gets standard feed.");
        visit [-->];
    }
}

walker SchoolGroup {
    has students: int = 0;

    can start with Root entry {
        print(f"[school] Group of {self.students} arrives to watch.");
        visit [-->];
    }

    can watch with Lion | Parrot | Animal entry {
        print(f"[school] {self.students} students watch {here.name}.");
        visit [-->];
    }
}

with entry {
    root ++> Lion(name="Leo")
        ++> Parrot(name="Polly", phrase="Polly wants a cracker")
        ++> Animal(name="Giraffe");

    root spawn Kiosk();
    zk = Zookeeper();
    root spawn zk;
    sg = SchoolGroup(students=24);
    root spawn sg;
}

