# I'm writing an order auditor in Jac and need both flavors of early return working side by side. Orders are nodes with an amount, a validity flag, and a fraud flag. Invalid orders should be skipped while the audit continues to later orders, but a flagged-fraud order must halt the whole walk on the spot. Print a line per order showing which action fired.
"""Order auditor: skip invalid orders, halt the walk on fraud flags.

Two flavors of early return live side by side:
  - `continue;` skips the current order but the walker keeps moving.
  - `disengage;` halts the walker entirely on the first fraud flag.
"""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud_flag: bool = False;
}

walker OrderAuditor {
    has total_amount: float = 0.0;
    has inspected: int = 0;

    can start with Root entry {
        print("Audit begin");
        visit [-->] else { disengage; }
    }

    can audit with Order entry {
        self.inspected += 1;

        if here.fraud_flag {
            print(f"[HALT] fraud on {here.label} (${here.amount}) -- disengaging");
            disengage;
        }

        if not here.valid {
            print(f"[SKIP] {here.label} invalid -- continuing");
            visit [-->] else { disengage; };
            return;
        }

        self.total_amount += here.amount;
        print(f"[OK]   {here.label} amount=${here.amount}");
        visit [-->] else { disengage; };
    }
}

with entry {
    root ++> Order(label="ORD-001", amount=120.50, valid=True)
        ++> Order(label="ORD-002", amount=88.25, valid=False)
        ++> Order(label="ORD-003", amount=300.00, valid=True)
        ++> Order(label="ORD-004", amount=45.00, valid=True, fraud_flag=True)
        ++> Order(label="ORD-005", amount=210.75, valid=True);

    auditor = OrderAuditor();
    root spawn auditor;

    print(f"Audit summary: inspected={auditor.inspected}, "
          f"total=${auditor.total_amount}");
}

