# A maintainer on the project kim-em/lean-zip (unknown) filed this issue about hand-rolled graph machinery causing pain:
# 
# Issue #2837: perf: land the rolling lazy2 deferral at L7 (certified +0.053pp at ~+2.4% matcher; multi-session proof threading)
# 
# Stage 1 of #2783 is now measured and certified (spike on branch `perf/lazy2-deferral`, `bench/ZipLazyRollSweep.lean`, commit 0a42c3d5): a true rolling pending-match deferral (cap 4, /4 probe ladder), composed with the hash3 singleton and seeded probe, gains **+0.053pp corpus-weighted Silesia at L7 for ~+2.4% matcher cost** — about 5x more ratio-efficient than the L7→L8 ladder direction, a genuine frontier gain. The mirror config (cap=1) is byte-identical to production on all 24 file×level pairs, so the harness is certified. L8 gains more (+0.068pp) but overruns its speed budget (~+7.3% matcher — each extra probe is ~8x costlier at chain 512).
# 
# What blocks landing: routing L7 through the rolling arm forces a re-thread of the entire lazy correctness tower (`lz77ChainLazy.mainLoop` + `_valid`/`_encodable` → `mainLoop_eq_chainLazy` → `lz77ChainLazyIterP_eq` → `mergedLoop_eq`), and the rolling arm emits a **data-dependent number of literals**, breaking the fixed-pushes-per-branch alignment every `strongRecOn` lockstep rung relies on — each rung needs a new nested induction over the rolling sub-recursion, with `lazy2Steps` universally quantified. This is a proper multi-session proof campaign per the sorry-policy, not a one-session force.
# 
# Plan: thread a `lazy2Steps : Nat := 1` knob through the tower one rung per session (intermediate commits with clearly-marked `sorry`s per the repo policy), starting from the boxed base; the spike stays the behavioral reference (its per-file table is the acceptance test). Ladder value: L7 → cap 4; L8 stays 1.
# 
# 🤖 Prepared with Claude Code
# 
# Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.
"""Lazy2 deferral rollout — model the correctness tower traversal.

A rolling lazy2 pending-match deferral (cap 4) needs to be threaded through a
chain of correctness proofs. Each rung depends on the previous one, and the
rolling arm emits a data-dependent number of literals, so every rung requires
a new induction. This demo models the tower as nodes connected by typed
``DependsOn`` edges and a walker that proves / fails / defers each rung in
order, surfacing the multi-session campaign the issue describes.
"""

# ----------------------------------------------------------------------
# Entity archetypes
# ----------------------------------------------------------------------

# Base correctness rung: the boxed reference implementation whose proofs
# are already accepted. Every other rung builds on it.
node BoxedBase {
    has rung_name: str = "boxedBase";
    has accepted: bool = True;
    has needs_sorry: bool = False;
}

# A pending-match rung. ``cap`` is the size of the rolling deferral
# ladder; ``literals`` is the (data-dependent) number of literals the
# arm may emit on a given input.
node LazyRung {
    has rung_name: str = "";
    has cap: int = 1;
    has literals: int = 0;
    has needs_sorry: bool = False;
    has proven: bool = False;
}

# A single sorry-bearing proof session. Sessions are sequenced along the
# tower and may depend on multiple earlier sessions (parallel induction
# hypotheses).
node ProofSession {
    has session_id: int = 0;
    has rung_label: str = "";
    has sorries: int = 0;
    has completed: bool = False;
}

# ----------------------------------------------------------------------
# Typed edges
# ----------------------------------------------------------------------

# "Rung R depends on rung R' — the rolling sub-recursion must be
# nested-induced after R' is locked in."
edge DependsOn {
    has reason: str = "";
}

# A proof session "threads" a specific lazy2 step count into a rung.
edge ThreadsStep {
    has lazy2_steps: int = 1;
}

# ----------------------------------------------------------------------
# Walker: walk the correctness tower and audit its rungs
# ----------------------------------------------------------------------

# ``TowerAuditor`` starts at root, fans out through ``DependsOn`` edges
# to every LazyRung in the tower, and at each rung fans in to the proof
# sessions that thread ``lazy2Steps`` through it. It guards against
# cycles (the tower graph can loop via shared sessions) with an
# explicit visited set, reports each rung's status, and accumulates a
# single exit report with the campaign summary.
walker TowerAuditor {
    has visited_rungs: list[str] = [];
    has visited_sessions: list[int] = [];
    has rungs_proven: int = 0;
    has rungs_deferred: int = 0;
    has total_sorries: int = 0;

    can start with Root entry {
        print("Tower audit starting at root");
        visit [->:DependsOn:->] else {
            print("  (no rungs attached)");
            disengage;
        }
    }

    can audit_rung with LazyRung entry {
        if here.rung_name in self.visited_rungs {
            print(f"  skip already-visited rung {here.rung_name}");
            disengage;
        }
        self.visited_rungs.append(here.rung_name);

        status = "PROVEN" if here.proven else "DEFERRED";
        sorry_note = " (sorry-bearing)" if here.needs_sorry else "";
        print(
            f"  rung[{here.rung_name}] cap={here.cap} "
            f"literals={here.literals} -> {status}{sorry_note}"
        );
        if here.proven {
            self.rungs_proven += 1;
        } else {
            self.rungs_deferred += 1;
        }

        # Walk to the proof sessions threading this rung.
        visit [here->:ThreadsStep:->] else {
            print(f"    (no proof sessions threaded for {here.rung_name})");
            disengage;
        }
    }

    can audit_session with ProofSession entry {
        if here.session_id in self.visited_sessions {
            return;  # silent skip — shared sessions shouldn't double-count
        }
        self.visited_sessions.append(here.session_id);
        self.total_sorries += here.sorries;
        done = "done" if here.completed else "open";
        print(
            f"    session[{here.session_id}] for {here.rung_label} "
            f"sorries={here.sorries} status={done}"
        );
    }

    can back with BoxedBase entry {
        # The boxed base is the certified anchor — note it and stop
        # walking deeper; the tower has reached its foundation.
        if here.rung_name in self.visited_rungs {
            disengage;
        }
        self.visited_rungs.append(here.rung_name);
        print(f"  anchor[boxedBase] accepted={here.accepted} (foundation)");
    }
}

# ----------------------------------------------------------------------
# Compatibility façade — keep the public "campaign" verb readable
# ----------------------------------------------------------------------

def run_campaign() -> TowerAuditor {
    auditor = TowerAuditor();
    root spawn auditor;
    return auditor;
}

# ----------------------------------------------------------------------
# Demo wiring
# ----------------------------------------------------------------------

with entry {
    # The boxed base anchors the tower.
    boxed = BoxedBase(rung_name="boxedBase", accepted=True, needs_sorry=False);

    # The lazy2 tower: ladder value L7 -> cap 4, L8 stays cap 1.
    l7 = LazyRung(rung_name="lz77ChainLazy", cap=1, literals=0, needs_sorry=False, proven=True);
    l7_rolling = LazyRung(rung_name="lz77ChainLazy.rolling", cap=4, literals=7, needs_sorry=True, proven=False);
    l7_iter = LazyRung(rung_name="lz77ChainLazyIterP", cap=4, literals=11, needs_sorry=True, proven=False);
    merged = LazyRung(rung_name="mergedLoop", cap=4, literals=13, needs_sorry=True, proven=False);
    l8_mirror = LazyRung(rung_name="L8Mirror", cap=1, literals=0, needs_sorry=False, proven=True);

    # Proof sessions — one per rung, each threading ``lazy2Steps=1`` by default.
    s1 = ProofSession(session_id=1, rung_label="lz77ChainLazy", sorries=0, completed=True);
    s2 = ProofSession(session_id=2, rung_label="lz77ChainLazy.rolling", sorries=3, completed=False);
    s3 = ProofSession(session_id=3, rung_label="lz77ChainLazyIterP", sorries=4, completed=False);
    s4 = ProofSession(session_id=4, rung_label="mergedLoop", sorries=2, completed=False);
    s5 = ProofSession(session_id=5, rung_label="L8Mirror", sorries=0, completed=True);

    # Tower topology (typed DependsOn edges):
    #   l7 -> l7_rolling -> l7_iter -> merged -> boxed
    #   l8_mirror -> boxed
    l7 +>:DependsOn(reason="boxed acceptance test"):+> l7_rolling;
    l7_rolling +>:DependsOn(reason="rolling sub-recursion induction"):+> l7_iter;
    l7_iter +>:DependsOn(reason="mergedLoop_eq_chainLazy"):+> merged;
    merged +>:DependsOn(reason="mergedLoop_eq foundation"):+> boxed;
    l8_mirror +>:DependsOn(reason="L8 mirror config sanity"):+> boxed;

    # Sessions threaded with lazy2Steps (the knob from the issue).
    l7 +>:ThreadsStep(lazy2_steps=1):+> s1;
    l7_rolling +>:ThreadsStep(lazy2_steps=1):+> s2;
    l7_iter +>:ThreadsStep(lazy2_steps=1):+> s3;
    merged +>:ThreadsStep(lazy2_steps=1):+> s4;
    l8_mirror +>:ThreadsStep(lazy2_steps=1):+> s5;

    # Hook the whole tower off root.
    root ++> l7 ++> l8_mirror;

    print("=== Lazy2 deferral tower ===");
    auditor = run_campaign();
    print(
        f"campaign summary: proven={auditor.rungs_proven} "
        f"deferred={auditor.rungs_deferred} "
        f"total_sorries={auditor.total_sorries}"
    );
}

