        self.seen.append(here.title);
        print(f"object: {here.label()}");
        visit [->:Uses:->] else { disengage; }
    }
}

walker ConsumerView {
    has seen: list[str] = [];

    can start with Root entry {
        print("consumer view");
        visit [->:Focus:->] else { disengage; }
    }

    can inspect with Measure | Column | ReportBinding entry {
        if here.title in self.seen {
            print(f"cycle ignored at {here.label()}");
            disengage;
        }
        self.seen.append(here.title);
        print(f"consumer: {here.label()}");
        visit [<--] else { disengage; }
    }
}

with entry {
    measure = Measure(
        title="'Sales'[Total Sales]",
        kind="measure",
        expression="SUM('Sales'[Revenue])",
        context="model"
    );
    revenue = Column(
        title="'Sales'[Revenue]",
        kind="column",
