    root +>:Focus:+> measure;
    measure +>:Uses(provenance="measure expression"):+> revenue;
    measure +>:Uses(provenance="measure expression"):+> quantity;
    card +>:Uses(provenance="visual 'Card' on page 1"):+> measure;
