"""Toll plaza G-4 collector: charge cars, trucks, and motorcycles, then sweep and report revenue."""

node Car {
    has label: str = "car";
    has axles: int = 2;
    has weight_tons: float = 0.0;
}

node Truck {
    has label: str = "truck";
    has axles: int = 4;
    has weight_tons: float = 0.0;
}

node Motorcycle {
    has label: str = "motorcycle";
    has axles: int = 2;
    has weight_tons: float = 0.0;
}

walker TollCollector {
    has revenue: float = 0.0;

    can start with Root entry {
        print("Gate G-4 sweep begins");
        visit [-->];
    }

    can collect_car with Car entry {
        charge = 2.50;
        self.revenue = self.revenue + charge;
        print(f"car axles={here.axles} weight={here.weight_tons}t -> paid ${charge:.2f}");
        visit [-->];
    }

    can collect_truck with Truck entry {
        charge = 2.50 + 0.50 * here.weight_tons;
        self.revenue = self.revenue + charge;
        print(f"truck axles={here.axles} weight={here.weight_tons}t -> paid ${charge:.2f}");
        visit [-->];
    }

    can collect_motorcycle with Motorcycle entry {
        charge = 1.00;
        self.revenue = self.revenue + charge;
        print(f"motorcycle axles={here.axles} weight={here.weight_tons}t -> paid ${charge:.2f}");
        visit [-->];
    }
}

with entry {
    root ++> Car()
        ++> Truck(weight_tons=8.0)
        ++> Motorcycle()
        ++> Truck(weight_tons=12.5)
        ++> Car();

    collector = TollCollector();
    root spawn collector;
    print(f"Gate G-4 total revenue: ${collector.revenue:.2f}");
}

