"""G-buffer VRAM audit walker.

Models the docs/engine/memory-budget.md under-count row: a G-buffer is a
chain of attachments (HDR colour, depth, depth_history, plus the FSR
masks). A walker walks the attachment chain using a typed ``Sized``
relationship, totals the live attachment VRAM at each resolution, and
reports whether the row understates the live set. A cycle guard
prevents infinite traversal on cyclic attachment graphs.
"""

node Attachment {
    has name: str = "";
    has bytes_per_pixel: float = 0.0;
    has frames_in_flight: int = 0;
}

node GBufferDocRow {
    has label: str = "";
    has claimed_mb_1080p: float = 0.0;
    has claimed_mb_4k: float = 0.0;
}

edge Sized { }

walker VramAuditor {
    has pixels_1080p: int = 1920 * 1080;
    has pixels_4k: int = 3840 * 2160;
    has audited_total_mb_1080p: float = 0.0;
    has audited_total_mb_4k: float = 0.0;
    has visited: list = [];

    can start with Root entry {
        visit [-->];
    }

    can tally with GBufferDocRow entry {
        print(f"Auditing doc row: {here.label}");
        print(f"  claimed: ~{here.claimed_mb_1080p:.1f} MB @ 1080p, "
              f"~{here.claimed_mb_4k:.1f} MB @ 4K");
        visit [->:Sized:->];
    }

    can sum_attachment with Attachment entry {
        # Cycle guard: attachment chains must be acyclic.
        if here.name in self.visited {
            print(f"  [CYCLE] revisit {here.name}; stopping walk");
            disengage;
        }
        self.visited.append(here.name);

        bytes_1080p = here.bytes_per_pixel * self.pixels_1080p * here.frames_in_flight;
        bytes_4k = here.bytes_per_pixel * self.pixels_4k * here.frames_in_flight;
        mb_1080p = bytes_1080p / (1024.0 * 1024.0);
        mb_4k = bytes_4k / (1024.0 * 1024.0);
        self.audited_total_mb_1080p += mb_1080p;
        self.audited_total_mb_4k += mb_4k;
        print(f"  + {here.name}: {here.bytes_per_pixel} B/px x "
              f"{here.frames_in_flight} FIF = {mb_1080p:.1f} MB @ 1080p, "
              f"{mb_4k:.1f} MB @ 4K");
        visit [->:Sized:->];
    }
}

