# Health-inspect a restaurant kitchen line (grill, fryer, cold prep): check each station's temperature, flagging anything above 40 C as a violation, and separately log every station visit. Both checks must run at every station.
"""Kitchen line health inspection.

Two walkers sweep the same station graph: one flags stations whose
temperature reading exceeds 40 C as a health violation, and the other
logs every station visit. Both walkers must visit every station so the
violation report and the visit log are complete.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
}

walker TempInspector {
    can start with Root entry {
        visit [-->];
    }

    can inspect with Station entry {
        violation = "VIOLATION" if here.celsius > 40.0 else "OK";
        print(f"[{violation}] {here.name}: {here.celsius} C");
        visit [-->];
    }
}

walker VisitLogger {
    has log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can log_visit with Station entry {
        self.log.append(here.name);
        print(f"logged visit to {here.name}");
        visit [-->];
    }
}

with entry {
    grill = Station(name="grill", celsius=180.0);
    fryer = Station(name="fryer", celsius=165.0);
    cold_prep = Station(name="cold prep", celsius=4.0);
    root ++> grill ++> fryer ++> cold_prep;

    root spawn TempInspector();
    logger = VisitLogger();
    root spawn logger;
    print(f"visit log: {logger.log}");
}

