# I'm marking out a hiking trail in Jac as a chain of plain waypoints between the trailhead and the summit — the waypoints themselves don't need to hold any data at all. Give me a hiker walker that travels the trail and counts how many waypoints it passes, printing each stop number along the way and a completion line once it has passed enough of them.
"""Hiking trail: chain waypoints from trailhead to summit; a hiker walker counts stops."""

node TrailHead {
    has label: str = "Trailhead";
}

node Waypoint {
    has marker: str = "";
}

node Summit {
    has label: str = "Summit";
}

walker Hiker {
    has stop_number: int = 0;

    can start with Root entry {
        print("Setting out from the trailhead...");
        visit [-->];
    }

    can depart with TrailHead entry {
        visit [-->];
    }

    can pass_waypoint with Waypoint entry {
        self.stop_number += 1;
        print(f"Stop {self.stop_number}");
        visit [-->];
    }

    can finish with Summit entry {
        print(f"Hike complete: passed {self.stop_number} waypoints along the trail.");
        disengage;
    }
}

with entry {
    root ++> TrailHead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();
    root spawn Hiker();
}

