    root ++> WeatherStation(location="Downtown", celsius=22.5)
        ++> WeatherStation(location="Airport", celsius=19.0)
        ++> WeatherStation(location="Hilltop", celsius=27.3)
        ++> WeatherStation(location="Harbor", celsius=15.8);
