"""Watch invalidation gap: declared dependency manifest changes outside the
imported module graph.

Models the Phase-A failure mode of ``smc watch``: a cheap fingerprint is
built only over the source ``Imports`` edges actually walked, while declared
``Depends`` relationships carry their own governing manifests. A declared
dependency's manifest can therefore change without the watch fingerprint
moving, and the declared-dependency cache is never reset.

We model:

  Module            -- a source module (the import graph)
  DeclaredDep       -- a declared dependency of an entry package
  EntryPackage      -- the watched package
  Manifest          -- a governing manifest content blob (typed field)

Edges carry the relationship type:

  Imports    -- source-import edge walked by the fingerprint
  Depends    -- declared-dependency edge (NOT walked by the fingerprint)
  GovernedBy -- module -> its nearest governing manifest

The ``CheapFingerprint`` walker mirrors the narrow behavior: it follows
``Imports`` + ``GovernedBy`` and only touches manifests reachable that way.
A dependent manifest change outside the imported graph is invisible to it.

The ``DeclaredAudit`` walker mirrors the broader behavior: it follows the
declared ``Depends`` edge type and folds every transitively declared
manifest, exposing the trust/provenance gap.
"""

node Module {
    has name: str = "";
    has source: str = "";
}

node DeclaredDep {
    has name: str = "";
    has kind: str = "runtime";
}

node EntryPackage {
    has name: str = "";
}

node Manifest {
    has owner: str = "";
    has content: str = "";
}

# Source-import edge: walked by the cheap fingerprint.
edge Imports {
    has line: int = 0;
}

# Declared-dependency edge: NOT walked by the cheap fingerprint (gap).
edge Depends {
    has kind: str = "runtime";
}

# Module / dependency -> its nearest governing manifest.
edge GovernedBy { }


# -- Cheap fingerprint walker (the narrow, buggy signal) ---------------------
walker CheapFingerprint {
    has visited: list[str] = [];
    has manifests_seen: list[str] = [];
    has fp: str = "";

    can start with Root entry {
        visit [->:Imports:->];
    }

    can walk_imports with Module entry {
        if here.name not in self.visited {
            self.visited.append(here.name);
            self.fp = self.fp + f"M[{here.name}]";
            visit [->:GovernedBy:->];
            visit [->:Imports:->];
        } else {
            disengage;
        }
    }

    can fold_manifest with Manifest entry {
        self.manifests_seen.append(here.owner);
        self.fp = self.fp + f"G[{here.owner}={here.content}]";
    }
}


# -- Declared-audit walker (the broader trust/provenance surface) ------------
walker DeclaredAudit {
    has visited: list[str] = [];
    has declared_seen: list[str] = [];
    has surface: str = "";

    can start with Root entry {
        visit [->:Depends:->];
    }

    can walk_declared with DeclaredDep | Module entry {
        key = f"D[{here.name}]" if isinstance(here, DeclaredDep) else f"M[{here.name}]";
        if key not in self.visited {
            self.visited.append(key);
            self.declared_seen.append(here.name);
            self.surface = self.surface + key + " ";
            visit [->:GovernedBy:->];
            visit [->:Depends:->];
        } else {
            disengage;
        }
    }

    can fold_manifest with Manifest entry {
        self.surface = self.surface + f"G[{here.owner}={here.content}] ";
    }
}


# -- A single walker that runs BOTH passes and reports the gap ---------------
walker WatchInvalidator {
    has fp: str = "";
    has admitted_cache: str = "VALID";

    can start with Root entry {
        cheap = CheapFingerprint();
        root spawn cheap;
        self.fp = cheap.fp;

        audit = DeclaredAudit();
        root spawn audit;
        declared_surface = audit.declared_seen;

        cheap_owners = cheap.manifests_seen;
        missing: list[str] = [];
        for owner in declared_surface {
            if owner not in cheap_owners {
                missing.append(owner);
            }
        }

        if len(missing) > 0 {
            self.admitted_cache = "STALE";
            print(f"[GAP] cheap fp={self.fp!r} unchanged; "
                  f"declared manifests not folded: {missing}; "
                  f"admission cache left {self.admitted_cache}");
        } else {
            print(f"[OK] cheap fp={self.fp!r} covers all declared "
                  f"manifests ({cheap_owners})");
        }
        disengage;
    }
}


