    claude_bind +>:HostsEgress(side="host"):+> host_tools;

    auditor = BindingAuditor();
    root spawn auditor;
    for line in auditor.findings {
        print(line);
    }

    print("--- stale-binding scenario ---");
    root spawn StaleInvalidator(target_name="exec-A");
