node VisualizationMap {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has map_id: str = "";
}

node KnowledgeUnit {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has stable_id: str = "";
    has lifecycle: str = "current";
}

edge Displays {
    has view_name: str = "";
}

edge Contains {
    has role: str = "";
}

edge Prerequisite {
    has reason: str = "";
}

walker DependencyAuditor {
    has visited_ids: list[str] = [];
    has checked_count: int = 0;
    has cycle_count: int = 0;

    can begin with Root entry {
        print("Starting dependency audit from the visualization canvas");
        visit [-->] else {
            disengage;
        }
    }

    can open_canvas with Canvas entry {
        print(f"Canvas: {here.title} ({here.viewport})");
        visit [->:Displays:->] else {
            disengage;
        }
    }

    can open_map with VisualizationMap entry {
        print(f"Map {here.map_id}: {here.title}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_unit with KnowledgeUnit entry {
        if here.stable_id in self.visited_ids {
            self.cycle_count += 1;
            print(f"Cycle detected at {here.stable_id}; dependency walk stops on this branch");
