    knowledge_map +>:Contains(role="focus"):+> triage;
    triage +>:Prerequisite(reason="requires telemetry"):+> logging;
    logging +>:Prerequisite(reason="feeds response"):+> containment;
    containment +>:Prerequisite(reason="intentional cycle probe"):+> triage;

    root spawn DependencyAuditor();
}

