    has draft_id: str = "";
    has rationale: str = "";
    has residual_uncertainty: str = "";
}

node Release {
    has release_id: str = "";
    has version: int = 0;
    has predecessor_evidence: str = "";
}

node Binding {
    has binding_id: str = "";
    has scope: str = "";
    has environment: str = "";
}

node Reassessment {
    has assessment_id: str = "";
    has preregistered: bool = True;
    has result: str = "PENDING";
    has rationale: str = "";
}

# ---------- Typed edges (relationships carry meaning) ----------

edge ProducedBy {
    has attempt: int = 0;
}

edge Binds {
    has consequence_class: str = "low";
}

edge Triggers {
    has condition: str = "";
}

edge Reenters {
    has directive: str = "";
