node Stage {
    has title: str = "";
    has command: str = "";
    has passed: bool = False;
    has critical: bool = True;
    has host: str = "";
}

node Job {
    has name: str = "";
}

edge DependsOn {
    has order: int = 0;
}

edge AssignedTo {
    has slot: int = 0;
