    has blocked: bool = False;
    has visited: list[str] = [];

    can start with Root entry {
        print("git push received -> GitHub Actions triggered");
        visit [-->];
    }

    can enter_job with Job entry {
        print(f"  [job] {here.name}");
        visit [-->];
    }

    can run_stage with Stage entry {
        # Cycle guard: stages are tracked by title; revisit = cycle.
        for tag in self.visited {
            if tag == here.title {
                cycle_msg = f"    CYCLE detected at stage '{here.title}'";
                print(cycle_msg);
                self.blocked = True;
                disengage;
            }
        }
        self.visited.append(here.title);

        if not here.passed {
            outcome = "FAIL";
            print(f"    [{outcome}] {here.title}: {here.command} on {here.host}");
            if here.critical {
                self.blocked = True;
                print("    critical stage failed -> workflow halted");
                disengage;
            }
        } else {
            print(f"    [PASS] {here.title}: {here.command} on {here.host}");
        }
        visit [-->];
    }
}

