    lint = Job(name="lint");
    build = Job(name="build");

    test_stage = Stage(title="tests", command="pytest", passed=True, critical=True, host="ubuntu-22.04");
    lint_stage = Stage(title="lint", command="ruff check", passed=False, critical=True, host="ubuntu-22.04");
