# ---------- entity archetypes ----------

node Finding {
    has file_path: str = "";
    has line: int = 0;
    has kind: str = "";
    has message: str = "";
    has confidence: float = 0.0;

    def fingerprint() -> str {
        return f"{self.file_path}:{self.line}:{self.kind}";
    }
}

node Repo {
    has name: str = "";
    has commit_pin: str = "";
}

node Corpus {
    has label: str = "";
}

# ---------- relationship archetypes ----------

edge ContainsRepo { }     # Corpus → Repo
edge HasFinding { }      # Repo → Finding

# ---------- walker: performs the blast-radius diff ----------

