node Project {
    has name: str = "";
    has base_dir: str = "";
}

node SharedRoot {
    has directory_name: str = "";
    has drained: bool = False;
}

node Directory {
    has path: str = "";
}

node Module {
    has path: str = "";
    has resolved: bool = False;
}

node ImportRequest {
    has specifier: str = "";
    has status: str = "pending";
    has resolved_path: str = "";
}

# --- Edge archetypes --------------------------------------------------------

edge OwnedBy {}
edge SearchedAt {}
edge HostsModule {}
edge Requests {}

# --- The resolver walker ----------------------------------------------------

walker ResolveRequest {
    has trace: list[str] = [];
    has hit: str = "";

    can start with ImportRequest entry {
        print(f"[req] resolving '{here.specifier}' "
              f"(status={here.status})");
        if here.status != "pending" {
            return;
