"""Hermes config append scenario: hooks list with a security guard that
refuses whole-file rewrites, so the only honest path is in-place append
of a typed config entry, followed by explicit allowlist approval."""

node ConfigRoot {
    has name: str = "config.yaml";
    has version: int = 37;
}

node HookList {
    has event: str = "";
}

node HookEntry {
    has command: str = "";
    has timeout: int = 9;
    has matcher: str = "";
    has fail_closed: bool = False;
    has approved: bool = False;
}

edge OwnsHooks {}
edge HookOf {}
edge Allowlisted {}

walker AppendConfig {
    has event: str = "pre_llm_call";
    has command: str = "";
    has timeout: int = 9;
    has appended: bool = False;

    can start with ConfigRoot entry {
        print(f"config {here.name} (v{here.version}): requesting append to {self.event}");
        visit [->:OwnsHooks:->];
    }

    can descend with HookList entry {
        if here.event == self.event {
            already_present = False;
            for n in [-->] {
                if n.command == self.command {
                    already_present = True;
                }
            }
            if already_present {
                print(f"hook already present: {self.command}");
                disengage;
            }
            new_entry = HookEntry(
                command=self.command,
                timeout=self.timeout,
                matcher="*",
                fail_closed=False
            );
            here +>:HookOf:+> new_entry;
            self.appended = True;
            print(f"appended hook to {here.event}: command={self.command}");
            disengage;
        }
    }
}

walker ApproveHook {
    has event: str = "pre_llm_call";
    has command_match: str = "";

    can start with ConfigRoot entry {
        print(f"allowlist pass: event={self.event}, command={self.command_match}");
        visit [->:OwnsHooks:->];
    }

    can find_list with HookList entry {
        if here.event == self.event {
            visit [-->];
        }
    }

    can approve with HookEntry entry {
        if here.command == self.command_match {
            here.approved = True;
            here +>:Allowlisted:+> here;
            print(f"approved hook: {here.command}");
        }
    }
}

walker AuditHooks {
    has event: str = "pre_llm_call";

    can start with ConfigRoot entry {
        print(f"--- audit {self.event} hooks ---");
        visit [->:OwnsHooks:->];
    }

    can list_event with HookList entry {
        if here.event == self.event {
            visit [-->];
        }
    }

    can show with HookEntry entry {
        status = "APPROVED" if here.approved else "PENDING";
        print(f"  - [{status}] {here.command} (timeout={here.timeout}s)");
    }
}

with entry {
    cfg = ConfigRoot(name="~/.hermes/config.yaml", version=37);
    pre_llm = HookList(event="pre_llm_call");
    post_llm = HookList(event="post_llm_call");

    cfg +>:OwnsHooks:+> pre_llm;
    cfg +>:OwnsHooks:+> post_llm;

    initial = HookEntry(
        command="/old/pre.py",
        timeout=9,
        matcher="*",
        fail_closed=False,
        approved=True
    );
    pre_llm +>:HookOf:+> initial;

    print("=== scenario 1: attempt whole-file rewrite (refused by guard) ===");
    print("write_file/patch refuse config.yaml: edit via 'hermes config' instead");
    print("");

    print("=== scenario 2: append new hook entry ===");
    root spawn AppendConfig(
        event="pre_llm_call",
        command="/path/new.py",
        timeout=12
    );

    print("");
    print("=== scenario 3: append a duplicate (must be detected) ===");
    root spawn AppendConfig(
        event="pre_llm_call",
        command="/path/new.py",
        timeout=12
    );

    print("");
    print("=== scenario 4: approve the new hook on the allowlist ===");
    root spawn ApproveHook(
        event="pre_llm_call",
        command_match="/path/new.py"
    );

    print("");
    root spawn AuditHooks(event="pre_llm_call");
}

