# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node Module {
    has name: str = "";
    has loc: int = 0;
    has duplicates_protocol: bool = False;
}

node Book {
    has channel: str = "";
    has kind: str = "snapshot";
    has stale: bool = False;
}

edge Imported {
    has from_module: str = "";
    has to_module: str = "";
}

edge Subscribes {
    has channel: str = "";
}

edge DependsOn {
    has weight: int = 1;
}

# ---------------------------------------------------------------------------
# Walker: CouplingAuditor
# ---------------------------------------------------------------------------

walker CouplingAuditor {
    has report_lines: list[str] = [];
    has visited: list[str] = [];
    has cycle_found: bool = False;
    has dup_sites: list[str] = [];

    can start with Root entry {
        print("=== Coupling audit: trader ↔ kx_orderbooks ===");
        visit [-->];
    }

    can audit_module with Module entry {
        key = here.name;
        already = False;
        for v in self.visited {
            if v == key {
                already = True;
            }
        }
        if already {
            return;
        }
        self.visited.append(key);
        self.report_lines.append(
            f"module {here.name} ({here.loc} LOC)"
        );
        if here.duplicates_protocol {
            site = f"{here.name} re-implements WS protocol handling";
            self.dup_sites.append(site);
            self.report_lines.append(f"  ! {site}");
        }
        visit [->:Imported:->];
    }

    can audit_book with Book entry {
        line = f"book channel={here.channel} kind={here.kind}";
        if here.stale {
            line = line + " STALE";
        }
        self.report_lines.append(f"  -> {line}");
        visit [->:Subscribes:->];
    }

    can find_cycles with Module entry {
        nexts = [->:DependsOn:->];
        for n in nexts {
            edge_line = f"{here.name} --{n.name}--";
            self.report_lines.append(f"  cycle probe: {edge_line}");
            if n.name == self.visited[0] and len(self.visited) > 1 {
                self.cycle_found = True;
                self.report_lines.append(
                    f"  CYCLE: {' -> '.join(self.visited)} -> {n.name}"
                );
            }
        }
        visit [->:DependsOn:->];
    }
