    book_fast = Book(channel="fast", kind="delta");
    book_snap = Book(channel="snap", kind="snapshot");

    # Typed edges.
    edge1 = Imported(from_module="kx_orderbooks", to_module="feed_adapter");
    engine +>:edge1:+> feed;
    edge2 = Imported(from_module="kalshi_broadcast_word_trader", to_module="kx_orderbooks");
    trader +>:edge2:+> engine;
    edge3 = Imported(from_module="kalshi_broadcast_word_trader", to_module="feed_adapter");
    trader +>:edge3:+> feed;

    sub1 = Subscribes(channel="fast");
    engine +>:sub1:+> book_fast;
    sub2 = Subscribes(channel="snap");
    engine +>:sub2:+> book_snap;
    sub3 = Subscribes(channel="fast");
    trader +>:sub3:+> book_fast;

