    # snap depends on fast. This is the issue's "recommend single source
    # of truth" warning sign.
    dep1 = DependsOn(weight=2);
    book_fast +>:dep1:+> book_snap;
    dep2 = DependsOn(weight=2);
    book_snap +>:dep2:+> book_fast;

    auditor = CouplingAuditor();
    root spawn auditor;

    print("\n--- import map ---");
    for line in auditor.report_lines {
        print(line);
    }
    print("\n--- recommendation ---");
    if auditor.dup_sites {
        print("single source of truth: route all WS frames through "
              "kx_orderbooks; remove duplicated protocol code at:");
        for line in auditor.dup_sites {
            print(f"  - {line}");
        }
    }
    if auditor.cycle_found {
        print("WARNING: circular book dependency detected -- break the "
