"""Review tier routing: declare blast-radius paths so required review depth is schema, not judgment.

Models the gap in Issue #482 — review depth is currently tiered by prose judgment
("high-risk, concurrent-batch, or RC PRs"). This demo models the proposed
`review_tiers` seam: path patterns mapped to required review depth, consumed by
a walker that walks the changed paths and reports which review gates must fire.
"""

# A path-glob entry the consumer repo declares at its seam.
node PathPattern {
    has pattern: str = "";
    has tier: str = "standard";
    has rationale: str = "";
}

# A changed file on a PR, carrying its own blast radius classification.
node ChangedPath {
    has file_path: str = "";
    has risk_class: str = "normal";
}

# A collected finding: this gate is required for this changed path.
node Finding {
    has file_path: str = "";
    has gate_label: str = "";
    has tier: str = "";
}

edge DeclaredAt { }     # PathPattern declared on the repo seam.
edge Affects { }        # ChangedPath is touched by this PR.

walker TierRouter {
    has findings: list = [];

    can start with Root entry {
        # Walk declared patterns first, then route the changed paths.
        visit [->:DeclaredAt:->];
    }

    can index_pattern with PathPattern entry {
        visit [->:DeclaredAt:->];
    }

    # For each changed path, decide which review gate label is mandated
    # based on the matching pattern's tier. We model the glob match as a
    # substring check (a real impl would use a glob engine); the routing
    # semantics the issue cares about are preserved.
    can route with ChangedPath entry {
        declared = [->:DeclaredAt:->];
        for pat in declared {
            if pat.pattern != "" and pat.pattern in here.file_path {
                gate_label = (
                    "ADVERSARIAL+SECURITY+HUMAN" if pat.tier == "critical"
                    else "ADVERSARIAL+SECURITY" if pat.tier == "high"
                    else "ADVERSARIAL" if pat.tier == "standard"
                    else "LINT"
                );
                self.findings.append(
                    Finding(
                        file_path=here.file_path,
                        gate_label=gate_label,
                        tier=pat.tier
                    )
                );
            }
        }
        visit [->:Affects:->];
    }

    can summarize with Finding entry {
        visit [-->];
    }
}

with entry {
    # Declared blast-radius patterns at the repo seam. Absence of any
    # declaration preserves today's judgment-based behavior (opt-in).
    pay_pattern = PathPattern(pattern="payments/", tier="critical",
                              rationale="payments path -> critical blast radius");
    auth_pattern = PathPattern(pattern="auth/", tier="high",
                               rationale="auth path -> high blast radius");
    doc_pattern = PathPattern(pattern="docs/", tier="low",
                              rationale="docs path -> low blast radius");

    # The PR's changed paths with their derived risk classes.
    pr_touched = [
        ChangedPath(file_path="payments/charge.rb", risk_class="critical"),
        ChangedPath(file_path="auth/session.rb", risk_class="high"),
        ChangedPath(file_path="docs/README.md", risk_class="low"),
        ChangedPath(file_path="lib/util.rb", risk_class="normal"),
    ];

    # Wire the seam: root -> declared patterns (DeclaredAt) and
    # root -> changed paths (Affects).
    root +>:DeclaredAt:+> pay_pattern;
    root +>:DeclaredAt:+> auth_pattern;
    root +>:DeclaredAt:+> doc_pattern;
    root +>:Affects:+> pr_touched[0];
    root +>:Affects:+> pr_touched[1];
    root +>:Affects:+> pr_touched[2];
    root +>:Affects:+> pr_touched[3];

    # Spawn the router walker on root. It walks patterns, then routes
    # each changed path through the declared tiers, producing findings.
    router = TierRouter();
    root spawn router;

    # Single exit report from accumulated walker state.
    print(f"Review Completion Gate requires {len(router.findings)} mandated reviews:");
    for f in router.findings {
        print(f"  - [{f.tier.upper()}] {f.file_path} -> {f.gate_label}");
    }
    routed_paths = [f.file_path for f in router.findings];
    for p in pr_touched {
        if not (p.file_path in routed_paths) {
            print(f"  - [judgment] {p.file_path} -> no declared tier, defer to per-PR judgment");
        }
    }
}

