# Guests at our hotel walk past service desks (spa session, room-service dinner, express laundry); each desk adds its price to whichever guest is currently passing by. Print each charge as it happens and what each guest owes at checkout.
"""Hotel corridor of service desks: guests walk past desks, each adds its price to the guest, and we print charges and totals."""

node Guest {
    has name: str = "";
    has total_owed: float = 0.0;
}

node Desk {
    has service: str = "";
    has price: float = 0.0;
}

walker GuestWalker {
    has current_guest_name: str = "";
    has running_total: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    can charge with Desk entry {
        self.running_total += here.price;
        print(f"Charging {here.service} (${here.price})");
        visit [-->];
    }

    can arrive with Guest entry {
        here.total_owed = self.running_total;
        print(f"{here.name} owes ${here.total_owed} at checkout");
    }
}

with entry {
    root ++> Desk(service="spa", price=45.0)
        ++> Desk(service="room-service dinner", price=32.5)
        ++> Desk(service="express laundry", price=18.0)
        ++> Guest(name="Alice");

    w = GuestWalker();
    root spawn w;
}

