def _parents_of(g: Composer, name: str) -> list[str] {
    c = g.resolve(name);
    if c is None {
        return [];
    }
    w = c spawn ParentHop();
    return w.outs;
}

def _children_of(g: Composer, name: str) -> list[str] {
    c = g.resolve(name);
    if c is None {
        return [];
    }
    w = c spawn ChildHop();
    return w.outs;
}

def create_generator(g: Composer, name: str, parents: list[str] = []) -> None {
    for p in parents {
        if g.resolve(p) is None {
            raise KeyError(p);
        }
    }
    c = Column(name=name);
    root ++> c;
    g.cols[name] = c;
    for p in parents {
        pc = g.resolve(p);
        if pc is None {
            continue;
        }
        c +>:DependsOn:+> pc;
        pc +>:DependentOf:+> c;
    }
