def bust_live_cache(
    w: CompilerCacheWorld,
    seeds: list[str],
    cache: dict[str, str],
) -> list[str] {
    victims = invalidation_closure(w, seeds);
    for art in victims {
        if art in cache {
            del cache[art];
        }
    }
    return victims;
}

