"""Hermes authority execution: carry a scoped proof to exact operations and settle each result."""

node AuthorityCarrier {
    has principal: str = "";
    has generation: int = 0;
    has scope: str = "";
    has valid: bool = False;
}

node Operation {
    has action: str = "";
    has target: str = "";
    has required_principal: str = "";
    has required_generation: int = 0;
    has required_scope: str = "";
    has candidate_route: str = "";
    has applied: bool = False;
}

node Receipt {
    has target: str = "";
    has generation: int = 0;
    has accepted: bool = False;
    has reason: str = "";
}

edge Admits { }

edge CarriesProof {
    has scope: str = "";
    has generation: int = 0;
}

edge ProducesReceipt { }

walker AuthorityGate {
    has proof_principal: str = "";
    has proof_generation: int = 0;
    has proof_scope: str = "";
    has proof_valid: bool = False;
    has hop_count: int = 0;
    has max_hops: int = 8;
    has last_authorized: bool = False;
    has last_reason: str = "";

    can admit with Root entry {
        print("admission: selecting explicit authority carriers");
        visit [->:Admits:->] else { disengage; }
    }

    can carry with AuthorityCarrier entry {
        if self.hop_count >= self.max_hops {
            print("refused: authority traversal exceeded its generation fence");
            disengage;
        } else {
            self.hop_count = self.hop_count + 1;
            self.proof_principal = here.principal;
            self.proof_generation = here.generation;
            self.proof_scope = here.scope;
            self.proof_valid = here.valid;
            print(f"proof: {here.principal} generation {here.generation} scope {here.scope}");
            visit [->:CarriesProof:->] else { disengage; }
        }
    }

    can authorize with Operation entry {
        identity_match = self.proof_principal == here.required_principal;
        generation_match = self.proof_generation == here.required_generation;
        scope_match = self.proof_scope == here.required_scope;
        authorized = self.proof_valid and identity_match and generation_match and scope_match;
        self.last_authorized = authorized;
        here.applied = authorized;

        if authorized {
            self.last_reason = "accepted: exact identity, scope, and generation";
        } else {
            if not self.proof_valid {
                self.last_reason = "refused: carrier was invalidated";
            } else {
                if not identity_match {
                    self.last_reason = "refused: identity mismatch";
                } else {
                    if not generation_match {
                        self.last_reason = "refused: stale generation";
                    } else {
