    has status: str = "idle";
}

node ChannelThread {
    has title: str = "";
    has status: str = "idle";
}

node ChildSession {
    has title: str = "";
    has status: str = "idle";
}

# ---- Edge archetypes ----------------------------------------------------

# Transcript provenance: "this session was forked from that session."
edge ForkSource {
    has forked_from_label: str = "";
}

# Runtime ownership / delegation.
edge SpawnedBy {
    has spawned_by_label: str = "";
}

# Channel / thread containment.
edge ChannelChild {
    has channel_label: str = "";
}

# ---- Walkers ------------------------------------------------------------

walker SidebarRenderer {
    # Walks the ownership/sidebar hierarchy (SpawnedBy + ChannelChild)
    # and renders rows. Forks appear as top-level peers because they
    # only carry ForkSource edges, not SpawnedBy edges.

    can start with Root entry {
        visit [-->];
    }

    can render_session with Session entry {
        print(f"[sidebar] session: {here.title} ({here.status})");
        visit [->:SpawnedBy:->];
        visit [->:ChannelChild:->];
    }

    can render_fork with ForkedSession entry {
        # Forks are peers: do NOT follow ownership edges from them.
        print(f"[sidebar] forked: {here.title} ({here.status})");
    }

    can render_subagent with SubagentSession entry {
        print(f"[sidebar] subagent: {here.title} ({here.status})");
        visit [->:SpawnedBy:->];
        visit [->:ChannelChild:->];
    }

    can render_thread with ChannelThread entry {
        print(f"[sidebar] thread: {here.title} ({here.status})");
        visit [->:ChannelChild:->];
    }

    can render_child with ChildSession entry {
        print(f"[sidebar] child: {here.title} ({here.status})");
    }
}

walker LineageProbe {
    # Walks ONLY the ForkSource edges to demonstrate that fork
    # provenance is preserved and independent of the sidebar tree.

    can start with Root entry {
        visit [-->];
    }

    can scan_session with Session entry {
        visit [->:ForkSource:->];
    }

    can scan_fork with ForkedSession entry {
        print(f"[lineage] {here.title} is a fork");
        visit [->:ForkSource:->];
    }

    can scan_subagent with SubagentSession entry {
        visit [->:ForkSource:->];
    }

    can scan_thread with ChannelThread entry {
        visit [->:ForkSource:->];
    }

    can scan_child with ChildSession entry {
        visit [->:ForkSource:->];
    }
}

# ---- Demo wiring --------------------------------------------------------

with entry {
    # A plain session that spawns two things: a true subagent (ownership)
    # and an ordinary fork (just transcript provenance).
    main = Session(title="main-session", status="running");
    root ++> main;

    # 1) A real subagent — owned, delegated, follows SpawnedBy.
    sub = SubagentSession(title="research-subagent", status="running");
    main +>:SpawnedBy(spawned_by_label="main-session"):+> sub;

    # 2) An ordinary fork — only a ForkSource edge, no SpawnedBy edge.
    #    In the buggy UI this was being nested as a child because
    #    parentSessionKey was read as the navigation parent.
    fork1 = ForkedSession(title="design-sketch", status="idle");
    main +>:ForkSource(forked_from_label="main-session"):+> fork1;

    # 3) A second fork of the same source — would have stacked deeply
    #    under main in the old rendering.
    fork2 = ForkedSession(title="alt-approach", status="idle");
    main +>:ForkSource(forked_from_label="main-session"):+> fork2;

    # 4) A channel thread with a real contained child (ownership).
    thread = ChannelThread(title="design-thread", status="running");
    main +>:ChannelChild(channel_label="design"):+> thread;
    child = ChildSession(title="thread-note-1", status="idle");
    thread +>:ChannelChild(channel_label="design"):+> child;

    # --- Spawn the sidebar renderer ---
    # Expected sidebar output: every row is top-level under "main-session".
    # Forks appear as peers (no SpawnedBy edge followed).
    # The subagent and the thread-with-child follow their ownership edges.
    print("=== Sidebar render (ownership only) ===");
    root spawn SidebarRenderer();

    # --- Spawn the lineage probe ---
    # Demonstrates that fork provenance is fully preserved and
    # recoverable through the dedicated ForkSource edges, even though
    # those edges do NOT participate in sidebar placement.
    print("=== Lineage probe (fork provenance only) ===");
    root spawn LineageProbe();
}

