# Build a toll plaza collector for gate G-4: cars pay $2.50, trucks pay $2.50 plus 50 cents per ton, motorcycles pay $1.00. Print one payment line per vehicle describing it, and report the revenue collected after the sweep.
"""Toll plaza G-4: walkers sweep vehicles and compute lane revenue."""

node Vehicle {
    has plate: str = "";
    def fee() -> float {
        return 0.0;
    }
}

node Car(Vehicle) {
    has passes: int = 1;
    override def fee() -> float {
        return 2.50 * self.passes;
    }
}

node Truck(Vehicle) {
    has tons: float = 0.0;
    override def fee() -> float {
        return 2.50 + 0.50 * self.tons;
    }
}

node Motorcycle(Vehicle) {
    override def fee() -> float {
        return 1.00;
    }
}

node Lane {
    has lane_name: str = "";
}

walker Cashier {
    has collected: float = 0.0;

    can start with Root entry {
        print("Cashier opening booth G-4");
        visit [-->];
    }

    can approach with Lane entry {
        visit [-->];
    }

    can charge with Car | Truck | Motorcycle entry {
        cost = here.fee();
        kind = "Car" if isinstance(here, Car) else ("Truck" if isinstance(here, Truck) else "Motorcycle");
        print(f"{here.plate} ({kind}) -> ${cost:.2f}");
        self.collected = self.collected + cost;
    }
}

with entry {
    g4 = Lane(lane_name="G-4");
    root ++> g4;

    g4 ++> Car(plate="CAR-01");
    g4 ++> Truck(plate="TRK-77", tons=8.0);
    g4 ++> Motorcycle(plate="MC-22");
    g4 ++> Truck(plate="TRK-12", tons=2.5);
    g4 ++> Car(plate="CAR-03", passes=2);

    cashier = Cashier();
    root spawn cashier;

    print(f"Total revenue at G-4: ${cashier.collected:.2f}");
}

