"""Cycle-safe social proof extraction over typed graph relationships."""

node GraphEntity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "";
    has incoming_edge_type: str = "";
}

node SocialProofStep {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_title: str = "";
    has edge_type: str = "";
    has verb: str = "";
    has target_title: str = "";
}

edge SocialLink {
    has edge_type: str = "";
}

walker SocialProofExtractor {
    has candidate_title: str = "";
    has anchor_title: str = "";
    has edge_verbs: dict[str, str] = {};
    has seen_titles: list[str] = [];
    has steps: list[SocialProofStep] = [];
    has description: str = "";
    has previous_title: str = "";
    has stopped_on_cycle: bool = False;
    has confidence: float = 0.85;

    def resolve_verb(edge_name: str) -> str {
        mapped = self.edge_verbs.get(edge_name);
        if mapped is None {
            return edge_name;
        }
        return mapped;
    }

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can extract with GraphEntity entry {
        print("Visited " + here.title);

        if here.title in self.seen_titles {
            self.description = self.description + " -> [...]";
            self.stopped_on_cycle = True;
            print("Cycle policy: truncated with [...]");
            disengage;
        }

        self.seen_titles.append(here.title);

        if self.anchor_title == "" {
            self.anchor_title = here.title;
        }

        if self.previous_title != "" {
            edge_name = here.incoming_edge_type;
            verb = self.resolve_verb(edge_name);
            step = SocialProofStep(
                source_title=self.previous_title,
                edge_type=edge_name,
                verb=verb,
                target_title=here.title
            );
            self.steps.append(step);

            phrase = self.previous_title + " " + verb + " " + here.title;
            if self.description == "" {
                self.description = phrase;
            } else {
                self.description = self.description + ", then " + phrase;
            }
        }

        if here.title == self.candidate_title {
            if len(self.steps) == 0 {
                self.description = "directly related";
            }

            print("Social proof: " + self.description);
            print("Anchor=" + self.anchor_title + ", Candidate=" + self.candidate_title);
            print("Steps=" + str(len(self.steps)) + ", Confidence=" + str(self.confidence));

            for step in self.steps {
                print(
                    step.source_title
                    + " --[" + step.edge_type + "/" + step.verb + "]--> "
                    + step.target_title
                );
            }

            disengage;
        }

        self.previous_title = here.title;
        visit [->:SocialLink:->] else { disengage; }
    }

    can finish with exit {
        print("Social proof report: " + self.description);
    }
}

with entry {
    verbs = {
        "follow": "follows",
        "like": "liked",
        "contains": "contains",
        "related_to": "is related to"
    };

    anchor = GraphEntity(title="User_A", kind="user");
    user_b = GraphEntity(
        title="User_B",
        kind="user",
        incoming_edge_type="follow"
    );
    tweet_y = GraphEntity(
        title="Tweet_Y",
        kind="tweet",
        incoming_edge_type="like"
    );
    topic = GraphEntity(
        title="#AI",
        kind="topic",
        incoming_edge_type="contains"
    );
    candidate = GraphEntity(
        title="Tweet_Z",
        kind="tweet",
        incoming_edge_type="contains"
    );

    root ++> anchor;
    anchor +>:SocialLink(edge_type="follow"):+> user_b;
    user_b +>:SocialLink(edge_type="like"):+> tweet_y;
    tweet_y +>:SocialLink(edge_type="contains"):+> topic;
    topic +>:SocialLink(edge_type="contains"):+> candidate;
    candidate +>:SocialLink(edge_type="related_to"):+> anchor;

    root spawn SocialProofExtractor(
        candidate_title="Tweet_Z",
        edge_verbs=verbs
    );

    root spawn SocialProofExtractor(
        candidate_title="Missing",
        edge_verbs=verbs
    );
}

