    has name: str = "";
}

node Attraction {
    has name: str = "";
    has stars: int = 0;
}

node Station {
    has name: str = "";
}

edge ConnectsTo {}

walker Planner {
    has itinerary: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can tour with Station entry {
        print(f"Station: {here.name}");
        visit [-->];
    }

    can collect with Hotel entry {
        # Hotels are intentionally ignored.
        visit [-->];
    }

