node Process {
    has pid: int = 0;
    has label: str = "";
    has running: bool = True;
    has exit_code: int = -1;
    has tombstone: object = None;
}

node Supervisor {
    has label: str = "";
}

node DeadTombstone {
    has exit_reason: str = "";
    has exit_code: int = -1;
}

edge Spawned { }
edge Exited { }

# Death-aware audit walker: walks the supervisor's spawned subtree,
# records every pid that is already dead (or has its exit consumed),
# and emits a verdict instead of parking forever.
walker AuditExit {
    has target_pid: int = 0;
    has dead_pids: list[int] = [];
    has reasons: list[str] = [];
    has verdict: str = "RUNNABLE";

    can begin with Root entry {
        visit [-->];
    }

    can audit_supervisor with Supervisor entry {
        all_dead = True;
        any_can_exit = False;
        for child in [-->] {
            if child.running and child.tombstone is None {
                any_can_exit = True;
                all_dead = False;
            } else {
                self.dead_pids.append(child.pid);
                tomb = child.tombstone;
                reason_text = tomb.exit_reason if tomb else "killed-no-tombstone";
                self.reasons.append(reason_text);
            }
        }
        verdict_label = "NOTHING_CAN_EXIT" if (len([-->]) > 0 and not any_can_exit) else "OK";
        self.verdict = verdict_label;
        print(f"[AuditExit] target_pid={self.target_pid} "
              f"verdict={self.verdict} dead_pids={self.dead_pids} "
              f"reasons={self.reasons}");
    }
}

with entry {
    # A supervisor that has spawned three processes; two are dead (one
    # with an exit tombstone, one with an exit consumed elsewhere),
    # one is still running. Under the bug, run_until_exit would park
    # forever awaiting the dead pair; the death-aware audit returns a
    # verdict immediately.
    sup = Supervisor(label="harness-finish_call");
    root ++> sup;

    p1 = Process(pid=101, label="worker-A", running=False, exit_code=137);
    p1.tombstone = DeadTombstone(exit_reason="SIGKILL-def-crash", exit_code=137);

    p2 = Process(pid=102, label="worker-B", running=False, exit_code=-1);
    p2.tombstone = DeadTombstone(exit_reason="undef-absent-stdlib", exit_code=-1);

    p3 = Process(pid=103, label="worker-C", running=True);

    sup +>:Spawned:+> p1;
    sup +>:Spawned:+> p2;
    sup +>:Spawned:+> p3;

    p1 +>:Exited:+> p1.tombstone;
    p2 +>:Exited:+> p2.tombstone;

    auditor = AuditExit(target_pid=999);
    root spawn auditor;
}

