# Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.
"""Extension install path-traversal defense model.

Demonstrates the core scenario from gemini-cli issue #29076: extension
names must be validated so that ``path.join(extensionsDir, name)``
cannot escape the extensions directory. The model uses a tree of
``Dir`` nodes connected by ``Contains`` edges, a ``File`` leaf, and an
``Extension`` request that proposes a target name. A walker traverses the
graph to verify the resolved location is still inside the root and rejects
any name that escapes via ``..`` segments or absolute prefixes.
"""

node Dir {
    has name: str = "";
    has depth: int = 0;
}

node File {
    has name: str = "";
}

node Extension {
    has title: str = "";
    has proposed_name: str = "";
    has is_safe: bool = True;
    has reject_reason: str = "";
}

edge Contains { }

walker PathAuditor {
    has segments: list[str] = [];
    has safe: bool = True;
    has reason: str = "";
    has verdict_printed: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit with Extension entry {
        self.safe = True;
        self.reason = "";
        self.verdict_printed = False;
        raw = here.proposed_name.replace("\\", "/");
        self.segments = raw.split("/");
        if self.segments == [] {
            self.segments = [""];
        }
        visit [-->] else {
            label = "ACCEPT" if self.safe else "REJECT";
            tail = f" ({self.reason})" if not self.safe else "";
            print(f"[{label}] '{here.title}' -> '{here.proposed_name}'" + tail);
            self.verdict_printed = True;
            disengage;
        }
    }

    can walk with Dir entry {
        if not self.safe {
            return;
        }
        if len(self.segments) == 0 {
            return;
        }
        head = self.segments[0];
        rest = self.segments[1:];
        self.segments = rest;
        if here.depth == 0 and head == "" {
            self.safe = False;
            self.reason = "absolute path rejected";
            return;
        }
        if head == ".." {
            if here.depth == 0 {
                self.safe = False;
                self.reason = "traversal escapes extensions root";
            } else {
                here.depth = here.depth - 1;
            }
            return;
        }
        if head != "" {
            here.depth = here.depth + 1;
        }
        visit [-->];
    }

    can land with File entry {
        return;
    }
}

with entry {
    extensions_dir = Dir(name="extensions", depth=0);
    tools_dir = Dir(name="tools", depth=1);
    linters_dir = Dir(name="linters", depth=2);
    cache_dir = Dir(name="cache", depth=0);

    root ++> extensions_dir;
    extensions_dir +>:Contains:+> tools_dir;
    tools_dir +>:Contains:+> linters_dir;
    root ++> cache_dir;

    good_ext = Extension(title="safe-ext", proposed_name="tools/linters");
    traversal_ext = Extension(title="evil-ext", proposed_name="../../etc/passwd");
    absolute_ext = Extension(title="abs-ext", proposed_name="/usr/local/bin");
    sibling_ext = Extension(title="sibling-ext", proposed_name="../cache/payload");
    plain_ext = Extension(title="plain-ext", proposed_name="plain-name");
    nested_ext = Extension(title="nested-ext", proposed_name="tools/nested/deep");

    root ++> good_ext;
    root ++> traversal_ext;
    root ++> absolute_ext;
    root ++> sibling_ext;
    root ++> plain_ext;
    root ++> nested_ext;

    PathAuditor() spawn root;
}

