# --- Entity archetypes ---------------------------------------------------

node BaselineCommit {
    has sha: str = "";
    has summary: str = "";
}

node Finding {
    has finding_id: str = "";
    has title: str = "";
    has category: str = "Backlog";
    has rationale: str = "";
}

node AcceptanceCommand {
    has label: str = "";
    has cmd: str = "";
    has passed: bool = True;
    has note: str = "";
}

node VisibleRuntime {
    has scenario: str = "";
    has executed: bool = False;
}

node Decision {
    has outcome: str = "PENDING";
    has reasoning: str = "";
}

# --- Typed edges ---------------------------------------------------------

edge Blocks {
    has severity: str = "exit";
}

edge MitigatedBy {
    has boundary: str = "";
}

edge ClassifiedAs {
    has bucket: str = "";
}

edge Exercises {
    has step: str = "";
}

edge RunsCommand {
    has order_index: int = 0;
}

# --- Reviewer walker -----------------------------------------------------

walker Reviewer {
    # Cycle policy: guard set of visited node identities plus a depth cap.
    has visited: list = [];
    has depth_remaining: int = 16;
    has seen_findings: list = [];
    has commands_passed: bool = True;
    has runtime_executed: bool = False;

