        self.depth_remaining = self.depth_remaining - 1;
        if self.depth_remaining <= 0 {
            disengage;
        }
        visit [-->] else { disengage; };
    }

    can review_finding with Finding entry {
        if self._seen(here.finding_id) {
            visit [-->] else { disengage; };
        }
        self._mark(here.finding_id);
        self.seen_findings.append(here.finding_id);
        print(f"[FINDING] {here.finding_id} {here.title} -> {here.category}");
        if here.category == "Exit blocker" {
            print(f"          rationale: {here.rationale}");
        }
        self.depth_remaining = self.depth_remaining - 1;
        if self.depth_remaining <= 0 {
            disengage;
        }
        visit [-->] else { disengage; };
    }

    can review_command with AcceptanceCommand entry {
        key = here.label;
        if self._seen(key) {
            visit [-->] else { disengage; };
        }
        self._mark(key);
        verdict = "PASS" if here.passed else "FAIL";
        print(f"[CMD {verdict}] {here.label}: {here.cmd}");
        if not here.passed {
            print(f"          note: {here.note}");
            self.commands_passed = False;
        }
        self.depth_remaining = self.depth_remaining - 1;
        if self.depth_remaining <= 0 {
            disengage;
        }
        visit [-->] else { disengage; };
    }

    can review_runtime with VisibleRuntime entry {
        key = "runtime:" + here.scenario;
        if self._seen(key) {
            visit [-->] else { disengage; };
        }
        self._mark(key);
        verdict = "RUN" if here.executed else "SKIP";
        print(f"[RUNTIME {verdict}] {here.scenario}");
        if here.executed {
            self.runtime_executed = True;
        }
        self.depth_remaining = self.depth_remaining - 1;
        if self.depth_remaining <= 0 {
            disengage;
        }
        visit [-->] else { disengage; };
    }

    can record_decision with Decision entry {
        key = "decision:" + here.outcome + ":" + here.reasoning;
        if self._seen(key) {
            disengage;
        }
        self._mark(key);

        # Confirm the five bounded-critical-path findings were all classified.
        needed = ["#5", "#8", "#53", "#54", "#55"];
        covered = 0;
        for fid in self.seen_findings {
            for n in needed {
