        title="Visible runtime evidence",
        category="Accepted risk",
        rationale="Clean-current visible runtime evidence gathered and recorded."
    );
    f8 = Finding(
        finding_id="#8",
        title="Disappearing-road behavior",
        category="Accepted risk",
        rationale="Reproduced on frozen baseline; contained with operating boundary."
    );
    f53 = Finding(
        finding_id="#53",
        title="Installation exposure in required workflow",
        category="Exit blocker",
        rationale="Immediate installation exposure required containment before acceptance."
    );
    f54 = Finding(
        finding_id="#54",
        title="Audit trustworthiness concern A",
        category="Backlog",
        rationale="Does not prevent a trustworthy acceptance pass."
    );
    f55 = Finding(
        finding_id="#55",
        title="Audit trustworthiness concern B",
        category="Backlog",
        rationale="Does not prevent a trustworthy acceptance pass."
    );

    # Acceptance commands — both PASS in this bounded pass.
    cmd_build = AcceptanceCommand(
        label="build-compat",
        cmd="npm run build-compat",
        passed=True,
        note="Built against frozen baseline."
    );
    cmd_test = AcceptanceCommand(
        label="test-compat",
        cmd="npm run test-compat",
        passed=True,
        note="Compat suite green on frozen baseline."
    );

    runtime = VisibleRuntime(
        scenario="new city -> planning project -> road -> implementation -> save -> reload",
