# One anchor zone at depth 0, three depth-1 children of which one is an
# unambiguous inboard zone, one is an unambiguous inboard zone, and one
# straddles the meridian so it is a SubZone of TWO parents under coverage
# but OwnedSubZone of exactly ONE parent under ownership.

with entry {
    anchor_a = Zone(zone_id="A0", depth=0, lat=0.0, lon=-0.30);
    anchor_b = Zone(zone_id="A1", depth=0, lat=0.0, lon=0.30);

    child_inboard_left = Zone(
        zone_id="C-L", depth=1, lat=0.01, lon=-0.20
    );
    child_inboard_right = Zone(
        zone_id="C-R", depth=1, lat=0.01, lon=0.20
    );
    child_straddler = Zone(
        zone_id="C-S", depth=1, lat=0.01, lon=-0.02
    );

    # Build the hierarchy off root.
    root ++> anchor_a ++> anchor_b;

    # Coverage: each child intersects both anchors (interior-intersection
    # in a small band). The straddler is a sub-zone of BOTH anchors under
    # coverage, which is the double-counting pathology the issue names.
    anchor_a +>:SubZone(intersect_area=0.8):+> child_inboard_left;
    anchor_b +>:SubZone(intersect_area=0.8):+> child_inboard_left;
    anchor_a +>:SubZone(intersect_area=0.8):+> child_inboard_right;
    anchor_b +>:SubZone(intersect_area=0.8):+> child_inboard_right;
    anchor_a +>:SubZone(intersect_area=0.6):+> child_straddler;
    anchor_b +>:SubZone(intersect_area=0.6):+> child_straddler;

    # Lineage: id-truncation ancestry. Transitive by construction. Here
    # both anchors are treated as lineage ancestors of all three children
    # for the demo; in a real DGGRS this is a function of the id.
    anchor_a +>:LineageOf:+> child_inboard_left;
    anchor_b +>:LineageOf:+> child_inboard_left;
    anchor_a +>:LineageOf:+> child_inboard_right;
    anchor_b +>:LineageOf:+> child_inboard_right;
    anchor_a +>:LineageOf:+> child_straddler;
    anchor_b +>:LineageOf:+> child_straddler;

    # Ownership: unique assignment. The straddler is owned by exactly
    # ONE anchor under the documented convention (centre-in-parent-
    # halfplane). Inboard children have unambiguous ownership.
    anchor_a +>:OwnedSubZone:+> child_inboard_left;
    anchor_b +>:OwnedSubZone:+> child_inboard_right;
    anchor_a +>:OwnedSubZone:+> child_straddler;

    auditor = HierarchyAuditor(audit_depth=1);
    root spawn auditor;

    print("--- roll-up ---");
    print(
        f"coverage  total={auditor.coverage_total} "
        f"straddlers={auditor.coverage_straddlers}"
    );
    print(
        f"lineage   total={auditor.lineage_total}"
    );
    print(
        f"ownership total={auditor.ownership_total} "
        f"straddlers={auditor.ownership_straddlers}"
    );
    print(
        "note: coverage double-counts the straddler (3+3 instead of 3); "
        "ownership is exact and the straddler belongs to exactly one parent."
    );
}

