    root ++> j04;
    root ++> j13;
    root ++> jhub;
    j09 +>:owns:+> c_tow;
    j04 +>:owns:+> c_fox;
    j13 +>:owns:+> c_auct;
    jhub +>:owns:+> c_read;
    j09 +>:depends:+> j13;
    j09 +>:depends:+> j04;
    j13 +>:depends:+> jhub;
    j04 +>:depends:+> jhub;
    gs.by_id["JOB-09"] = j09;
