        if kids {
            visit kids;
        } else {
            disengage;
        }
    }
}

def build_nodes(graph_adj: list[list[int]]) -> list[GNode] {
    nodes: list[GNode] = [];
    n = len(graph_adj);
    for i in range(n) {
        nd = GNode(nid=i);
        nodes.append(nd);
    }
    for i in range(n) {
        u = nodes[i];
        row = graph_adj[i];
        for j in range(len(row)) {
            v = int(row[j]);
            if v >= 0 and v < n {
                u +>:GEdge:+> nodes[v];
            }
        }
    }
    return nodes;
}

def shortest_cycle_containing_target(graph: list[list[int]], target: int) -> int {
    n = len(graph);
    if n == 0 {
        return -1;
    }
    if target < 0 or target >= n {
        return -1;
    }
    nodes = build_nodes(graph);
    start = nodes[target];
    start.dist = 0;
    claimed: dict[str, bool] = {};
    w = start spawn DistBfs(start_nid=target, claimed=claimed);

    best: int = -1;
    for u_idx in range(n) {
        u = nodes[u_idx];
        d = u.dist;
