"""Task dependency graph with memoization-style short-circuit traversal.

Models the pyinvoke/invoke #461 "advanced task dependencies / caching" use case:
a tree of tasks (some heavy, some cheap) connected by typed `Requires` edges.
A walker descends the dependency graph, but each task remembers whether its
result has already been "produced" — re-entering an already-completed task
short-circuits instead of re-running its body. This is the make-like behavior
the issue asks for: tasks declare what they need, run only as many times as
required, and skip work that has already been done.
"""

node Task {
    has title: str = "";
    has heavy: bool = False;
    has done: bool = False;
    has runs: int = 0;
}

edge Requires {
    has via: str = "pre";
}

walker Executor {
    can start with Root entry {
        visit [->:Requires:->];
    }

    can run_task with Task entry {
        if here.done {
            print(f"  [skip ] {here.title} (already done, runs={here.runs})");
            visit [->:Requires:->];
            return;
        }
        if here.heavy {
            print(f"  [heavy] {here.title} -- doing real work");
            here.runs = here.runs + 1;
        } else {
            print(f"  [light] {here.title} -- quick step");
            here.runs = here.runs + 1;
        }
        here.done = True;
        visit [->:Requires:->];
    }
}

