    can audit_run with Manifest entry {
        print(f"Resuming run {here.run_id}: re-verifying every completed stage");
        visit [->:StageLink:->];
    }

    can verify_stage with Stage entry {
        mismatch = here.input_hash != here.recorded_hash;
        stale = not here.outputs_intact;
        if mismatch or stale {
            print(f"  [CORRUPT] {here.name} -- input_hash={here.input_hash}, "
                  f"recorded_hash={here.recorded_hash}, intact={here.outputs_intact}");
            self.invalidations.append(here.name);
        } else {
            print(f"  [OK]      {here.name}");
        }
        visit [->:StageLink:->];
    }

    can cascade_invalidate with Stage entry {
        if self.invalidations and here.name not in self.invalidations {
            print(f"  [CASCADE] {here.name} -- downstream of invalidated "
                  f"{self.invalidations[0]}, rerun or abort");
            self.invalidations.append(here.name);
            visit [->:StageLink:->];
        } else {
            visit [->:StageLink:->] else { disengage; }
        }
    }

    def final_report -> str {
        if not self.invalidations {
            return "All stages verified -- resume may proceed.";
        }
        invalid_list = ", ".join(self.invalidations);
        return f"INTEGRITY ERROR: invalidated stages [{invalid_list}] -- rerun or abort.";
    }
