        input_hash="h_eval_in",
        recorded_hash="h_eval_in",
        outputs_intact=True
    );

    root +>:StageLink:+> features +>:StageLink:+> train +>:StageLink:+> eval_stage;

    auditor = IntegrityAudit();
    root spawn auditor;
    print(auditor.final_report());
}

