    alice = House(name="Alice", residents=3);
    bob = House(name="Bob", residents=2);
    carol = House(name="Carol", residents=4);
    dave = House(name="Dave", residents=1);

    # Wire every pair as buddies in one statement each (bidirectional).
    alice +>:Buddy(since="2020"):+> bob;
    bob +>:Buddy(since="2020"):+> alice;
    alice +>:Buddy(since="2020"):+> carol;
    carol +>:Buddy(since="2020"):+> alice;
    bob +>:Buddy(since="2021"):+> carol;
    carol +>:Buddy(since="2021"):+> bob;
    bob +>:Buddy(since="2021"):+> dave;
    dave +>:Buddy(since="2021"):+> bob;
    carol +>:Buddy(since="2022"):+> dave;
    dave +>:Buddy(since="2022"):+> carol;

    root ++> alice;
    root ++> bob;
    root ++> carol;
    root ++> dave;

    g_alice = Greeter(target="Dave");
    alice spawn g_alice;

    g_dave = Greeter(target="Alice");
    dave spawn g_dave;

    print(f"Alice's greeter visited: {g_alice.greeted}");
