# Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.
"""Activity feed as a graph: User and Post nodes with FOLLOWS/AUTHORED edges,
exercised by walkers that perform shortest-path, 2-hop recommendations, and
common-neighbor queries natively on typed edges."""

node User {
    has username: str = "";
    has joined: str = "";
}

node Post {
    has title: str = "";
    has body: str = "";
}

edge Follows {
    has since: str = "";
}

edge Authored {
    has at: str = "";
}

walker ShortestChain {
    has source_name: str = "";
    has target_name: str = "";
    has hops: int = 0;
    has path: list[str] = [];
    has visited: list[str] = [];
    has done: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can walk with User entry {
        if self.done {
            disengage;
        }
        already = False;
        for v in self.visited {
            if v == here.username {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.visited = self.visited + [here.username];
        if here.username == self.target_name {
            self.done = True;
            disengage;
        }
        self.path = self.path + [here.username];
        self.hops = self.hops + 1;
        visit [->:Follows:->] else { disengage; }
    }
}

walker RecommendFriends {
    has seed_name: str = "";
    has seen: list[str] = [];
    has picks: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can seed with User entry {
        if here.username != self.seed_name {
            visit [-->];
        }
        self.seen = self.seen + [here.username];
        visit [->:Follows:->];
    }

    can hop with User entry {
        already = False;
        for v in self.seen {
            if v == here.username {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.seen = self.seen + [here.username];
        visit [->:Follows:->];
    }

    can candidate with User entry {
        if (here.username != self.seed_name) {
            dup = False;
            for p in self.picks {
                if p == here.username {
                    dup = True;
                }
            }
            if not dup {
                self.picks = self.picks + [here.username];
            }
        }
    }
}

walker CommonNeighbors {
    has a_name: str = "";
    has b_name: str = "";
    has common: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can first with User entry {
        if here.username != self.a_name {
            visit [-->];
        }
        visit [->:Follows:->];
    }

    can second with User entry {
        if here.username != self.b_name {
            visit [-->];
        }
        visit [->:Follows:->];
    }

    can collect with User entry {
        if (here.username != self.a_name) and (here.username != self.b_name) {
            self.common = self.common + [here.username];
        }
    }
}

walker CascadePurge {
    has owner: str = "";
    has removed_posts: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can pick with User entry {
        if here.username != self.owner {
            visit [-->];
        }
        visit [->:Authored:->];
    }

    can collect_post with Post entry {
        self.removed_posts = self.removed_posts + [here.title];
        del here;
    }
}

with entry {
    alice = User(username="alice", joined="2021-03-01");
    bob = User(username="bob", joined="2021-05-12");
    carol = User(username="carol", joined="2022-01-04");
    dave = User(username="dave", joined="2022-07-19");
    eve = User(username="eve", joined="2023-02-22");

    p1 = Post(title="Hello graph", body="first post");
    p2 = Post(title="Cypher musings", body="patterns");
    p3 = Post(title="Edge cases", body="more");

    root ++> alice ++> bob ++> carol ++> dave ++> eve;

    alice +>:Follows(since="2022"):+> bob;
    alice +>:Follows(since="2022"):+> carol;
    bob   +>:Follows(since="2023"):+> dave;
    carol +>:Follows(since="2023"):+> dave;
    dave  +>:Follows(since="2024"):+> eve;

    alice +>:Authored(at="2023-06-01"):+> p1;
    bob   +>:Authored(at="2023-06-09"):+> p2;
    alice +>:Authored(at="2023-07-02"):+> p3;

    print("=== shortest follow chain alice -> eve ===");
    chain = ShortestChain(source_name="alice", target_name="eve", path=["alice"]);
    root spawn chain;
    print(f"hops={chain.hops} path={chain.path}");

    print("=== 2-hop recommendations for alice ===");
    rec = RecommendFriends(seed_name="alice");
    root spawn rec;
    print(f"recommendations={rec.picks}");

    print("=== common neighbors between bob and carol ===");
    cn = CommonNeighbors(a_name="bob", b_name="carol");
    root spawn cn;
    print(f"common={cn.common}");

    print("=== cascade purge alice's posts ===");
    purge = CascadePurge(owner="alice");
    root spawn purge;
    print(f"removed={purge.removed_posts}");
}

