    has title: str = "";
    has decision_text: str = "";
}

node Prose {
    has title: str = "";
    has body: str = "";
    has kind: str = "readme";
}

walker TruthGate {
    has failures: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can check_manifest with Manifest entry {
        print(f"[manifest] {here.title}: {here.decision_text}");
        if "bound" in here.decision_text or "certified" in here.decision_text {
