    has service_name: str = "";
    has error_to_throw: str = "";

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can hit with Service entry {
        target_name = here.name;
        if self.service_name != "" and self.service_name != target_name {
            visit [->:DependsOn:->];
            return;
        }

        if self.error_to_throw == "" {
            print(f"  ok    : {target_name}");
            visit [->:DependsOn:->];
            return;
        }

        # BUG SHAPE: the original middleware catches EVERY error and
        # records it as a service-health failure. Here we surface that
        # decision so a maintainer can wire the fix.
        if self.error_to_throw == "validation" {
            print(f"  skip  : {target_name} got validation error "
                  f"(not a service-health concern)");
        } elif self.error_to_throw == "auth" {
            print(f"  skip  : {target_name} got authorization error "
                  f"(not a service-health concern)");
        } elif self.error_to_throw == "timeout" {
            err = HealthCheckError(kind="timeout");
            here.failure_count += 1;
            here.last_error_kind = err.kind;
            print(f"  FAIL  : {target_name} timed out -> counted "
                  f"({here.failure_count})");
        } elif self.error_to_throw == "checkFailed" {
            err = HealthCheckError(kind="checkFailed",
