node Module {
    has name: str = "";
    has path: str = "";
    has lazy_imports: int = 0;
}

edge DependsOn {
    has call_sites: int = 0;
    has lazy: bool = False;
}

edge Inverts {
    has kind: str = "";
}

edge Provides {
    has symbols: str = "";
}

