    agents = Module(name="agents", path="scripts/lib/agents.py", lazy_imports=5);
    viz = Module(name="viz", path="scripts/lib/viz.py", lazy_imports=0);

    templating = Module(name="templating", path="scripts/lib/templating.py");
    viz_hooks = Module(name="viz_hooks", path="scripts/lib/viz_hooks.py");

    config +>:DependsOn(call_sites=2, lazy=True):+> agents;
    agents +>:DependsOn(call_sites=4, lazy=True):+> config;

    agents +>:DependsOn(call_sites=3, lazy=True):+> viz;
    viz +>:DependsOn(call_sites=1, lazy=False):+> agents;

