    can inspect_workspace with Workspace entry {
        self.steps += 1;
        if self.steps > self.max_steps {
            print("Traversal stopped at the safety depth limit");
            disengage;
        } else {
            if here.kill_switch {
                self.raw_allowed = False;
                self.cdp_allowed = False;
                print("Kill switch active: expert capabilities denied");
            } else {
                self.raw_allowed = here.raw_playwright_enabled;
                self.cdp_allowed = here.raw_cdp_enabled;
                print(f"Workspace scope: {here.scope_tier}");
            }
            visit [->:Owns:->] else {
                disengage;
            }
        }
    }

    can inspect_session with BrowserSession entry {
        self.steps += 1;
        if self.raw_allowed {
            print(f"Raw Playwright allowed for session {here.session_id}");
        } else {
            print(f"Raw Playwright denied for session {here.session_id}");
        }
        if self.cdp_allowed {
            if here.browser_name == "chromium" {
