# Help me build a vet-clinic round in Jac. Pets are nodes with a name, species, and whether they need a vaccine today. A vet walker should keep its own list of patient names and count of shots given as it moves from pet to pet; afterwards I want to read those numbers straight off the spawned walker instance and print a summary.
"""Vet clinic round: pets as nodes, vet walker tallies shots while traversing."""

node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = False;
}

walker Vet {
    has patient_log: list[str] = [];
    has shots_given: int = 0;

    can start with Root entry {
        print(f"Vet beginning rounds");
        visit [-->] else { disengage; }
    }

    can examine with Pet entry {
        self.patient_log.append(here.name);
        if here.needs_vaccine {
            self.shots_given += 1;
            print(f"[SHOT] {here.name} the {here.species} got a vaccine");
        } else {
            print(f"[SKIP] {here.name} the {here.species} is up to date");
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True)
        ++> Pet(name="Biscuit", species="dog")
        ++> Pet(name="Pancake", species="rabbit", needs_vaccine=True)
        ++> Pet(name="Pepper", species="cat", needs_vaccine=True);

    vet = Vet();
    root spawn vet;

    print(f"\n--- Round summary ---");
    print(f"Patients seen ({len(vet.patient_log)}): {vet.patient_log}");
    print(f"Shots given: {vet.shots_given}");
}

