    can check_supply with AnatStage entry {
        label = self.current_label;
        # Reuse decisions mirror con/mechababs issue #107:
        # ribbon + fsaverage sphere are deterministic format conversions
        # from FreeSurfer, so reuse is safe; desc-preproc_T2w is not
