        ribbon_ready = here.ribbon_ready;
        t2w_ready = here.t2w_preproc_ready;
        sphere_ready = here.sphere_ready;
        status = (
            f"{label}: upstream smriprep {here.smriprep_version} -> "
            f"ribbon={ribbon_ready}, t2w={t2w_ready}, sphere={sphere_ready}"
        );
        self.findings.append(status);
        visit [-->] else { disengage; }
    }
