    has target: str = "";
    has served_dir: str = "";

    can start with Root entry {
        print(f"[up] target={self.target}");
        visit [-->];
    }

    can pick_target with Frontend entry {
        if here.name == self.target {
            self.served_dir = here.path;
            if self.served_dir == "" {
                print(f"[up] BUG: {here.name} has no path; npm would run in project root");
            } else {
                print(f"[up] serving {here.name} from {self.served_dir}");
