        visit [-->];
    }
}

walker BuildLane {
    can start with Root entry {
        print("[build] resolving cross-repo frontend sources...");
        visit [-->];
    }

    can announce with Frontend entry {
        if here.kind == "git" {
            print(f"[build]   {here.repo}@{here.ref}//{here.subdir} -> {here.path}");
        }
        visit [-->];
    }
}

