            self.cycle_found = True;
            cycle = self.on_path + [here.name];
            print(f"ERROR: typealias cycle detected: {' -> '.join(cycle)}");
            disengage;
        }
        self.on_path = self.on_path + [here.name];

        # Nominal aliases terminate at their named boundary; structural
        # aliases must still be expanded one more level.
        if here.kind == "nominal" {
            print(f"OK: nominal alias '{here.name}' resolves at named boundary");
            self.on_path = self.on_path[:-1];
            disengage;
        }
        visit [->:Expands:->];
    }

    # A TypeRef we arrive at via Expands: record it, then descend.
    can resolve_ref with TypeRef entry {
        if here.name in self.on_path {
            self.cycle_found = True;
            cycle = self.on_path + [here.name];
            print(f"ERROR: typealias cycle detected: {' -> '.join(cycle)}");
            disengage;
        }
        print(f"  expanding into {here.name}");
        visit [->:Expands:->];
    }
}

