    # Case 1: structural self-reference
    #   typealias Tree = { l: Tree, r: Tree }
    # The original checker recursed Tree -> Tree -> Tree ... and overflowed.
    tree_self = AliasDecl(name="Tree", kind="structural");
    tree_self_ref = TypeRef(name="Tree");
    root +>:Aliases:+> tree_self +>:Expands:+> tree_self_ref +>:Expands:+> tree_self_ref;

