    root +>:Aliases:+> b_decl +>:Expands:+> b_ref;
    a_decl +>:Expands:+> b_ref;

    # Case 3: a nominal recursive type — must still check and build.
    #   type Tree = { l: Tree, r: Tree }   (nominal; recursion terminates on the name)
    nom_decl = AliasDecl(name="Tree", kind="nominal");
    nom_ref = TypeRef(name="Tree");
    root +>:Aliases:+> nom_decl +>:Expands:+> nom_ref +>:Expands:+> nom_ref;

    print("=== Checking structural self-referencing typealias ===");
    c1 = AliasChecker();
    root spawn c1;

    print("=== Checking mutual two-step typealias cycle ===");
    c2 = AliasChecker();
    root spawn c2;

    print("=== Checking nominal recursive type (should be OK) ===");
    c3 = AliasChecker();
    root spawn c3;
}

