cached task records after a restart. We model both the *registered graph*
(what the maintainer defined) and the *cached runtime state* (what was last
persisted), then a walker walks the registered graph, comparing versions and
marking stale tasks invalid.
"""

node Task {
    has name: str = "";
    has version: int = 0;
    has last_seen_version: int = 0;
    has stale: bool = False;
    has cache_hit: bool = False;
}

# Typed edges carry the dependency relationship. `since_version` records
# which version of the task graph introduced this edge; if the registered
# graph changes, edges added in newer versions invalidate older cached
# state for the upstream task.
edge DependsOn {
    has since_version: int = 0;
}

# A separate "Pipeline" node groups a versioned task graph definition.
node Pipeline {
    has label: str = "";
    has graph_version: int = 0;
}

# A walker that walks upstream dependencies from a starting task, detects
# cycles, marks cache misses as stale, and reports the dependency frontier.
walker DependencyAuditor {
    has visited: list[str] = [];
    has stale_tasks: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit_pipeline with Pipeline entry {
        print(f"Auditing pipeline '{here.label}' at graph version v{here.graph_version}");
        visit [->:DependsOn:->];
    }

    can audit_task with Task entry {
        # Cycle guard: walkers have no built-in visited-set in 0.36.1,
        # so we maintain one explicitly on the walker.
        if here.name in self.visited {
            self.cycle_detected = True;
            print(f"[CYCLE] revisited {here.name}");
            disengage;
        }
        self.visited.append(here.name);

        # Stale if the cached record's last_seen_version doesn't match
        # the current definition version of this task.
        if here.cache_hit and here.last_seen_version != here.version {
            here.stale = True;
            self.stale_tasks.append(here.name);
            status = "STALE";
        } else {
            status = "FRESH";
        }
        print(f"[{status}] task {here.name} v{here.version} (cached v{here.last_seen_version})");
        visit [->:DependsOn:->];
    }
}

# A walker that simulates the invalidation cascade: when a task's version
# changes, every downstream dependent becomes stale transitively.
walker InvalidationCascade {
    has pending: list = [];

    can start with Root entry {
        visit [-->];
    }

    can seed_pipeline with Pipeline entry {
        print(f"Cascade from pipeline '{here.label}'");
        visit [->:DependsOn:->];
    }

    can cascade with Task entry {
        # If THIS task is stale and a downstream task cached against an
        # older version of us, propagate the staleness.
        if here.stale {
            print(f"  invalidating downstream of stale {here.name}");
            visit [->:DependsOn:->];
        } else {
            visit [->:DependsOn:->];
        }
    }
}

