"""Orchard irrigation tour: one shared routine logs pumps and sprinklers, resets idle hours, and reports totals."""

node Device {
    has label: str = "";
    has kind: str = "";
    has idle_hours: int = 0;
    has serviced: bool = False;
}

node Pump(Device) {
    has pressure_psi: float = 0.0;
}

node Sprinkler(Device) {
    has radius_ft: float = 0.0;
}

walker Crew {
    has total_serviced: int = 0;

    can start with Root entry {
        print("Crew starting irrigation tour...");
        visit [-->];
    }

    can tour with Pump | Sprinkler entry {
        prev = here.idle_hours;
        if here.serviced {
            new_label = "skip";
        } else {
            here.serviced = True;
            here.idle_hours = 0;
            self.total_serviced += 1;
            new_label = "serviced";
        }
        action = new_label;
        print(f"[{here.kind}] {here.label} idle_hours={prev} -> {action}");
        visit [-->];
    }
}

with entry {
    pump_a = Pump(label="Pump-A", kind="pump", idle_hours=12, pressure_psi=45.0);
    pump_b = Pump(label="Pump-B", kind="pump", idle_hours=3, pressure_psi=50.0);
    sprinkler_a = Sprinkler(label="Sprinkler-A", kind="sprinkler", idle_hours=8, radius_ft=15.0);
    sprinkler_b = Sprinkler(label="Sprinkler-B", kind="sprinkler", idle_hours=20, radius_ft=20.0);
    pump_b.serviced = True;

    root ++> pump_a ++> pump_b ++> sprinkler_a ++> sprinkler_b;

    crew = Crew();
    root spawn crew;
    print(f"Total devices serviced: {crew.total_serviced}");
}

