# A maintainer on the project raydocs/Aureo (unknown) filed this issue about hand-rolled graph machinery causing pain:
# 
# Issue #26: Expose Board API, CLI, and minimal inspectable UI
# 
# ## Outcome
# 
# 让人和 Agent 读取同一 Board truth，并可追踪下一项工作和证据。
# 
# ## Context
# 
# 当前 Web/PWA 是 thread control UI，不包含 Board projection。
# 
# ## Scope
# 
# * POST/GET board and projection/events APIs
# * ago board create/show/watch CLI
# * Web 显示 objective、task states、dependencies、agent、attempt、context/evidence、retry 与 next runnable
# * attempt 链接到现有 thread view
# * refresh/reconnect projection consistency
# 
# ## Out of scope
# 
# * drag-and-drop workflow editor
# * 复杂 graph canvas
# * 手动 Agent picker
# 
# ## Acceptance criteria
# 
# * create 立即返回 durable board ID
# * sequence reconnect 恢复相同状态
# * UI 不允许绕过 acceptance authority
# 
# ## Verification
# 
# * go test daemon/cmd packages
# * web bun test/typecheck/build
# 
# ## Expected deliverables
# 
# * Board API/CLI
# * minimal board projection/UI
# * contract tests
# 
# Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.
"""Board projection walker: model objectives, tasks, agents, and attempts.

The hand-rolled source maintains a Board with parent/child task IDs, agent
assignment lookups, and walkable dependency graphs for "next runnable" and
"reconnect" semantics. This demo lifts that machinery into native Jac:

  * Objective, Task, Agent, Attempt are node archetypes with typed fields.
  * Decomposes, DependsOn, AssignedTo, Produces are typed edges.
  * BoardInspector is a walker that traverses the graph, accumulates
    per-objective state, detects dependency cycles, and emits one final
    report (the single exit-point idiom).
  * Walker carries an explicit guard set so cycle-prone edges (DependsOn)
    cannot loop forever, mirroring the source's cycle safety.
"""

node Objective {
    has title: str = "";
    has goal: str = "";
}

node Task {
    has title: str = "";
    has state: str = "pending";
    has context: str = "";
    has evidence: str = "";
    has attempt_count: int = 0;
}

node Agent {
    has name: str = "";
    has role: str = "";
}

node Attempt {
    has note: str = "";
    has outcome: str = "unknown";
}

edge Decomposes {}
edge DependsOn {}
edge AssignedTo {}
edge Produces {}

walker BoardInspector {
    has objective_count: int = 0;
    has task_count: int = 0;
    has ready_count: int = 0;
    has cycle_found: bool = False;
    has visited_tasks: list = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_objective with Objective entry {
        self.objective_count += 1;
        print(f"[OBJECTIVE] {here.title}: {here.goal}");
        visit [->:Decomposes:->];
    }

    can audit_task with Task entry {
        if here in self.visited_tasks {
            return;
        }
        self.visited_tasks.append(here);
        self.task_count += 1;
        is_runnable = here.state == "ready" or here.state == "pending";
        blocked = False;
        for pred in [->:DependsOn:->] {
            if pred.state != "done" {
                blocked = True;
                break;
            }
        }
        if is_runnable and not blocked {
            self.ready_count += 1;
            print(f"  [RUNNABLE] {here.title} (state={here.state}, "
                  f"attempts={here.attempt_count})");
        } else {
            print(f"  [BLOCKED]  {here.title} (state={here.state})");
        }
        if here.context != "" {
            print(f"    context : {here.context}");
        }
        if here.evidence != "" {
            print(f"    evidence: {here.evidence}");
        }
        visit [->:Produces:->];
        visit [->:Decomposes:->];
    }

    can audit_attempt with Attempt entry {
        label = "OK " if here.outcome == "success" else "BAD";
        print(f"    [ATTEMPT {label}] {here.note}");
        visit [-->];
    }

    can detect_cycle with Task entry {
        for nxt in [->:DependsOn:->] {
            if nxt in self.visited_tasks {
                self.cycle_found = True;
                print(f"  [CYCLE] dependency loop detected via {here.title}");
                break;
            }
        }
        visit [->:DependsOn:->];
    }

    can finish with Root entry {
        print("");
        print(f"inspected {self.objective_count} objectives, "
              f"{self.task_count} tasks, "
              f"{self.ready_count} runnable, "
              f"cycle={self.cycle_found}");
    }
}

with entry {
    obja = Objective(title="Ship Board projection",
                     goal="Let humans and agents read the same board truth");
    t_setup = Task(title="Add board create/show CLI",
                   state="done",
                   context="ago board create --title=...",
                   evidence="commit a1");
    t_api = Task(title="Expose POST/GET board API",
                 state="done",
                 evidence="commit a2");
    t_ui = Task(title="Render objective + task projection",
                state="ready",
                context="bun web typecheck + build",
                attempt_count=1);
    t_reconnect = Task(title="Sequence reconnect state recovery",
                       state="pending",
                       context="must restore same board ID");
    agent = Agent(name="aurora", role="implementer");
    attempt_ok = Attempt(note="first attempt succeeded", outcome="success");
    attempt_fail = Attempt(note="web build failed", outcome="failure");

    root +>:Decomposes:+> obja;
    obja +>:Decomposes:+> t_setup;
    obja +>:Decomposes:+> t_api;
    obja +>:Decomposes:+> t_ui;
    obja +>:Decomposes:+> t_reconnect;

    t_ui +>:DependsOn:+> t_api;
    t_reconnect +>:DependsOn:+> t_ui;

    t_setup +>:AssignedTo:+> agent;
    t_ui +>:Produces:+> attempt_fail;
    t_setup +>:Produces:+> attempt_ok;

    root spawn BoardInspector();
}

# Jac lang
# from: osp_A_02__composer_v20
# I'm marking out a hiking trail in Jac as a chain of plain waypoints between the trailhead and the summit — the waypoints themselves don't need to hold any data at all. Give me a hiker walker that travels the trail and counts how many waypoints it passes, printing each stop number along the way and a completion line once it has passed enough of them.
"""Hiking trail: chain waypoints from trailhead to summit and walk them with a hiker."""

node Trailhead {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Waypoint {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Summit {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

walker Hiker {
    has stop_number: int = 0;
    has waypoints_passed: int = 0;
    has target_waypoints: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can begin with Trailhead entry {
        self.stop_number += 1;
        print(f"Stop {self.stop_number}: trailhead");
        visit [-->];
    }

    can cross with Waypoint entry {
        self.stop_number += 1;
        self.waypoints_passed += 1;
        print(f"Stop {self.stop_number}: waypoint {self.waypoints_passed}");
        visit [-->];
    }

    can finish with Summit entry {
        self.stop_number += 1;
        print(f"Stop {self.stop_number}: summit");
        visit [-->] else {
            print(
                f"Trail complete — passed {self.waypoints_passed} of "
                f"{self.target_waypoints} waypoints in {self.stop_number} stops."
            );
            disengage;
        };
    }
}

with entry {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();
    root spawn Hiker(target_waypoints=3);
}

