# We run several depots that each serve a set of stores. Instead of checking depots one by one, anchor one combined query from the whole list of depot nodes at once, find every store within reach, and flag the ones whose stock has dropped below 20 units.
"""Multi-depot stock sweep: anchor one query at the root over every depot,
walk into the stores each depot serves, and flag low-stock items."""

node Store {
    has title: str = "";
    has stock: int = 0;
    has available: bool = True;

    def is_low() -> bool {
        return self.stock < 20;
    }
}

node Depot {
    has name: str = "";
}

edge Serves {
    has route_id: str = "";
}

walker StockAuditor {
    has total_low: int = 0;

    can start with Root entry {
        print("Anchoring depot audit from root...");
        visit [-->];
    }

    can audit with Depot entry {
        print(f"-- {here.name} --");
        for store in [here->:Serves:->] {
            if store.is_low() {
                label = "LOW" if store.available else "GONE";
                print(f"[{label}] {store.title} at {here.name} ({store.stock} units)");
                self.total_low = self.total_low + 1;
            }
        }
        visit [-->];
    }
}

with entry {
    north = Depot(name="North Depot");
    south = Depot(name="South Depot");
    east = Depot(name="East Depot");
    root ++> north ++> south ++> east;

    north +>:Serves(route_id="N1"):+> Store(title="Grocer A", stock=45);
    north +>:Serves(route_id="N2"):+> Store(title="Grocer B", stock=12);
    north +>:Serves(route_id="N3"):+> Store(title="Grocer C", stock=3, available=False);

    south +>:Serves(route_id="S1"):+> Store(title="Market X", stock=80);
    south +>:Serves(route_id="S2"):+> Store(title="Market Y", stock=17);

    east +>:Serves(route_id="E1"):+> Store(title="Shoppe 1", stock=25);
    east +>:Serves(route_id="E2"):+> Store(title="Shoppe 2", stock=8);
    east +>:Serves(route_id="E3"):+> Store(title="Shoppe 3", stock=120);

    auditor = StockAuditor();
    root spawn auditor;
    print(f"Total low-stock stores flagged: {auditor.total_low}");
}

