# I'm modeling a small flight network in Jac where each flight leg is an edge storing its ticket price. The edge type should have its own method that normalizes a price against the most expensive fare in the network. Have a scout walker collect all the prices into reports, then in the main block call that method on every leg to print what fraction of the top fare it costs.
"""Flight network: priced leg edges, scout reports peak fare, each leg prints its fraction of the top ticket."""

node Airport {
    has title: str = "";
}

edge FlightLeg {
    has price: float = 0.0;

    def normalized_fare(top_fare: float) -> float {
        if top_fare <= 0.0 {
            return 0.0;
        }
        return self.price / top_fare;
    }
}

walker Scout {
    has prices: list[float] = [];
    has legs: list = [];
    has max_fare: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    can survey with Airport entry {
        for leg in [edge here ->:FlightLeg:->] {
            self.prices.append(leg.price);
            self.legs.append(leg);
            if leg.price > self.max_fare {
                self.max_fare = leg.price;
            }
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    jfk = Airport(title="JFK");
    ord_hub = Airport(title="ORD");
    lax = Airport(title="LAX");
    root ++> jfk;
    jfk +>:FlightLeg(price=450.0):+> ord_hub;
    ord_hub +>:FlightLeg(price=320.0):+> lax;
    jfk +>:FlightLeg(price=520.0):+> lax;

    scout = Scout();
    root spawn scout;
    peak = scout.max_fare;
    print(f"Network peak fare: ${peak}");
    for leg in scout.legs {
        share = leg.normalized_fare(peak);
        print(f"Leg ${leg.price} is {share} of peak fare (${peak})");
    }
}

