"""Durable agent journal + tracing demo.

Models a small agent runtime: Runs contain Turns, each Turn contains Steps,
and each Step appends a Journal row. A walker reconstructs the journal by
traversing the typed graph and prints a synthetic span tree (run -> turn ->
step -> journal row) mirroring what an OpenTelemetry tracer would emit
when the optional `tracing` feature is enabled. The same fields are used
on nodes and on the printed "spans" so traces and journal rows join.

Graph shape (typed edges):

  Run --RunTurns--> Turn --TurnSteps--> Step --StepJournal--> JournalRow
"""

node Run {
    has run_id: str = "";
    has goal: str = "";
    has started_at: str = "";
}

node Turn {
    has turn_seq: int = 0;
    has prompt_tokens: int = 0;
    has completion_tokens: int = 0;
    has latency_ms: int = 0;
}

node Step {
    has step_seq: int = 0;
    has effect_id: str = "";
    has tool_name: str = "";
    has attempt: int = 1;
    has args_hash: str = "";   # hash of tool args; never the args themselves
}

node JournalRow {
    has row_seq: int = 0;
    has event: str = "";      # e.g. "tool_call", "approval", "fingerprint_mismatch"
    has note: str = "";
}

# Typed edges carry the relationship meaning so traversal is filterable.
edge RunTurns { }
edge TurnSteps { }
edge StepJournal { }

walker Tracer {
    # Walk the run -> turn -> step -> journal chain and print a synthetic
    # span tree. We use an explicit guard set to avoid re-visiting nodes
    # on accidental cycles (jac 0.36 walkers have no built-in dedupe).
    has seen: list = [];

    can start with Root entry {
        visit [-->];
    }

    can enter_run with Run entry {
        if here in self.seen {
            disengage;
        }
        self.seen.append(here);
        print(f"span[run] run_id={here.run_id} goal=\"{here.goal}\" "
              f"started_at={here.started_at}");
        visit [->:RunTurns:->];
    }

    can enter_turn with Turn entry {
        if here in self.seen {
            disengage;
        }
        self.seen.append(here);
        total = here.prompt_tokens + here.completion_tokens;
        print(f"  span[turn] turn_seq={here.turn_seq} "
              f"prompt_tokens={here.prompt_tokens} "
              f"completion_tokens={here.completion_tokens} "
              f"total_tokens={total} latency_ms={here.latency_ms}");
        visit [->:TurnSteps:->];
    }

    can enter_step with Step entry {
        if here in self.seen {
            disengage;
        }
        self.seen.append(here);
        print(f"    span[step] run_id={...} step_seq={here.step_seq} "
              f"effect_id={here.effect_id} tool={here.tool_name} "
              f"attempt={here.attempt} args_hash={here.args_hash}");
        visit [->:StepJournal:->];
    }

    can enter_journal with JournalRow entry {
        if here in self.seen {
            disengage;
        }
        self.seen.append(here);
        print(f"      span[journal] row_seq={here.row_seq} "
              f"event={here.event} note=\"{here.note}\"");
        visit [->:StepJournal:->] else { disengage; }
    }
