"""Session-wide shared cwd slot bug (modeled).

The issue is that EnterWorktree(path:) is documented as rebinding only the
calling agent's own cwd, but in practice all shells in the session tree read
from one shared mutable slot. We model that slot as an explicit graph object
shared across the orchestrator and every subagent, and walk it to show that
a single mutation is observed by every concurrent shell.
"""

# Shared slot that the bug is about: a single cwd binding every shell reads.
node CwdSlot {
    has path: str = "";
    has last_writer: str = "";
}

# A shell — the orchestrator's persistent shell or any subagent's shell —
# reads its cwd through the shared slot instead of holding its own copy.
node Shell {
    has owner: str = "";
    has last_observed_path: str = "";
    has last_observed_writer: str = "";
    has pinned: bool = False;
}

# EnterWorktree is supposed to be a per-agent rebind. Modeled as an edge
# that, on entry, mutates the shared slot. The edge type carries the
# intended target path so we can show intended vs observed cwd.
edge EnterWorktree {
    has target_path: str = "";
    has caller: str = "";
}

# Cascade invalidation: when the shared slot is mutated, every pinned shell
# notices its last_observed_* is stale.
edge ObservedCwd {
    has at_tick: int = 0;
}

walker Tick {
    has count: int = 0;

    can advance with Root entry {
        print(f"--- tick {self.count} ---");
        visit [-->];
    }

    can sweep with Shell entry {
        here.pinned = False;
        visit [-->];
    }
}

# A walker that, from any shell, reads the shared slot. The issue is that
# this read returns the slot's current value regardless of which shell asked.
walker ReadCwd {
    has owner: str = "";

    can start with Root entry {
        visit [-->];
    }

    can read_slot with CwdSlot entry {
        # The orchestrator and every subagent arrive here and see the SAME
        # value because they all reach the single shared slot.
        print(f"  shell owner={self.owner} sees path={here.path} writer={here.last_writer}");
        visit [-->];
    }

    can ignore with Shell entry {
        visit [-->];
    }
}

# Detect cross-contamination: a sibling wrote the slot since we last read.
walker DetectContamination {
    has owner: str = "";

    can start with Root entry {
        visit [-->];
    }

    can check with Shell entry {
        if here.last_observed_writer != "" and here.last_observed_writer != self.owner and here.pinned {
            print(f"  [CONTAMINATION] shell {here.owner} last read by {here.last_observed_writer}, expected {self.owner}");
        }
        visit [-->];
    }
}

with entry {
    # The single shared slot — this is the bug object.
    slot = CwdSlot(path="/repo/main", last_writer="init");

    # Orchestrator's persistent shell.
    orch = Shell(owner="orchestrator", last_observed_path="/repo/main");

    # Concurrent subagents, each with its own shell. Each EnterWorktree edge
    # claims to rebind only the calling agent, but the slot is shared.
    root ++> slot;
    root ++> orch;

    # Subagent A enters its worktree.
    root +>:EnterWorktree(target_path="/repo/lane-a", caller="subagent-A"):+>
        Shell(owner="subagent-A", last_observed_path="/repo/main");

    # Subagent B enters its worktree.
    root +>:EnterWorktree(target_path="/repo/lane-b", caller="subagent-B"):+>
        Shell(owner="subagent-B", last_observed_path="/repo/main");

    # Subagent of a subagent (C) also rebinds the slot.
    root +>:EnterWorktree(target_path="/repo/lane-c", caller="subagent-A->subagent-C"):+>
        Shell(owner="subagent-C", last_observed_path="/repo/main");

    # 1) Initial state: everyone reads the shared slot — same value.
    print("=== initial shared-slot reads ===");
    root spawn ReadCwd(owner="orchestrator");
    root spawn ReadCwd(owner="subagent-A");
    root spawn ReadCwd(owner="subagent-B");
    root spawn ReadCwd(owner="subagent-C");

    # 2) Subagent A fires EnterWorktree(lane-a) — slot is now lane-a.
    print("\n=== after EnterWorktree(lane-a) by subagent-A ===");
    slot.path = "/repo/lane-a";
    slot.last_writer = "subagent-A";
    root spawn ReadCwd(owner="orchestrator");
    root spawn ReadCwd(owner="subagent-B");

    # 3) Subagent B fires EnterWorktree(lane-b) — slot is now lane-b, but
    #    the orchestrator's shell ALSO sees lane-b on its next read. That's
    #    the cross-contamination: orchestrator was not the caller.
    print("\n=== after EnterWorktree(lane-b) by subagent-B ===");
    slot.path = "/repo/lane-b";
    slot.last_writer = "subagent-B";
    root spawn ReadCwd(owner="orchestrator");
    root spawn ReadCwd(owner="subagent-A");

    # 4) Deep subagent C fires EnterWorktree(lane-c) — orchestrator and both
    #    sibling subagents observe lane-c. Last-writer-wins across the tree.
    print("\n=== after EnterWorktree(lane-c) by subagent-A->subagent-C ===");
    slot.path = "/repo/lane-c";
    slot.last_writer = "subagent-A->subagent-C";
    root spawn ReadCwd(owner="orchestrator");
    root spawn ReadCwd(owner="subagent-A");
    root spawn ReadCwd(owner="subagent-B");

    # 5) Reproduce the "no explicit EnterWorktree call" variant from the
    #    issue: a sibling subagent's bootstrap (modeled as a slot mutation
    #    without a typed EnterWorktree edge) still contaminates everyone.
    print("\n=== subagent bootstrap alone (no explicit EnterWorktree) ===");
    slot.path = "/repo/lane-a-boot";
    slot.last_writer = "subagent-A bootstrap";
    root spawn ReadCwd(owner="orchestrator");

    # 6) Mark all shells as pinned to their last observed value, then
    #    mutate the slot again, then run the contamination detector.
    print("\n=== contamination detection ===");
    orch.pinned = True;
    orch.last_observed_writer = "init";
    slot.path = "/repo/lane-c";
    slot.last_writer = "subagent-A->subagent-C";
    root spawn DetectContamination(owner="orchestrator");
}

