"""DMC3 L3 resource-pool lifecycle: LoadedResource registry with typed
state transitions, loader-node ownership, and a quiescence walker that
verifies every record has settled to state0 or state3.

Models the canonical 363-record pool with seven groups, the central
state writers (acquisition -> state1 -> state2 -> state3, cancellation
state1/state2 -> state4, release resets to state0), and bounded
loader-node (kind, id) ownership above the registry. A QuiescenceAuditor
walker walks the registry and reports any record that violates the
quiescence predicate (`0x1401B84B0`): every record must be state0 or
state3. The Release walker exercises the three distinct state-zero
policies (deferred state4 cleanup, owner release, full reset).
"""

# --- Edge archetypes (typed relationships) --------------------------------

edge Owns {
    # Loader-node bounded ownership (claim++ / claim--) -- (kind, id) identity.
    has kind: str = "";
    has resource_id: int = 0;
}

edge Acquires {
    # Materialization seam: L2 provider identity -> L3 FileSlot ownership.
    has provider: str = "";
}

edge PostLoad {
    # Typed post-load dispatch path (MOD / EFM / SCM / SHW / PNST family).
    has family: str = "";
}

# --- Node archetypes -------------------------------------------------------

node LoadedResource {
    has title: str = "";          # debug name (slot label)
    has group: int = 0;           # group index 0..6 (seven groups)
    has state: int = 0;           # lifecycle: 0,1,2,3,4
    has available: bool = True;   # quiescence-eligible
}

node LoaderNode {
    has title: str = "";
    has kind: str = "";           # loader family (kind of (kind, id))
    has resource_id: int = 0;     # bounded identity
}

node FileSlot {
    has title: str = "";
    has backing: str = "";        # backing/owned subobject region
    has available: bool = True;
}

# --- Walkers ---------------------------------------------------------------

walker QuiescenceAuditor {
    has bad: list = [];

    can start with Root entry {
        print("QuiescenceAuditor: scanning registry");
        visit [-->];
    }

    can audit with LoadedResource entry {
        # Central quiescence predicate `0x1401B84B0`: state must be 0 or 3.
        if not (here.state == 0 or here.state == 3) {
            self.bad.append(here.title);
            print(f"  ! violation: {here.title} group={here.group} state={here.state}");
        }
        visit [-->];
    }
}

walker Release {
    has group_filter: int = -1;

    can start with Root entry {
        if self.group_filter >= 0 {
            print(f"Release: group-{self.group_filter} reset (state0 unconditional)");
