}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------

with entry {
    # Two canary cases: one ingested from Gmail, one from Microsoft mail.
    case_g = LegalCase(
        case_id="GL-0001",
        reply_offered=True,
