# I'm making a tiny dungeon crawler in Jac. Rooms are chained nodes and one special room holds the treasure. A hunter walker should check rooms one by one while counting how many it has seen, and terminate the entire search immediately when it finds the treasure room — rooms past the vault must never be visited.
"""Tiny dungeon crawler: rooms chained as nodes, one holds the treasure.

A Hunter walker traverses the chain room by room, counting how many it has
seen. The instant it steps into the vault the walk terminates — no room
beyond the treasure is ever visited.
"""

node Room {
    has name: str = "";
    has is_vault: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can explore with Room entry {
        self.rooms_checked += 1;
        if here.is_vault {
            print(f"Treasure found in '{here.name}' after checking {self.rooms_checked} room(s).");
            disengage;
