        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes")
        ++> Room(name="Vault", is_vault=True)
        ++> Room(name="Forbidden Crypt")
        ++> Room(name="Dragon's Lair");

    hunter = Hunter();
    root spawn hunter;
    print(f"Hunter stopped after inspecting {hunter.rooms_checked} room(s); the rest of the dungeon stays dark.");
