    helper.route_case(c2, p_primary, p_fallback);
    helper.route_case(c3, p_primary, p_fallback);
    helper.route_case(c5, p_primary, p_fallback);

    auditor = Auditor();
    root spawn auditor;

    print("Benchmark findings:");
    for cid in auditor.findings.keys() {
        row = auditor.findings[cid];
        print(f"  {cid}: {row}");
    }
}

