# I am working on a focused enhancement of Langflow's existing authentication and authorization foundations to support team-based collaboration and explicit project/workflow sharing.
# 
# ## Proposed behavior
# 
# ### Team administration
# 
# - Add a **Teams** tab to the administration area.
# - Allow Platform Admins to create and manage teams.
# - Require every team to be created with an initial non-empty membership.
# - Require every active team to have at least one active Team Admin.
# - Support team-scoped membership roles:
#   - **Admin:** manages the team's settings, members, and member roles.
#   - **Maintainer:** adds or removes ordinary team members.
#   - **User:** receives access to resources shared with the team.
# - Keep team roles separate from platform-wide superuser authority and resource permissions.
# 
# ### Project and workflow sharing
# 
# - Add a **Share** action to the existing project and workflow menus.
# - Allow a resource owner to share a project or workflow even when the owner is not a Platform Admin.
# - Support sharing with:
#   - A specific existing user.
#   - A specific existing team.
# - Provide two user-facing access modes:
#   - **Can use:** can view and run the saved workflow, but cannot edit it.
#   - **Can edit:** can view, run, and edit permitted content.
# - Editing access does not automatically allow resharing, deletion, ownership transfer, publication changes, authentication-setting changes, or moving another user's resource.
# - Sharing a project applies dynamically to its current and future workflows.
# - Sharing an individual workflow does not expose its private parent project or sibling workflows.
# 
# ### Authorization and ownership
# 
# - Preserve the existing authentication mechanisms, including local sessions, JWTs, API keys, and external authentication.
# - Keep authentication separate from authorization.
# - Preserve the authenticated caller as the execution principal.
# - Sharing a workflow does not transfer the owner's credentials, variables, private dependencies, files, or provider configuration.
# - Keep workflow ownership with the authenticated creator, including workflows created inside another user's shared project.
# - Apply permission changes and revocation to newly admitted requests without requiring a process restart.
# - Protect collaborative saves against stale concurrent updates.
# 
# ## Current work
# 
# - Fork: https://github.com/waqoor/langflow
# - Branch: `feat/auth-team-sharing`
# - Work-in-progress PR: https://github.com/waqoor/langflow/pull/1
# 
# The implementation is currently incomplete and is not ready to merge or deploy. I am opening this issue to make the work visible and obtain early maintainer feedback on the product scope, authorization semantics, and expected upstream architecture.
# 
# A previous discussion in #1864 mentioned Casbin as the intended RBAC/ABAC direction. The current fork implementation is designed around Langflow's existing `BaseAuthorizationService` interface and canonical `authz_*` tables. Maintainer guidance would be appreciated on whether an upstream implementation should remain behind the existing plugin/Casbin boundary or whether a native OSS enforcing implementation is acceptable.
# 
# ## Out of scope
# 
# This work does not introduce:
# 
# - A replacement login or identity system.
# - Email invitations for users who do not already exist.
# - Team-owned credentials.
# - Credential delegation from resource owners.
# - Real-time collaborative graph editing.
# - A tenant execution sandbox.
# - A new API version.
# - A second authorization store or parallel policy engine.
# - Canary, staging, shadow, or parallel production paths.
# 
# ### Use Case
# 
# ### Team administration
# 
# As a Langflow Platform Admin, I want to create non-empty teams and assign team-scoped Admin, Maintainer, and User roles so that collaboration can be managed without granting every team manager platform-wide superuser access.
# 
# ### Direct sharing
# 
# As a project or workflow owner, I want to share a resource with a specific existing user as either **Can use** or **Can edit** so that I control whether that collaborator may only run the resource or also modify it.
# 
# ### Team sharing
# 
# As a resource owner, I want to share a project or workflow with a team so that current and future eligible team members receive the configured access without creating individual grants for every member.
# 
# ### Project inheritance
# 
# As a collaborator, I want a project share to cover its current and future workflows so that access remains consistent as workflows are added to the project.
# 
# ### Permission consistency
# 
# As a collaborator, I want the homepage, direct resource URLs, APIs, editor controls, save operations, and execution endpoints to enforce the same effective permissions so that inaccessible operations are not merely hidden in the frontend.
# 
# ### Revocation and concurrent editing
# 
# As a resource owner, I want a permission downgrade or revocation to affect new requests immediately, and I want stale saves to be rejected, so that an open editor cannot silently bypass changed access or overwrite another user's newer changes.
# 
# ### Implementation Plan
# 
# The implementation extends the existing Langflow architecture rather than introducing a separate authorization or collaboration subsystem.
# 
# ## 1. Data model and migrations
# 
# - Extend the existing team membership model with the team-scoped roles:
#   - `admin`
#   - `maintainer`
#   - `user`
# - Add the state required to distinguish manually inactive teams from teams suspended because they have no active Team Admin.
# - Add revision metadata for share changes and collaborative project/workflow updates.
# - Generate forward-only Alembic migrations against the actual migration head.
# - Preserve existing team, role, share, project, workflow, and user identifiers.
# - Preserve existing `read`, `execute`, `write`, and `admin` API permission values.
# - Do not add a separate membership table, sharing table, or policy database.
# 
# ## 
# 
# Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.
"""Team-based resource sharing with cycle-safe graph traversal."""

node User {
    has key: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Team {
    has key: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Project {
    has key: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has revision: int = 1;
}

node Workflow {
    has key: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has revision: int = 1;
}

edge Collaboration {
    has kind: str = "";
    has role: str = "user";
    has access: str = "can_use";
    has inherited: bool = False;
    has active: bool = True;
}

walker SharingAuditor {
    has seen: list[str] = [];
    has records: list[str] = [];
    has visited_count: int = 0;
    has cycle_found: bool = False;

    can begin with Root entry {
        print("Auditing team and resource relationships");
        visit [->:Collaboration:->];
    }

    can inspect with User | Team | Project | Workflow entry {
        if here.key in self.seen {
            self.cycle_found = True;
            print(f"Cycle detected at {here.title}");
        } else {
            self.seen.append(here.key);
            self.records.append(here.title);
            self.visited_count += 1;
            print(f"Reached {here.title}");
            visit [->:Collaboration:->] else { skip; }
        }
    }

    can summarize with Root exit {
        print(f"Reachable entities: {self.visited_count}");
        print(f"Cycle guard triggered: {self.cycle_found}");
        print(f"Audit order: {self.records}");
    }
}

with entry {
    owner = User(key="u-owner", title="Owner", year=0, available=True);
    member = User(key="u-member", title="Contributor", year=0, available=True);
    team = Team(key="team-design", title="Design Team", year=0, available=True);
    project = Project(key="project-flow", title="Shared Project", year=2024, available=True);
    workflow = Workflow(key="workflow-main", title="Main Workflow", year=2024, available=True);

    root +>:Collaboration(kind="contains"):+> team;
    root +>:Collaboration(kind="contains"):+> owner;
    team +>:Collaboration(kind="membership", role="admin", active=True):+> owner;
    team +>:Collaboration(kind="membership", role="user", active=True):+> member;
    owner +>:Collaboration(kind="owns"):+> project;
    project +>:Collaboration(kind="contains"):+> workflow;
    project +>:Collaboration(kind="share", access="can_edit", inherited=True):+> team;
    project +>:Collaboration(kind="share", access="can_use", inherited=False):+> member;
    member +>:Collaboration(kind="member_of"):+> team;
    workflow +>:Collaboration(kind="context"):+> project;

    root spawn SharingAuditor();
}

# Language: Jac
# from: osp__Railroad-Team__Railroad__582__sstp3sst
node Snapshot {
    has version: str;
}

node Symbol {
    has sid: str;
    has origin: str = "source";
}

edge DirectCall {}
edge AliasCall {}
edge ApproximateCall {}

obj CallGraphService {
    has snapshot: Snapshot;
    has precision: str = "balanced";
    has symbols: dict[str, Symbol] = {};
    has cache: dict[str, list[str]] = {};
}

walker CallReach {
    has claimed: dict[str, bool] = {};
    has precision: str = "balanced";
    has found: list[str] = [];

    can collect with Symbol entry {
        if here.sid in self.claimed {
            skip;
        }
        self.claimed[here.sid] = True;
        self.found.append(here.sid);
        print(here.sid);

        for kid in [here ->:DirectCall:->][?:Symbol] {
            visit :0: [kid];
        }

        if self.precision != "fast" {
            for kid in [here ->:AliasCall:->][?:Symbol] {
                visit :0: [kid];
            }
        }

        if self.precision == "sound" {
            for kid in [here ->:ApproximateCall:->][?:Symbol] {
                visit :0: [kid];
            }
        }
    }
}

def new_service(snapshot_id: str, precision: str = "balanced")
    -> CallGraphService {
    snapshot = Snapshot(version=snapshot_id);
    service = CallGraphService(snapshot=snapshot);
    set_precision(service, precision);
    return service;
}

def set_precision(service: CallGraphService, precision: str) -> None {
    if precision == "fast" {
        service.precision = "fast";
    } else {
        if precision == "sound" {
            service.precision = "sound";
        } else {
            service.precision = "balanced";
        }
    }
    service.cache = {};
}

def register_symbol(
    service: CallGraphService,
    sid: str,
    origin: str = "source"
) -> Symbol {
    symbol = Symbol(sid=sid, origin=origin);
    service.symbols[sid] = symbol;
    service.cache = {};
    return symbol;
}

def add_call(
    service: CallGraphService,
    caller_id: str,
    callee_id: str,
    kind: str = "direct"
) -> None {
    if caller_id not in service.symbols {
        return;
    }
    if callee_id not in service.symbols {
        return;
    }

    caller = service.symbols[caller_id];
    callee = service.symbols[callee_id];

    if kind == "direct" {
        caller +>:DirectCall:+> callee;
    } else {
        if kind == "alias" {
            caller +>:AliasCall:+> callee;
        } else {
            caller +>:ApproximateCall:+> callee;
        }
    }
    service.cache = {};
}

def invalidate(service: CallGraphService) -> None {
    service.cache = {};
}

def query_calls(
    service: CallGraphService,
    entry_id: str,
    cancelled: bool = False
) -> list[str] {
    if cancelled {
        return [];
    }
    if entry_id not in service.symbols {
        return [];
    }

    key = service.snapshot.version + "|" + service.precision + "|" + entry_id;
    if key in service.cache {
        return service.cache[key];
    }

    graph_root = service.symbols[entry_id];
    w = graph_root spawn CallReach(
        claimed={},
        precision=service.precision
    );
    result: list[str] = sorted(w.found);
    service.cache[key] = result;
    return result;
}

