    has seen_records: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can step with Property entry {
        if here.slot not in self.seen_slots {
            self.seen_slots.append(here.slot);
        }
        visit [-->];
    }

    can step_rec with Record entry {
        if here.label not in self.seen_records {
            self.seen_records.append(here.label);
        }
        visit [-->];
    }
}

