    r1 +>:PartOf(ordinal=7):+> p_last;
    r2 +>:PartOf(ordinal=0):+> p_first;
    r2 +>:PartOf(ordinal=4):+> p_mid;
    r2 +>:PartOf(ordinal=7):+> p_last;
    r3 +>:PartOf(ordinal=0):+> p_first;
    r3 +>:PartOf(ordinal=4):+> p_mid;
