# --- Column metadata model ---------------------------------------------------

node Column {
    has name: str = "";
    has js_type: str = "raw";  # "raw" | "bigint" | "number"
}

# --- Branch archetypes --------------------------------------------------------

node LeafSelect {
    has label: str = "";
    has output_columns: list = [];
}

node SetOperation {
    has label: str = "";
}

node CteWrap {
    has label: str = "";
}

node RecursiveCte {
    has label: str = "";
}

# --- Typed edges -------------------------------------------------------------

edge BranchesTo {
    has position: int = 0;
}

edge OuterWraps {
    # CTE / recursive CTE wrapping an inner select
}

# --- Walker: cross-branch agreement fold -------------------------------------

walker ProvenanceFolder {
    has output_columns: list = [];

    can start with Root entry {
        visit [-->];
    }

    # Simple CTE: passthrough of inner select's metadata (single source).
    can fold_simple_cte with CteWrap entry {
        inner_targets = [here ->:OuterWraps:->];
        if inner_targets {
            inner = inner_targets[0];
            self.output_columns = inner.output_columns;
            print(f"[CteWrap] {here.label} -> single-source passthrough");
            for col in self.output_columns {
                marker = "convert" if col.js_type != "raw" else "abstain";
                print(f"  pos {col.name}: {col.js_type} ({marker})");
            }
        }
    }

    # Set operation: fold over agreement of every branch at each position.
    can fold_setop with SetOperation entry {
        branches = [here ->:BranchesTo:->];
        first_cols = branches[0].output_columns;
        n = len(first_cols);
        agreed: list = [];
        for i in range(0, n) {
            candidate = first_cols[i].js_type;
            all_match = True;
            for b in branches {
                b_cols = b.output_columns;
                if i >= len(b_cols) {
                    all_match = False;
                    break;
                }
                if b_cols[i].js_type != candidate {
                    all_match = False;
                    break;
                }
            }
            resolved = candidate if all_match else "raw";
            col = Column(name=first_cols[i].name, js_type=resolved);
            agreed.append(col);
        }
        self.output_columns = agreed;
        print(f"[SetOperation] {here.label} -> agreement fold over "
              f"{len(branches)} branches:");
        for col in agreed {
            marker = "convert" if col.js_type != "raw" else "abstain";
            print(f"  pos {col.name}: {col.js_type} ({marker})");
        }
    }

    # Recursive CTE: base + step at the same positions; same fold as set-op.
    can fold_recursive with RecursiveCte entry {
        branches = [here ->:BranchesTo:->];
        first_cols = branches[0].output_columns;
        n = len(first_cols);
        agreed: list = [];
        for i in range(0, n) {
            candidate = first_cols[i].js_type;
            all_match = True;
            for b in branches {
                b_cols = b.output_columns;
                if i >= len(b_cols) {
                    all_match = False;
                    break;
                }
                if b_cols[i].js_type != candidate {
                    all_match = False;
                    break;
                }
            }
            resolved = candidate if all_match else "raw";
            col = Column(name=first_cols[i].name, js_type=resolved);
            agreed.append(col);
        }
        self.output_columns = agreed;
        print(f"[RecursiveCte] {here.label} -> agreement fold over "
              f"{len(branches)} branches:");
        for col in agreed {
            marker = "convert" if col.js_type != "raw" else "abstain";
            print(f"  pos {col.name}: {col.js_type} ({marker})");
        }
    }

    can record_leaf with LeafSelect entry {
        self.output_columns = here.output_columns;
        print(f"[LeafSelect] {here.label}: "
              f"{[c.js_type for c in here.output_columns]}");
    }
}

# --- Demonstration wiring ----------------------------------------------------

with entry {
    # All-agreeing UNION: both branches project js:'bigint' at every position.
    all_bigint_a = LeafSelect(label="leaf-A");
    all_bigint_a.output_columns = [
        Column(name="id", js_type="bigint"),
        Column(name="count", js_type="bigint"),
    ];

    all_bigint_b = LeafSelect(label="leaf-B");
    all_bigint_b.output_columns = [
        Column(name="id", js_type="bigint"),
        Column(name="count", js_type="bigint"),
    ];

    # Disagreeing UNION: branch B uses a plain raw column at position 1.
    disagree_a = LeafSelect(label="leaf-disagree-A");
    disagree_a.output_columns = [
        Column(name="id", js_type="bigint"),
        Column(name="label", js_type="number"),
    ];

    disagree_b = LeafSelect(label="leaf-disagree-B");
    disagree_b.output_columns = [
        Column(name="id", js_type="bigint"),
        Column(name="label", js_type="raw"),
    ];

    # CTE: single-source passthrough.
    cte_inner = LeafSelect(label="cte-inner");
    cte_inner.output_columns = [
        Column(name="id", js_type="bigint"),
        Column(name="value", js_type="number"),
    ];

    # Recursive CTE: base + step at the same positions, both js:'bigint'.
    rec_base = LeafSelect(label="rec-base");
    rec_base.output_columns = [
        Column(name="node_id", js_type="bigint"),
        Column(name="depth", js_type="bigint"),
    ];

    rec_step = LeafSelect(label="rec-step");
    rec_step.output_columns = [
        Column(name="node_id", js_type="bigint"),
        Column(name="depth", js_type="bigint"),
    ];

    # --- Graph topology --------------------------------------------------------

    # UNION (all-agree): set-op node with two branches.
    union_ok = SetOperation(label="UNION-ok");
    root +>:BranchesTo(position=0):+> union_ok;
    union_ok +>:BranchesTo(position=0):+> all_bigint_a;
    union_ok +>:BranchesTo(position=1):+> all_bigint_b;

    # UNION (disagreeing): set-op node with two branches.
    union_mixed = SetOperation(label="UNION-mixed");
    root +>:BranchesTo(position=1):+> union_mixed;
    union_mixed +>:BranchesTo(position=0):+> disagree_a;
    union_mixed +>:BranchesTo(position=1):+> disagree_b;

    # Simple CTE: wrapper around inner select.
    cte = CteWrap(label="CTE-simple");
    root +>:BranchesTo(position=2):+> cte;
    cte +>:OuterWraps:+> cte_inner;

    # Recursive CTE: base + step joined as a positional UNION.
    rec_cte = RecursiveCte(label="RecursiveCTE");
    root +>:BranchesTo(position=3):+> rec_cte;
    rec_cte +>:BranchesTo(position=0):+> rec_base;
    rec_cte +>:BranchesTo(position=1):+> rec_step;

    # --- Spawn the walker ------------------------------------------------------
    print("=== Cross-branch agreement fold ===");
    root spawn ProvenanceFolder();
}

