    has host_name: str = "ClaudeDesktop";
    has init_deadline_s: int = 60;
}

node McpServer {
    has title: str = "";
    has launcher_cmd: str = "";
    has deps: str = "";
    has deadline_hit: bool = False;
    has stage_reached: str = "spawning";
}

node Launcher {
    has runner: str = "";
    has cold_start_s: int = 0;
    has downloaded: bool = False;
}

node Backend {
    has process_name: str = "";
    has tools_exposed: int = 0;
    has reachable: bool = False;
}

edge Configured { has config_key: str = ""; }
edge RunsVia { }
edge Spawns { has pid: int = 0; }

walker DeadlineRacer {
    has deadline_s: int = 60;

    can start with Desktop entry {
        print(f"Desktop {here.host_name} enforces {here.init_deadline_s}s init deadline");
        visit [->:Configured:->];
    }

    can race with McpServer entry {
        server = here;
        launcher_nodes = [here->:RunsVia:->];
        if not launcher_nodes {
            server.stage_reached = "no-launcher";
            server.deadline_hit = True;
            print(f"  [{server.title}] no launcher configured");
            visit [->:Configured:->];
            disengage;
        }
        launcher = launcher_nodes[0];
        if launcher.cold_start_s > self.deadline_s {
            server.deadline_hit = True;
            server.stage_reached = "downloading";
            print(f"  [{server.title}] cancelled at {self.deadline_s}s while {launcher.runner} was resolving {server.deps}");
        } else {
            server.stage_reached = "backend-ready";
            print(f"  [{server.title}] backend ready in {launcher.cold_start_s}s");
        }
        visit [->:Configured:->];
    }
}

walker LateAttacher {
    can start with Desktop entry {
        print(f"Late attach pass: checking for backends that came up after the deadline");
        visit [->:Configured:->];
    }

    can find with McpServer entry {
        launcher_nodes = [here->:RunsVia:->];
        if launcher_nodes {
            backend_nodes = [launcher_nodes[0]->:Spawns:->];
            if here.deadline_hit and backend_nodes {
                backend = backend_nodes[0];
                backend.reachable = False;
                print(f"  [orphan] {here.title}: {backend.process_name} is up with {backend.tools_exposed} tools but unreachable");
            }
        }
        visit [->:Configured:->];
    }
}

with entry {
    desktop = Desktop(host_name="ClaudeDesktop", init_deadline_s=60);
    root ++> desktop;

    # Server 1: cold start inside the 60 s window — works fine.
    s1 = McpServer(title="weather", launcher_cmd="uvx weather-mcp", deps="httpx");
    desktop +>:Configured(config_key="weather"):+> s1;
    l1 = Launcher(runner="uvx", cold_start_s=20, downloaded=True);
    s1 +>:RunsVia:+> l1;
    b1 = Backend(process_name="weather-mcp", tools_exposed=4, reachable=True);
    l1 +>:Spawns(pid=4101):+> b1;

    # Server 2: cold start exceeds 60 s — matches the bug report.
    s2 = McpServer(title="opensearch", launcher_cmd="uvx opensearch-mcp-server-py", deps="botocore,boto3");
    desktop +>:Configured(config_key="opensearch"):+> s2;
    l2 = Launcher(runner="uvx", cold_start_s=110, downloaded=True);
