    b2 = Backend(process_name="opensearch-mcp-server-py", tools_exposed=7, reachable=True);
    l2 +>:Spawns(pid=4102):+> b2;

    # Server 3: another over-budget cold start, no backend ever spawned.
    s3 = McpServer(title="metrics", launcher_cmd="uvx metrics-mcp", deps="numpy,scipy");
    desktop +>:Configured(config_key="metrics"):+> s3;
    l3 = Launcher(runner="uvx", cold_start_s=140, downloaded=False);
    s3 +>:RunsVia:+> l3;

