walker InverseResolver {
    can start with Root entry {
        visit [-->];
    }

    can resolve_inverse with Holon entry {
        space_node: HolonSpace | None = None;
        for n in [-->] {
            if isinstance(n, HolonSpace) {
                space_node = n;
            }
