node SessionGraph {
    has nodes: dict[str, Session] = {};
}

walker TipWalker {
    has claimed: dict[str, bool] = {};
    has tip_id: str = "";
    can step with Session entry {
        if here.id in self.claimed { skip; }
        self.claimed[here.id] = True;
        print(here.id);
        if here.end_reason != "compression" {
            self.tip_id = here.id;
            disengage;
        }
        kids: list[Session] = [];
        for ch in [here ->:CompressLink:->][?:Session] {
            kids.append(ch);
        }
        if kids {
            visit :0: kids;
        } else {
            self.tip_id = here.id;
            disengage;
        }
    }
}

walker DemoWalker {
    has claimed: dict[str, bool] = {};
    can tour with Session entry {
        if here.id in self.claimed { skip; }
        self.claimed[here.id] = True;
        print(here.id);
        kids: list[Session] = [];
        for ch in [here ->:CompressLink:->][?:Session] {
            kids.append(ch);
        }
        if kids {
            visit kids;
        }
    }
