    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can step_entity with Entity entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.found.append(here.cid);
        print({"comp": here.cid});
        kids: list[Entity] = [];
        for ch in [here ->:Neighbor:->][?:Entity] {
