node Artifact {
    has title: str = "";
    has phase: int = 0;
    has complete: bool = False;
    has unit: str = "";
}

node IntentDoc {
    has title: str = "intent.md";
    has phase: int = 1;
    has complete: bool = False;
    has unit: str = "spec";
    has acceptance_criteria: int = 0;
}

node DesignDoc {
    has title: str = "design.md";
    has phase: int = 2;
    has complete: bool = False;
    has unit: str = "spec";
    has architecture_decisions: int = 0;
    has risks: int = 0;
}

node Task {
    has title: str = "";
    has phase: int = 3;
    has complete: bool = False;
    has unit: str = "task";
    has depends_on: str = "";
    has validated: bool = False;
    has task_title: str = "";
}

node SummaryDoc {
    has title: str = "summary.md";
    has phase: int = 4;
    has complete: bool = False;
    has unit: str = "spec";
    has stakeholder_ready: bool = False;
}

edge Produces {
    has order: int = 0;
}

walker PipelineAuditor {
    has gaps: list[str] = [];
    has validated_count: int = 0;

    can start with Root entry {
        print("Auditing spec-driven pipeline...");
        visit [-->];
    }

    can inspect with Artifact entry {
        status = "OK" if here.complete else "MISSING";
        print(f"  [{status}] phase={here.phase} {here.title}");
        visit [-->];
    }

    can deepen with DesignDoc entry {
        gap = f"design risks={here.risks}" if here.risks < 3 else "";
        if gap != "" {
            self.gaps.append(gap);
        }
        visit [-->];
    }

    can check_task with Task entry {
        if here.validated {
            self.validated_count += 1;
        } else {
            self.gaps.append(f"task {here.task_title} unvalidated (depends on {here.depends_on})");
        }
        visit [-->];
    }
}

with entry {
    intent = IntentDoc(complete=True, acceptance_criteria=14);
    design = DesignDoc(complete=True, architecture_decisions=5, risks=5);
    task_a = Task(title="movement", task_title="movement", depends_on="design", validated=True);
    task_b = Task(title="collision", task_title="collision", depends_on="task_a", validated=False);
    summary = SummaryDoc(complete=True, stakeholder_ready=True);

    root ++> intent
        ++> design
        ++> task_a
        ++> task_b
        ++> summary;

    auditor = PipelineAuditor();
    root spawn auditor;

    print(f"\nValidated tasks: {auditor.validated_count}");
    print(f"Gaps found: {auditor.gaps}");
}

