node Scratch {
    has name: str = "";
    has reserve_qty: int = 0;
    has working_set: int = 0;
    has floor: int = 512;
    has capacity_after_shrink: int = 0;
    has thrashes: bool = False;
}

node Frame {
    has frame_index: int = 0;
    has draw_commands_len: int = 0;
    has batch_count: int = 0;
}

edge HoldsScratch {}
edge HoldsFrame {}

walker AuditOne {
    can start with Root entry {
        visit [->:HoldsScratch:->];
    }

    can audit with Scratch entry {
        # Mirrors draw.rs: reserve(reserve_qty) then shrink target
        # = 2 * max(working_set, floor).
        effective_working = here.working_set if here.working_set > here.floor else here.floor;
        target = 2 * effective_working;
        # Reserve happens before shrink: capacity grows to >= reserve_qty,
        # then shrink_to(target) drops it if reserve_qty > target.
        capacity_post_reserve = here.reserve_qty;
        post = capacity_post_reserve if capacity_post_reserve <= target else target;
        here.capacity_after_shrink = post;
        # Thrashes if next frame's reserve() would grow again after the shrink.
        here.thrashes = here.reserve_qty > target;
    }
}

walker RunFrames {
    can start with Root entry {
        visit [->:HoldsFrame:->];
    }

    can step with Frame entry {
        root spawn AuditOne();
        visit [->:HoldsFrame:->];
    }
}

