node RestoreFile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has kind: str = "regular";
}

edge Contains {
    has relative_path: str = "";
}

walker NarExtractor {
    has windows_mode: bool = True;
    has directories_seen: int = 0;
    has files_seen: int = 0;
    has aborted: bool = False;

    can start with Root entry {
        print("starting NAR extraction");
        visit [->:Contains:->] else {
            disengage;
