        visit [->:Contains:->] else {
            disengage;
        }
    }
}

with entry {
    root_dir = RestoreDirectory(
        title="NAR root",
        path="/store/example",
        is_root=True,
        dir_fd_ready=True
    );
    nested_dir = RestoreDirectory(
        title="nested directory",
        path="/store/example/bin",
        is_root=False,
        dir_fd_ready=False
    );
    payload = RestoreFile(
        title="executable",
        path="/store/example/bin/tool",
        kind="regular"
    );

