    delta = Tool(name="HAVE_DELTA", binary_present=True, documented=False, downstream_consumers=0);
    direnv = Tool(name="HAVE_DIRENV", binary_present=True, documented=False, downstream_consumers=0);
    mise = Tool(name="HAVE_MISE", binary_present=True, documented=False, downstream_consumers=0);

    # Live group (5 in the issue; modeled in full).
    astgrep = Tool(name="HAVE_ASTGREP", binary_present=True, documented=False, downstream_consumers=2);
    atuin = Tool(name="HAVE_ATUIN", binary_present=True, documented=False, downstream_consumers=3);
    jnv = Tool(name="HAVE_JNV", binary_present=True, documented=False, downstream_consumers=1);
    jq = Tool(name="HAVE_JQ", binary_present=True, documented=False, downstream_consumers=5);
    shellcheck = Tool(name="HAVE_SHELLCHECK", binary_present=True, documented=False, downstream_consumers=2);

    # The declared surface — only jq and shellcheck survive the narrowing
    # proposed in the issue's "decision worth making explicitly" section.
    f_jq = Flag(name="HAVE_JQ", supported=True);
    f_shellcheck = Flag(name="HAVE_SHELLCHECK", supported=True);

    # Wire the graph. Tools hang off root; declared flags hang off root too.
    # Each live tool connects to the flag(s) that back it via a ConsumedBy edge
    # whose payload names the OS-repo consumer (the "both-directions" audit).
    root ++> delta ++> direnv ++> mise;
    root ++> astgrep ++> atuin ++> jnv ++> jq ++> shellcheck;
    root ++> f_jq ++> f_shellcheck;

    jq +>:ConsumedBy(consumer="os-mint"):+> f_jq;
    jq +>:ConsumedBy(consumer="role-sre"):+> f_jq;
    atuin +>:ConsumedBy(consumer="os-mint"):+> f_jq;  # NOT declared — should fail
    shellcheck +>:ConsumedBy(consumer="role-review"):+> f_shellcheck;

