    root +>:DeclaredIn(as_of="v5.0.0"):+> f_jq;
    root +>:DeclaredIn(as_of="v5.0.0"):+> f_shellcheck;

    # Run the audit.
    auditor = SupportAudit();
    root spawn auditor;
    print("--- audit violations ---");
    for v in auditor.violations {
        print(v);
    }
    print(f"total: {len(auditor.violations)}");

    # Run the contract-surface collector to show the declared set.
    surface = ContractSurface();
    root spawn surface;
    print("--- declared surface ---");
    for d in surface.declared {
        print(d);
    }
}

