    has slow_threshold: float = 20.0;
    has slow: list = [];
    has dupes: list = [];

    can start with Root entry {
        print("=== Build Performance Audit (2026-07-20) ===");
        visit [-->];
    }

    can sweep with Crate | FeatureSet | BuildScript entry {
        visit [-->];
    }

    can rank with Crate entry {
        verdict = "SLOW" if here.total_time_s >= self.slow_threshold else "ok";
        if here.total_time_s >= self.slow_threshold {
            self.slow.append([here.name, here.total_time_s, verdict]);
