edge ManifestEntry {}     # Snapshot --holds--> DeletionVector | DataFile
edge Targets {}           # DeletionVector --targets--> DataFile
edge IndexedDeletes {}    # Snapshot --indexed--> DeletionVector (post-recovery)

walker IndexRecovery {
    # Per-data-file accumulator of candidate DVs seen in the manifest.
    has dv_by_path: dict[str, list[DeletionVector]] = {};
    # Final, deduplicated / merged DVs per data file.
    has indexed: dict[str, DeletionVector] = {};
    # Track which data files have been seen in this snapshot (one entry per file).
    has seen_files: dict[str, bool] = {};

    can start with Root entry {
        visit [-->];
    }

    can enter_snapshot with Snapshot entry {
        # Clear walker state so a re-spawn is idempotent.
        self.dv_by_path = {};
        self.indexed = {};
        self.seen_files = {};
        visit [->:ManifestEntry:->];
    }

    can collect_dv with DeletionVector entry {
        target = here.referenced_data_file;
        bucket = self.dv_by_path.get(target, []);
        bucket.append(here);
        self.dv_by_path[target] = bucket;
        visit [-->];
    }

    can note_file with DataFile entry {
        self.seen_files[here.path] = True;
        visit [-->];
    }

    def finish_snapshot() -> None {
        # Post-pass: the equivalent of ``Builder.build()`` in Iceberg.
        # We cannot trigger this from a Snapshot exit ability in a way that
        # sees ``here`` reliably across spawn, so we run it directly below
        # after traversal completes; the walker report still carries state.
        for (path, candidates) in self.dv_by_path.items() {
            survivor = self.merge_or_dedup(candidates);
            self.indexed[path] = survivor;
            if len(candidates) > 1 {
                all_same = True;
                first_key = IndexRecovery.blob_key(candidates[0].blob);
                for dv in candidates[1:] {
                    if IndexRecovery.blob_key(dv.blob) != first_key {
                        all_same = False;
                        break;
