edge UsesTexture { }
edge BackedBy { }
edge AllocatedFrom { }

walker PageFaultAudit {
    has hop_budget: int = 20;
    has fault_pages: int = 0;
    has mapped_buffers: int = 0;

    can start with Root entry {
        print("walking submit resource graph");
        visit [->:Submitted:->] else { disengage; }
