        year=2024,
        source="AGENTS.md"
    );
    runner = Runner(
        title="bounded process runner",
        year=2024,
        timeout_ms=1500,
        output_limit=4096
    );
    context = Context(
        title="projected repository context",
        year=2024,
        cache_key="octet:ygg-serve",
