    );

    root +>:Contains(slot="repository"):+> repo;
    repo +>:Contains(slot="instructions"):+> instructions;
    instructions +>:Executes(timeout_ms=1500, output_limit=4096):+> runner;
    runner +>:Projects(source_path="src/repository_context.rs"):+> context;
    context +>:Invalidates(reason="stale cache or malformed repository"):+> repo;

