"""Stoichiometry-aware reaction I/O walker.

Models the essential scenario from issue #48: a reaction walker visits its
typed input/output edges, picks up the curated stoichiometric coefficient,
aggregates duplicate coefficients onto the same target node, and reports
the totals — replacing the hand-rolled `_resolve_vr_entities` machinery that
hardcoded every coefficient to 1.
"""

node Entity {
    has name: str = "";
    has has_curated_coef: bool = False;
}

node EntitySetMember {
    has name: str = "";
    has member_coef: int = 1;
}

node Reaction {
    has name: str = "";
}

edge InputEdge {
    has stoichiometry: int = 1;
    has curated: bool = False;
}

edge OutputEdge {
    has stoichiometry: int = 1;
    has curated: bool = False;
}

walker StoichiometryAuditor {
    has in_totals: dict = {};
    has out_totals: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can audit with Reaction entry {
        print(f"Reaction: {here.name}");
        self.in_totals = {};
        self.out_totals = {};
        visit [->:InputEdge:->];
    }

    can tally_inputs with Entity | EntitySetMember entry {
        if isinstance(here, EntitySetMember) {
            coef = here.member_coef;
        } elif here.has_curated_coef {
            coef = 2;
        } else {
            coef = 1;
        }
        key = here.name;
        prior = self.in_totals.get(key, 0);
        self.in_totals[key] = prior + coef;
    }

    can finish_inputs with Entity | EntitySetMember entry {
        visit [->:OutputEdge:->];
    }

    can tally_outputs with Entity | EntitySetMember entry {
        if isinstance(here, EntitySetMember) {
            coef = here.member_coef;
        } elif here.has_curated_coef {
            coef = 2;
        } else {
            coef = 1;
        }
        key = here.name;
        prior = self.out_totals.get(key, 0);
        self.out_totals[key] = prior + coef;
        print(f"  output coef {coef} to {here.name}; running total {self.out_totals[key]}");
        if len(self.in_totals) > 0 and len(self.out_totals) == len(self.in_totals) {
            print("  input totals:");
            for (k, v) in self.in_totals.items() {
                print(f"    {k}: {v}");
            }
            print("  output totals:");
            for (k, v) in self.out_totals.items() {
                print(f"    {k}: {v}");
            }
        }
    }
}

with entry {
    rxn = Reaction(name="R1");
    root ++> rxn;

    eA = Entity(name="A", has_curated_coef=True);
    eB = Entity(name="B", has_curated_coef=False);
    eC = Entity(name="C", has_curated_coef=True);
    mA1 = EntitySetMember(name="A#1", member_coef=2);
    mA2 = EntitySetMember(name="A#2", member_coef=2);

    rxn +>:InputEdge(stoichiometry=2, curated=True):+> eA;
    rxn +>:InputEdge(stoichiometry=1, curated=False):+> eB;
    rxn +>:InputEdge(stoichiometry=1, curated=False):+> mA1;
    rxn +>:InputEdge(stoichiometry=1, curated=False):+> mA2;
    rxn +>:InputEdge(stoichiometry=1, curated=False):+> eC;

    rxn +>:OutputEdge(stoichiometry=1, curated=False):+> eB;

    auditor = StoichiometryAuditor();
    root spawn auditor;
