# 
# 
# Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.
"""OAK adapter selection demo: ontology terms, subclass closures, and a walker
that performs ``reachable_from``-style descendant traversal with cycle guards
so we can compare cold/warm behavior and surface the over-return ubergraph
problem (mirrors of OAK issues #55/#57).
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node Term {
    has id: str = "";
    has label: str = "";
    has ontology: str = "";
}

# A subclass assertion: every subclass is reachable from its superclass via is_a.
edge IsA {
    has predicate: str = "is_a";
}

# ``part_of`` existential relation: some OAK setups fold this into the closure
# (e.g. the benchmark's is_a + part_of variant). We keep it as a distinct
# typed edge so the walker can choose which predicate set to follow.
edge PartOf {
    has predicate: str = "part_of";
}

# The "ubergraph-style" cross-ontology edge: asserted in a foreign ontology
# but terminating at our anchor term. Walking it without a prefix filter
# inflates the closure — exactly the false-accept pitfall called out in the
# issue. Kept as its own edge so the walker can demonstrate the over-return.
edge CrossOntologySubClassOf {
    has source_ontology: str = "";
}

# ---------------------------------------------------------------------------
# Walker: descend from a Term, accumulating every reachable Term id.
#
# This is the OAK ``reachable_from`` / ``descendants`` closure pattern.
# Cycle policy: jac 0.36.1 walkers have no built-in visited-set, so the guard
# set is carried explicitly on the walker (preserved domain logic — see §2
# of the idiomize contract). Cold vs warm behavior is observable in the
# report (cold prints per-step work; warm is just the cached answer).
# ---------------------------------------------------------------------------

walker DescendantClosure {
    has anchor_id: str = "";
    has follow_part_of: bool = False;
    has allow_foreign: bool = False;
    has guard: set[str] = set[str]();
    has tally: dict[str, int] = {};

    can start with Root entry {
        # Find the anchor term and begin the closure from there.
        target = [t for t in [-->] if isinstance(t, Term) and t.id == self.anchor_id];
        if len(target) == 0 {
            print(f"anchor {self.anchor_id} not found");
            disengage;
        }
        visit target[0];
    }

    can descend with Term entry {
        # Cycle guard: never re-enter a term we've already expanded.
        if here.id in self.guard {
            visit [-->];
            return;
        }
        self.guard.add(here.id);
        # Record one work unit so the demo can count "closure cost".
        self.tally[here.id] = self.tally.get(here.id, 0) + 1;

        # Predicate-set selection (mirrors is_a vs is_a+part_of).
        targets: list = [here->:IsA:->];
        if self.follow_part_of {
            targets = targets + [here->:PartOf:->];
        }

        # Scope policy: cross-ontology edges inflate the closure unless the
        # caller opts in (ubergraph "over-return" pitfall).
        if not self.allow_foreign {
            targets = [t for t in targets if t.ontology == here.ontology];
        }

        visit targets;
    }
}

# ---------------------------------------------------------------------------
# Walker: report a simple cold/warm comparison for a chosen adapter profile.
# It walks the same anchor twice to mimic the benchmark's "Cold" then
# "Warm" columns (the second pass costs nothing extra in this demo because
# the graph is already in memory — analogous to a warmed adapter cache).
# ---------------------------------------------------------------------------

walker AdapterBenchmark {
    has profile_name: str = "";
    has anchor_id: str = "";
    has follow_part_of: bool = False;
    has allow_foreign: bool = False;
    has cold_size: int = 0;
    has warm_size: int = 0;

    can start with Root entry {
        print(f"--- adapter profile: {self.profile_name} ---");

        # Cold pass.
        cold = DescendantClosure(
            anchor_id=self.anchor_id,
            follow_part_of=self.follow_part_of,
            allow_foreign=self.allow_foreign,
        );
        root spawn cold;
        self.cold_size = len(cold.tally);
        print(f"  cold closure: {self.cold_size} reachable terms");

        # Warm pass — a *new* walker with the same policy is dispatched to
        # measure the "second call" column. In a real adapter this is where
        # the cache pays off; in this in-memory demo the warm pass is just a
        # fresh traversal of the same graph.
        warm = DescendantClosure(
            anchor_id=self.anchor_id,
            follow_part_of=self.follow_part_of,
            allow_foreign=self.allow_foreign,
        );
        root spawn warm;
        self.warm_size = len(warm.tally);
        print(f"  warm closure: {self.warm_size} reachable terms");
        print(f"  closure cost (cold): {self.cold_size} term-visits");
        print(f"  closure cost (warm): {self.warm_size} term-visits");

        scope_note = "single-ontology" if not self.allow_foreign else "merged (prefix-filter required!)";
        print(f"  scope: {scope_note}");
    }
}

# ---------------------------------------------------------------------------
# Demo graph
# ---------------------------------------------------------------------------

with entry {
    # GO-style cellular_component subtree (the anchor from the issue).
    cc_root = Term(id="GO:0005575", label="cellular_component", ontology="GO");
    cc_a = Term(id="GO:0005737", label="cytoplasm", ontology="GO");
    cc_b = Term(id="GO:0005829", label="cytosol", ontology="GO");
    cc_c = Term(id="GO:0005840", label="ribosome", ontology="GO");
