"""Sync dependency graph: model sync files as nodes, depends_on as typed
edges, and walk the DAG to print topological order and catch cycles.

The original drt-hub/drt issue #426 asks for a declarative dependency
graph between sync files so that ``drt run --all`` can topologically
order execution and ``drt validate`` can reject cycles. Here we model
that scenario natively in Jac: a ``Sync`` node archetype carries the
file name and an ``executed`` flag, a ``DependsOn`` typed edge carries
the declared dependency, and a ``Scheduler`` walker does the
topological traversal with explicit cycle detection (because walkers
in jac 0.36.1 do not dedupe visited nodes on their own).
"""

node Sync {
    has title: str = "";
    has executed: bool = False;
}

edge DependsOn {
    has weight: int = 1;
}

walker Scheduler {
    has order: list[str] = [];
    has cycle_target: str = "";

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can order_sync with Sync entry {
        if here.executed {
            if self.cycle_target != "" {
                print(f"CYCLE detected at {here.title}");
                disengage;
            }
            visit [->:DependsOn:->];
        } else {
            here.executed = True;
            self.order.append(here.title);
            visit [->:DependsOn:->];
        }
    }
}

walker DryRun {
    has layers: list[list[str]] = [];
    has seen: list[str] = [];

    can start with Root entry {
        self.layers.append([]);
        visit [->:DependsOn:->];
    }

    can lay_out with Sync entry {
        if here.title in self.seen {
            return;
        }
        self.seen.append(here.title);
        self.layers.append([here.title]);
        visit [->:DependsOn:->];
    }
}

with entry {
    companies = Sync(title="company_lookup.yaml");
    contacts = Sync(title="contacts.yaml");
    deals = Sync(title="deals.yaml");
    reports = Sync(title="reports.yaml");

    root +>:DependsOn:+> companies;
    companies +>:DependsOn:+> contacts;
    contacts +>:DependsOn:+> deals;
    deals +>:DependsOn:+> reports;

    print("=== topological execute order ===");
    sched = Scheduler();
    root spawn sched;
    print("order: " + str(sched.order));

    print("=== --graph dry-run layout ===");
    graph = DryRun();
    root spawn graph;
    print("levels: " + str(graph.layers));
}

