"""Hiking trail: chained waypoints from trailhead to summit, tallied by a hiker."""

node Trailhead {
    has label: str = "Trailhead";
}

node Waypoint {
    has marker: int = 0;
}

node Summit {
    has label: str = "Summit";
}

walker Hiker {
    has stop_count: int = 0;

    can start with Root entry {
        print("Setting out on the trail");
        visit [-->];
    }

    can begin with Trailhead entry {
        print(f"Trail begins at {here.label}");
        visit [-->];
    }

    can tally with Waypoint entry {
        self.stop_count += 1;
        print(f"Stop {self.stop_count}");
        visit [-->];
