node GraphItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Artifact(GraphItem) {
    has category: str = "";
}

node Revision(GraphItem) {
    has revision_number: int = 0;
}

edge DependsOn {
    has tier: int = 0;
    has reason: str = "";
}

walker ReachabilityAudit {
    has max_depth: int = 8;
    has depth: int = 0;
    has visited_titles: list[str] = [];
    has incident_lookups: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
