        title="Platform",
        year=2024,
        category="runtime"
    );
    api = Artifact(
        title="Public API",
        year=2024,
        category="interface"
    );
    release = Revision(
        title="Release 7",
        year=2025,
        revision_number=7,
        available=False
    );

