}

node AuditPayload(Boundary) {
    has consumer: str = "";
}

node PublicErrorWrapper(Boundary) {
    has classification: str = "";
}

node SSEPayload(Boundary) {
    has channel: str = "";
}

# --- Typed edges (relationship carries meaning) ------------------------------

edge Contains { }

edge DeliveredTo { }

# --- The scrub policy --------------------------------------------------------

node RedactionPolicy {
    has name: str = "OperatorPolicy";
    has forbidden_fields: list[str] = [
        "password", "secret", "token", "api_key",
        "authorization", "cookie", "credentials", "embedding", "prompt",
    ];
    has max_bytes: int = 1024;
    has snapshot_count: int = 0;
    has redaction_count: int = 0;
    has cycle_count: int = 0;

    def scrub_text(text: str) -> str {
        if text == "" {
            return text;
        }
        lower = text.lower();
        if "bearer " in lower or "sk-" in lower {
            self.redaction_count += 1;
            return "[REDACTED-TOKEN]";
        }
        return text;
    }

    def scrub_value(value: str, field: str) -> str {
        lower_field = field.lower();
        for forbidden in self.forbidden_fields {
            if forbidden in lower_field {
                self.redaction_count += 1;
                return "[FORBIDDEN-FIELD]";
            }
        }
        return self.scrub_text(value);
    }

    def snapshot(value: str) -> dict[str, str | int] {
        self.snapshot_count += 1;
        result: dict[str, str | int] = {};
        raw_bytes = len(value);
        if raw_bytes <= self.max_bytes {
            result["value"] = value;
            result["truncated"] = 0;
        } else {
            preview = value[:self.max_bytes];
            result["value"] = preview;
            result["truncated"] = 1;
            result["original_bytes"] = raw_bytes;
