# Entity archetypes
# ---------------------------------------------------------------------------

node RepoFile {
    has path: str = "";
    has content_hash: str = "";
    has available: bool = True;
}

node RustItem {
    has kind: str = "";
    has name: str = "";
    has available: bool = True;
}

node Finding {
    has summary: str = "";
    has confidence: float = 0.0;
    has stale: bool = False;
    has available: bool = True;
}

node Analyzer {
    has name: str = "";
    has available: bool = True;
}

# ---------------------------------------------------------------------------
# Typed edge archetypes
# ---------------------------------------------------------------------------

edge Contains {
    has line: int = 0;
