# Guests at our hotel walk past service desks (spa session, room-service dinner, express laundry); each desk adds its price to whichever guest is currently passing by. Print each charge as it happens and what each guest owes at checkout.
"""Hotel service desks: guests walk past desks and each desk charges them.

Each desk is a node; a guest walker moves from desk to desk and accumulates
charges, printing every charge and the running total at checkout.
"""

node Desk {
    has name: str = "";
    has price: float = 0.0;
}

walker Guest {
    has guest_name: str = "Guest";
    has total_owed: float = 0.0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can pass_desk with Desk entry {
        self.total_owed += here.price;
        print(f"{self.guest_name} charged ${here.price} for {here.name} (running total: ${self.total_owed})");
        visit [-->];
    }
}

with entry {
    spa = Desk(name="spa session", price=45.0);
    dinner = Desk(name="room-service dinner", price=28.5);
    laundry = Desk(name="express laundry", price=12.0);

    root ++> spa ++> dinner ++> laundry;

    alice = Guest(guest_name="Alice");
    root spawn alice;
    print(f"Checkout for {alice.guest_name}: owes ${alice.total_owed}");

    bob = Guest(guest_name="Bob");
    root spawn bob;
    print(f"Checkout for {bob.guest_name}: owes ${bob.total_owed}");
}

