# Simulate contact tracing from patient zero through a network of contacts. The outbreak should spread wave by wave: everyone exposed in a wave gets contacted before the next wave starts. Print the contact sequence so the level-by-level order is evident.
"""Contact tracing: spread an outbreak wave by wave through a contact network.

Patient zero infects every direct contact in the first wave; all newly
exposed people form the next wave; only when a wave is fully processed
do we move on. The walker visits level-by-level (breadth-first), so the
contact sequence reveals the wave ordering.
"""

node Person {
    has name: str = "";
    has infected: bool = False;
    has wave: int = 0;
}

edge Contact {
    has strength: str = "household";
}

walker Tracer {
    has current_wave: int = 0;
    has frontier: list[Person] = [];

    can start with Root entry {
        # Seed patient zero on the first Person reachable from root.
        visit [-->];
    }

    can ignite with Person entry {
        # First person encountered is patient zero.
        here.infected = True;
        here.wave = 0;
        self.frontier = [here];
        print(f"Wave 0 -> patient zero: {here.name}");
        self.current_wave = 0;
        # Spread one wave at a time until no new infections occur.
        while len(self.frontier) > 0 {
            self.current_wave += 1;
            next_frontier: list[Person] = [];
            for person in self.frontier {
                new_cases = self.infect_wave(person, self.current_wave);
                next_frontier.extend(new_cases);
            }
            self.frontier = next_frontier;
        }
        print("Outbreak contained: no further contacts to trace.");
        disengage;
    }

    def infect_wave(person: Person, wave_no: int) -> list[Person] {
        newly: list[Person] = [];
        for neighbor in [person->:Contact:->] {
            if not neighbor.infected {
                neighbor.infected = True;
                neighbor.wave = wave_no;
                print(
                    f"Wave {wave_no} -> {person.name} contacts {neighbor.name}"
                );
                newly.append(neighbor);
            }
        }
        return newly;
    }
}

with entry {
    p0 = Person(name="Alice");
    p1 = Person(name="Bob");
    p2 = Person(name="Cleo");
    p3 = Person(name="Diego");
    p4 = Person(name="Esha");
    p5 = Person(name="Finn");
    p6 = Person(name="Gita");
    p7 = Person(name="Hugo");

    # Wave 1 contacts of Alice (patient zero).
    p0 +>:Contact(strength="household"):+> p1;
    p0 +>:Contact(strength="work"):+> p2;
    p0 +>:Contact(strength="work"):+> p3;

    # Wave 2 contacts exposed by Bob/Cleo/Diego.
    p1 +>:Contact(strength="household"):+> p4;
    p2 +>:Contact(strength="gym"):+> p5;
    p3 +>:Contact(strength="cafe"):+> p6;

    # Wave 3 contacts.
    p4 +>:Contact(strength="neighbor"):+> p7;
    p6 +>:Contact(strength="neighbor"):+> p7;

    root ++> p0;
    root spawn Tracer();
}

