"""Tiny dungeon crawler: chain of room nodes, one holds the treasure, a hunter
walker counts visited rooms and disengages the moment it reaches the vault."""

node Room {
    has name: str = "";
    has is_vault: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->];
    }

    can explore with Room entry {
        self.rooms_checked += 1;
        print(f"Entering room: {here.name} (total visited: {self.rooms_checked})");
        if here.is_vault {
            print(f"Treasure found in '{here.name}'! Hunter stops the search.");
            disengage;
        }
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    entrance = Room(name="Entrance");
    hallway = Room(name="Hallway");
    armory = Room(name="Armory");
    vault = Room(name="Vault", is_vault=True);
    forbidden_hall = Room(name="Forbidden Hall");
    dragon_lair = Room(name="Dragon Lair");

    root ++> entrance
        ++> hallway
        ++> armory
        ++> vault
        ++> forbidden_hall
        ++> dragon_lair;

    hunter = Hunter();
    root spawn hunter;

    print(f"Hunter checked {hunter.rooms_checked} room(s) before disengaging.");
}

