node Person {
    has pid: str;
}

edge ParentOf {}

obj ArchiveStore {
    has people: dict[str, Person] = {};
}

walker AncestorWalk {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];
    has limit: int = 0;
    has depth: int = 0;

    can step with Person entry {
        if here.pid in self.claimed { skip; }
        self.claimed[here.pid] = True;
