        root ++> nd;
        g.contacts[cid] = nd;
    }
    for (a, b) in relation_edges {
        na = g.contacts.get(a, None);
        nb = g.contacts.get(b, None);
        if na is not None and nb is not None { na +>:RelatedTo:+> nb; }
