    has fed_dtype: str = "";          # dtype the caller hands in
    has imposed_dtypes: list[str] = []; # dtypes the eager direct consumers impose
    has published_dtype: str = "";    # what the type analysis says is effective
}

node Function {
    has name: str = "";
    has parameters: list = [];        # bookkeeping only; edges carry structure
}

# Typed edges: a Parameter belongs to a Function; a Consumer reads a Parameter.
edge ParamOf { }
edge Reads { }

walker CoercionAuditor {
    has conflicts: int = 0;
    has singles: int = 0;
    has visited: list = [];

    can start with Root entry {
        visit [-->];
    }

    # A Function exposes its parameters via the typed ParamOf edge.
    can descend with Function entry {
        visit [->:ParamOf:->];
    }

    # One union ability for Parameter handles both the read-traversal and the
    # report step. Shared surface (name, fed_dtype, imposed_dtypes, published_dtype)
    # is declared on Parameter; the ability touches only those fields.
    can audit with Parameter entry {
        if here.name not in self.visited {
            self.visited.append(here.name);
            # Cascade invalidation: walk every consumer that Reads this param.
            visit [here->:Reads:->];
            # Classify the eager-effective dtype.
            if len(here.imposed_dtypes) > 1 {
                self.conflicts += 1;
                print(
                    f"[DECLINE] {here.name}: consumers disagree -> "
                    f"{here.imposed_dtypes}; published={here.published_dtype}"
                );
            } else {
                self.singles += 1;
                marker = "AGREE" if here.published_dtype == here.fed_dtype else "DRIFT";
                print(
                    f"[{marker}] {here.name}: published={here.published_dtype}"
                );
            }
        }
    }
}

# --- Demonstration wiring ---------------------------------------------------

with entry {
    f = Function(name="hybrid_kernel");
    p_a = Parameter(
        name="alpha",
        fed_dtype="float32",
        imposed_dtypes=["float32"],
        published_dtype="float32"
    );
    p_b = Parameter(
        name="beta",
        fed_dtype="float64",
        imposed_dtypes=["float32", "float64"],
        published_dtype="float64"
    );
    p_c = Parameter(
        name="gamma",
        fed_dtype="int32",
        imposed_dtypes=["int32"],
        published_dtype="int32"
    );

    root ++> f;
    f +>:ParamOf:+> p_a;
    f +>:ParamOf:+> p_b;
    f +>:ParamOf:+> p_c;

    # Direct consumers: each Reads exactly one parameter. Plural readers of
    # the same parameter would attach extra Reads edges to it.
    consumer_x = Function(name="consumer_x");
