# Health-inspect a restaurant kitchen line (grill, fryer, cold prep): check each station's temperature, flagging anything above 40 C as a violation, and separately log every station visit. Both checks must run at every station.
"""Health-inspect a restaurant kitchen line: grill, fryer, cold prep.

Two inspections run at every station:
  1. Temperature check -- flag any station above 40 C as a violation.
  2. Visit log -- record every station the inspector passes.

A plain visitor (delivery driver) does not trigger either inspection,
matching the union-trigger reference pattern.
"""

node Station {
    has station_name: str = "";
    has temperature: float = 0.0;
}

walker HealthInspector {
    has inspector_badge: str = "";
    has visited_count: int = 0;
    has violations: list[str] = [];

    can start with Root entry {
        print(f"Inspector {self.inspector_badge} beginning kitchen walk");
        visit [-->];
    }

    can inspect with Station entry {
        self.visited_count += 1;
        stamp = f"{self.inspector_badge}@{here.station_name}";
        if here.temperature > 40.0 {
            self.violations.append(stamp);
            print(f"[VIOLATION] {here.station_name} at {here.temperature} C");
        } else {
            print(f"  ok       {here.station_name} at {here.temperature} C");
        }
        visit [-->];
    }
}

walker DeliveryDriver {
    has driver_name: str = "";

    can start with Root entry {
        print(f"Driver {self.driver_name} passing through the kitchen");
        visit [-->];
    }

    # Matches no Station ability, so the driver's pass is silent
    # -- no temperature check, no visit log on the inspector side.
    can pass_through with Station entry {
        visit [-->];
    }
}

with entry {
    grill = Station(station_name="Grill", temperature=180.0);
    fryer = Station(station_name="Fryer", temperature=165.0);
    cold_prep = Station(station_name="Cold Prep", temperature=4.0);
    root ++> grill ++> fryer ++> cold_prep;

    inspector = HealthInspector(inspector_badge="H-7");
    root spawn inspector;
    print(
        f"inspector visited {inspector.visited_count} stations, "
        f"violations: {inspector.violations}"
    );

    driver = DeliveryDriver(driver_name="Diego");
    root spawn driver;
}

