# Run a moderation sweep over game accounts: member accounts are audited normally, admin accounts get their reputation boosted by 5, and the welcome desk greets every bot passing through no matter what kind of walker it is.
"""Moderation sweep over game accounts.

Member accounts are audited normally, admin accounts get their
reputation boosted by 5, and the welcome desk greets every bot passing
through no matter what kind of walker it is.
"""

node Account {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Member(Account) {
    has reputation: int = 0;
    has violation_count: int = 0;

    def audit() -> str {
        verdict = "CLEAN" if self.violation_count == 0 else "FLAGGED";
        return f"[{verdict}] member {self.title} rep={self.reputation}";
    }
}

node Admin(Account) {
    has reputation: int = 0;
    has violation_count: int = 0;

    def audit() -> str {
        boosted = self.reputation + 5;
        verdict = "CLEAN" if self.violation_count == 0 else "FLAGGED";
        return f"[{verdict}] admin {self.title} rep={boosted} (boosted +5)";
    }
}

# The welcome desk greets every bot, regardless of which walker is
# passing through. A union trigger with the walker base types handles
# every kind at once.
node WelcomeDesk {
    has desk_name: str = "Lobby";

    can greet with Moderator | Auditor | Greeter entry {
        print(f"Welcome desk '{self.desk_name}' greets {visitor.kind} walker");
        visitor.greetings += 1;
    }
}

walker Moderator {
    has kind: str = "moderator";
    has greetings: int = 0;

    can start with Root entry {
        print("Moderator begins sweep");
        visit [-->];
    }

    can sweep with WelcomeDesk entry {
        visit [-->];
    }

    can audit_account with Member | Admin entry {
        print(here.audit());
        visit [-->];
    }
}

walker Auditor {
    has kind: str = "auditor";
    has greetings: int = 0;

    can start with Root entry {
        print("Auditor begins sweep");
        visit [-->];
    }

    can sweep with WelcomeDesk entry {
        visit [-->];
    }

    can audit_account with Member | Admin entry {
        print(here.audit());
        visit [-->];
    }
}

walker Greeter {
    has kind: str = "greeter";
    has greetings: int = 0;

    can start with Root entry {
        print("Greeter begins sweep");
        visit [-->];
    }

    can sweep with WelcomeDesk entry {
        visit [-->];
    }

    can audit_account with Member | Admin entry {
        print(here.audit());
        visit [-->];
    }
}

with entry {
    lobby = WelcomeDesk(desk_name="Front Desk");
    root ++> lobby
        ++> Member(title="alice", year=2021, reputation=12, violation_count=0)
        ++> Admin(title="bob", year=2020, reputation=40, violation_count=1)
        ++> Member(title="carol", year=2022, reputation=5, violation_count=2);

    mod = Moderator();
    root spawn mod;

    aud = Auditor();
    root spawn aud;

    greet = Greeter();
    root spawn greet;

    print(
        f"greetings -> moderator={mod.greetings}, "
        f"auditor={aud.greetings}, greeter={greet.greetings}"
    );
}

