            print(
                f"Summit reached — only {self.stop} of {self.expected} "
                f"waypoints passed"
            );
        }
        disengage;
    }
}

with entry {
    root ++> Trailhead()
        ++> Waypoint(name="Creek Crossing")
        ++> Waypoint(name="Pine Ridge")
        ++> Waypoint(name="Switchback Turn")
        ++> Summit();
    root spawn Hiker(expected=3);
}

