def make_graph(parent_child_edges: list[list[str]]) -> dict[str, Group] {
  store: dict[str, Group] = {};
  for e in parent_child_edges {
    pg: str = e[0];
    cg: str = e[1];
    if pg not in store {
      pnd = Group(gid=pg);
      root ++> pnd;
      store[pg] = pnd;
    }
    if cg not in store {
      cnd = Group(gid=cg);
      root ++> cnd;
      store[cg] = cnd;
