    has status: str = "PENDING";
}

node Commit {
    has sha: str = "";
    has subject: str = "";
    has version_code: int = 0;
    has bumped: bool = False;
}

node BuildFile {
    has path: str = "";
    has current_version_code: int = 0;
}

edge RunsCommit { has order: int = 0; }
edge TouchesFile { }

walker DeployAuditor {
    has findings: list[str] = [];
    has visited: list[str] = [];

    can start with Root entry {
        print("Deploy Site audit begins");
        visit [->:RunsCommit:->];
    }

    can audit_workflow with Workflow entry {
        if not (here.name in self.visited) {
            self.visited.append(here.name);
        }
        print(f"[workflow] {here.name} -> {here.status}");
        visit [->:RunsCommit:->];
    }

    can audit_commit with Commit entry {
        key = f"commit:{here.sha}";
        if key in self.visited {
            visit [-->] else { disengage; }
        }
        self.visited.append(key);

        verdict = "OK" if here.bumped else "STALE";
        note = (f"[commit:{verdict}] {here.sha[:7]} {here.subject} "
                f"(versionCode={here.version_code})");
        print(note);
        self.findings.append(note);

        visit [->:TouchesFile:->];
    }

    can audit_file with BuildFile entry {
        key = f"file:{here.path}";
        if key in self.visited {
            visit [-->] else { disengage; }
        }
        self.visited.append(key);

        ok = here.current_version_code < 100;
        verdict = "OK" if ok else "COLLISION";
        line = (f"[file:{verdict}] {here.path} "
                f"versionCode={here.current_version_code}");
        print(line);
        self.findings.append(line);
        if not ok {
            report_line = (f"ACTION: bump versionCode above "
                           f"{here.current_version_code} in {here.path}");
            print(report_line);
            self.findings.append(report_line);
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    deploy = Workflow(name="Deploy Site (#57)", status="FAILED");
    fix_commit = Commit(
        sha="6a6244a31ff92fb14aa588a2f92700b0625fc85a",
        subject="fix(ci): resolve ty panic and core type diagnostics",
        version_code=42,
        bumped=True,
    );
    gradle_file = BuildFile(
        path="app/build.gradle.kts",
        current_version_code=42,
    );

    root +>:RunsCommit(order=1):+> deploy;
    deploy +>:RunsCommit(order=2):+> fix_commit;
    fix_commit +>:TouchesFile:+> gradle_file;

    auditor = DeployAuditor();
    root spawn auditor;

    print("\n--- audit findings ---");
    for line in auditor.findings {
        print(line);
    }
}

