node Tag {
    has name: str = "";
    has name_fold: str = "";
    has depth: int = 0;
}

node File {
    has title: str = "";
}

edge SubtagOf {
    has path_segment: str = "";
}

edge TaggedWith {
    has applied_at: str = "";
}

walker TagAuditor {
    has folder: str = "";
    has prefix: str = "";
    has limit: int = 50;

    can start with Root entry {
        visit [-->];
    }

    can audit with Tag entry {
        if self.prefix != "" and not here.name_fold.startswith(self.prefix) {
            visit [-->];
            return;
        }
        if self.folder != "" and not here.name_fold.startswith(self.folder) {
            visit [-->];
            return;
        }
        direct_count = 0;
        for te in [->:TaggedWith:->] {
            _ = te;
            direct_count += 1;
        }
        descendant_count = direct_count;
        prefix_self = here.name_fold + "/";
        for te in [->:TaggedWith:->] {
            _ = te;
            descendant_count += 1;
        }
        print(f"tag={here.name} direct={direct_count} descendant={descendant_count}");
        visit [-->];
    }
